INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C1','kor',3,2,'u5',2,'낱말을 다루는 힘 — 이 단원에서 배울 두 가지는 기준에 따라 낱말 나누기(낱말의 종류와 특징)와 국어사전 쓰기(낱말을 찾고 글 읽기)이며, 둘 다 낱말을 다루는 힘을 기르는 일임',ARRAY['[4국04-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C2','kor',3,2,'u5',2,'모르는 낱말을 만났을 때 — 글을 읽다가 모르는 낱말이 나오면 그냥 건너뛰지도, 한 낱말 때문에 읽기를 멈추지도 않고, 앞뒤를 살펴 짐작하며 읽은 뒤에 국어사전에서 확인함',ARRAY['[4국04-02]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C3','kor',3,2,'u5',2,'이름을 나타내는 낱말 — “이것이 무엇이다”의 ‘무엇’ 쪽에 들어가는 낱말(사물함·손잡이·계단·바구니)',ARRAY['[4국04-02]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C4','kor',3,2,'u5',2,'움직임을 나타내는 낱말 — “무엇을 한다”의 ‘한다’ 쪽에 들어가는 낱말(닦다·옮기다·두드리다·접다·심다)',ARRAY['[4국04-02]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C5','kor',3,2,'u5',2,'성질이나 상태를 나타내는 낱말 — “어떠하다”의 ‘어떠하다’ 쪽에 들어가는 낱말(비좁다·환하다·매끈하다·묵직하다)',ARRAY['[4국04-02]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C6','kor',3,2,'u5',2,'문장에 넣어 읽어 종류 가리기 — 낱말만 보고 외우는 것이 아니라 “이것이 ○○이다 / ○○을 한다 / ○○이 어떠하다” 틀에 넣어 소리 내어 읽어 보고 어울리는 쪽을 찾음',ARRAY['[4국04-02]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C7','kor',3,2,'u5',2,'모양이 닮아도 종류가 다를 수 있음 — ‘웃음’과 ‘웃다’, ‘잠’과 ‘자다’처럼 모양이 닮아도 하나는 이름, 하나는 움직임을 나타낼 수 있으며 둘 다 바른 말임',ARRAY['[4국04-02]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C8','kor',3,2,'u5',2,'낱말의 종류를 아는 쓸모 — 종류의 이름을 외우는 것이 목표가 아니라, 낱말을 보고 어떤 말인지 알아보아 기준을 정해 나누고 사전에서 찾고 하려는 말을 또렷하게 하는 데 씀',ARRAY['[4국04-02]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C9','kor',3,2,'u5',4,'바뀌는 부분과 바뀌지 않는 부분 — 접고·접으니·접으면·접어서에서 앞쪽 ‘접’은 그대로이고 뒤쪽만 문장에 따라 바뀜',ARRAY['[4국04-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C10','kor',3,2,'u5',4,'모양이 바뀌는 낱말과 그대로인 낱말 — 움직임과 성질·상태를 나타내는 낱말은 문장에 쓰일 때 모양이 바뀌고, 이름을 나타내는 낱말은 뒤에 붙는 말이 달라져도 낱말 자체는 그대로임',ARRAY['[4국04-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C11','kor',3,2,'u5',4,'사전에 대표 모양 하나만 싣는 까닭 — 닦고·닦으니·닦아서·닦았다 …처럼 낱말 하나에 모양이 너무 많아 다 실으면 사전이 몇 배로 두꺼워지므로 대표 모양 하나만 실음(틀린 말이라서·빠뜨려서가 아님)',ARRAY['[4국04-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C12','kor',3,2,'u5',4,'기본형 만들기 — 바뀌지 않는 부분을 찾아 ‘-다’를 붙임(닦으니 → 닦 + 다 → 닦다); 이렇게 만든 대표 모양을 기본형이라 함',ARRAY['[4국04-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C13','kor',3,2,'u5',4,'바뀐 모양은 틀린 말이 아님 — 기본형은 사전에 실을 때 고른 대표 모양일 뿐이며, ‘접어서’·‘닦으니’는 문장에 알맞게 모양이 바뀐 것이지 틀린 말이 아님(사전에 없다고 틀린 말이 되지 않음)',ARRAY['[4국04-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C14','kor',3,2,'u5',6,'나누기 전에 기준을 먼저 정하기 — 낱말을 여럿 놓고 나눌 때 가장 먼저 할 일은 무엇을 보고 나눌지, 곧 기준을 정하는 것임(낱말마다 정해진 칸이 하나 있는 것이 아님)',ARRAY['[4국04-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C15','kor',3,2,'u5',6,'기준이 바뀌면 결과도 바뀜 — 같은 낱말이라도 종류로 나누면 셋·셋·셋, 모양이 바뀌는가로 나누면 여섯·셋처럼 나뉜 칸의 수와 든 낱말이 달라지며, 그 까닭은 낱말이 아니라 기준이 달라졌기 때문임',ARRAY['[4국04-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C17','kor',3,2,'u5',8,'글자의 짜임 — 글자 하나를 첫 자음자·모음자·받침으로 나눔(손 → ㅅ · ㅗ · ㄴ)',ARRAY['[4국04-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C18','kor',3,2,'u5',8,'첫 자음자의 차례 — 국어사전은 첫 자음자 차례(ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ)로 낱말을 묶어 실음',ARRAY['[4국04-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C19','kor',3,2,'u5',8,'모음자의 차례 — 첫 자음자가 같으면 모음자 차례(ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ)로 봄 — ㅏ가 맨 앞, ㅣ가 맨 뒤',ARRAY['[4국04-02]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C20','kor',3,2,'u5',8,'받침의 차례 — 첫 자음자와 모음자가 같으면 받침이 없는 글자가 먼저 실리고, 그다음 받침이 있는 글자가 ㄱ · ㄴ · ㄷ · ㄹ … 차례로 실림',ARRAY['[4국04-02]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C21','kor',3,2,'u5',8,'첫 글자가 같으면 다음 글자 — 첫 글자가 같으면 두 번째 글자를, 그것도 같으면 세 번째 글자를 같은 방법(첫 자음자 → 모음자 → 받침)으로 봄 — 낱말의 길이로 정하지 않음',ARRAY['[4국04-02]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C22','kor',3,2,'u5',8,'모양이 바뀐 낱말은 기본형으로 찾기 — ‘찌그러졌고’·‘비좁으니’는 사전에서 그대로 찾을 수 없으니, 사전을 펴기 전에 기본형(찌그러지다·비좁다)으로 되돌려 찾음',ARRAY['[4국04-02]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C23','kor',3,2,'u5',8,'국어사전에 실린 여러 가지 — 국어사전에는 낱말의 뜻뿐 아니라 소리 내어 읽는 법과 그 낱말이 쓰인 문장도 함께 실려 있음(뜻풀이표가 아님 · 바뀐 모양이 다 실린 것도 아님)',ARRAY['[4국04-02]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C24','kor',3,2,'u5',10,'앞뒤를 살펴 뜻 짐작하기 — 앞뒤 문장을 살피고 아는 다른 말로 바꾸어 읽어 보아 뜻이 통하면 짐작이 가까이 간 것임(‘어귀’ — 처음 오는 사람이 들어오는 곳)',ARRAY['[4국04-02][4국02-03][4국02-06]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C25','kor',3,2,'u5',10,'짐작이 빗나갔을 때 — 짐작한 뜻이 사전의 뜻과 다르면 사전의 뜻으로 고쳐 알고 그 줄을 다시 읽음(글을 못 읽는 것도, 사전이 틀린 것도 아님); 사전마다 뜻풀이 말이 조금씩 달라도 뜻이 같으면 됨',ARRAY['[4국04-02][4국02-03][4국02-06]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C26','kor',3,2,'u5',10,'국어사전을 쓰며 글을 읽으면 좋은 점 — 「학교 안내도를 만드는 법」처럼 낱말의 뜻을 알면 걸리는 곳이 줄어 글의 내용을 정확하게 알 수 있고, 짐작을 확인하며, 아는 낱말이 늘어남(빨리 읽으려는 것이 아님)',ARRAY['[4국04-02][4국02-03][4국02-06]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C27','kor',3,2,'u5',12,'「단서 세 장」 — 낱말 하나를 정해 단서 세 장에 낱말의 종류·사전에서 찾은 뜻·낱말을 괄호로 비운 쓰인 문장을 나누어 적고 짝이 알아맞힘 — 낱말을 그대로 적으면 단서가 아니라 답임',ARRAY['[4국04-02]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C28','kor',3,2,'u5',12,'「내 낱말 공책」 — 생활하다가 뜻이 궁금한 낱말을 모아 낱말(기본형)·종류·사전에서 찾은 뜻·내가 쓴 문장을 적고, 국어사전에 싣는 차례로 늘어놓아 나중에 찾기 쉽게 함',ARRAY['[4국04-02]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C29','kor',3,2,'u5',12,'놀이의 목표 — 단서 놀이의 목표는 이기는 것이 아니라 단서를 보며 낱말을 헤아려 보는 것이며, 못 맞힌 낱말은 사전에서 함께 찾아봄',ARRAY['[4국04-02]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C30','kor',3,2,'u5',12,'‘ㄴ’ 소리가 더해지는 낱말 — 앞 글자에 받침이 있고 뒤 글자가 이·야·여·요·유로 시작하면 ‘ㄴ’ 소리가 더해져 소리 남(한여름 [한녀름] · 논일 [논닐] · 눈인사 [눈닌사]) — 쓸 때는 그대로 씀(기초 다지기)',ARRAY['[4국04-02]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C31','kor',3,2,'u5',12,'뜻을 알아 두면 좋은 우리말 — 아우르다(여럿을 모아 하나로 만들다) · 북돋우다(기운을 더 나게 해 주다) · 여미다(옷깃을 바로 해 단정히 하다) — 셋 다 움직임을 나타내는 낱말(기초 다지기)',ARRAY['[4국04-02]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C32','kor',3,2,'u5',12,'ㅘ · ㅚ · ㅙ가 든 글자 쓰기 — ㅘ(ㅗ+ㅏ) · ㅚ(ㅗ+ㅣ) · ㅙ(ㅗ+ㅐ)는 모음자 두 개가 붙은 것으로, 두 모음자가 어느 쪽에 붙는지 살피며 씀(관찰 · 참외 · 괜찮다, 기초 다지기)',ARRAY['[4국04-02]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C33','kor',3,2,'u5',6,'「낱말을 먹는 아이」 내용과 생각 — 낱말을 먹을 때마다 그 낱말이 나타내는 마음이 되었던 아이가, 낱말을 먹지 않자 마음이 텅 비었다가 모든 낱말을 먹고 「모든 낱말이 나를 도와준다」(내 기분이 어떤지, 내가 누구인지 알게 해 줌)는 것을 깨달음 — 낱말을 ‘먹는다’는 빗댄 표현(『국어』 231~237쪽)',ARRAY['[4국04-02]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C34','kor',3,2,'u5',10,'「아직도 미지의 세계는 남아 있다」 내용 — 지도는 탐험의 성과가 알알이 박혀 있는 결과물이며, 땅 위 → 땅속(암석 지도) → 바다 밑(해저·해류·수온 지도)으로 관심이 넓어졌고 앞으로도 새 지도가 만들어질 것임 — 국어사전으로 낱말의 뜻을 확인하며 읽기(『국어』 242~247쪽)',ARRAY['[4국04-02][4국02-03][4국02-06]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X01','kor',3,'u5',ARRAY['K3-2-u5-C2']::text[],'모르는 낱말은 그냥 건너뛰고 읽어도 글을 다 이해한 것이라고 여긴다','건너뛴 낱말 때문에 무엇을 놓칠까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X02','kor',3,'u5',ARRAY['K3-2-u5-C2','K3-2-u5-C24']::text[],'한 낱말이라도 모르면 읽기를 멈추거나, 모르는 낱말이 나올 때마다 멈추어 사전부터 찾아야 한다고 여긴다','먼저 끝까지 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X03','kor',3,'u5',ARRAY['K3-2-u5-C2','K3-2-u5-C25']::text[],'앞뒤로 짐작만 하고 사전에서 확인하지 않은 채 짐작한 뜻을 그대로 맞는 뜻으로 여긴다','짐작한 다음에 할 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X04','kor',3,'u5',ARRAY['K3-2-u5-C3','K3-2-u5-C4','K3-2-u5-C5']::text[],'이름·움직임·성질이나 상태를 나타내는 낱말을 엇갈리게 가린다','세 가지 틀에 넣어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X05','kor',3,'u5',ARRAY['K3-2-u5-C4','K3-2-u5-C5']::text[],'움직임을 나타내는 낱말과 성질이나 상태를 나타내는 낱말을 섞어, ‘-다’로 끝나면 모두 같은 종류라고 여긴다','무엇을 한다? 어떠하다?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X06','kor',3,'u5',ARRAY['K3-2-u5-C6','K3-2-u5-C7']::text[],'낱말을 문장에 넣어 읽어 보지 않고 소리나 모양이 닮으면 같은 종류라고 여기거나(웃음·웃다), 닮은 둘 가운데 하나는 틀린 말이라고 여긴다','문장에 넣어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X07','kor',3,'u5',ARRAY['K3-2-u5-C8','K3-2-u5-C1']::text[],'낱말의 종류를 배우는 까닭을 종류의 이름을 외우는 것이나 글씨를 빨리 쓰는 것처럼 낱말을 다루는 일과 상관없는 것으로 여긴다','이 단원에서 앞으로 할 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X08','kor',3,'u5',ARRAY['K3-2-u5-C9']::text[],'바뀌지 않는 부분과 바뀌는 부분을 잘못 갈라, 뒤에 붙는 ‘으’·‘어’까지 바뀌지 않는 부분에 넣거나 앞쪽 일부를 뺀다','모든 모양에 빠짐없이 든 곳까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X09','kor',3,'u5',ARRAY['K3-2-u5-C10']::text[],'모든 낱말은 문장에 따라 모양이 바뀐다고 여기거나, 이름을 나타내는 낱말도 뒤에 붙는 말이 달라지면 낱말 자체가 바뀐 것이라고 여긴다','계단이 · 계단을 · 계단은 — 낱말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X10','kor',3,'u5',ARRAY['K3-2-u5-C11']::text[],'사전에 ‘닦으니’ 같은 모양이 실려 있지 않은 까닭을 사전을 만든 사람이 빠뜨려서라고 여긴다','모양이 몇 가지나 될까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X11','kor',3,'u5',ARRAY['K3-2-u5-C12']::text[],'기본형을 만들 때 바뀌는 부분까지 붙인 채 ‘-다’를 붙이거나(닦아다·심으다), ‘-다’가 아닌 다른 모양으로 만든다','바뀌지 않는 부분 + 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X12','kor',3,'u5',ARRAY['K3-2-u5-C13','K3-2-u5-C11']::text[],'기본형만 바른 말이고 사전에 없는 바뀐 모양(접어서·닦으니)은 틀린 말이라고 여긴다','문장에 맞게 바뀐 것뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X13','kor',3,'u5',ARRAY['K3-2-u5-C11','K3-2-u5-C22','K3-2-u5-C23']::text[],'모양이 바뀐 낱말(접어서·찌그러졌고)도 사전에 모두 실려 있어 그대로 찾을 수 있다고 여긴다','사전에는 대표 모양 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X14','kor',3,'u5',ARRAY['K3-2-u5-C14','K3-2-u5-C15']::text[],'낱말마다 들어갈 칸이 하나로 정해져 있다고 여겨, 나누기 전에 기준을 정하지 않고 그 칸부터 찾는다','무엇을 보고 나눌지부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X15','kor',3,'u5',ARRAY['K3-2-u5-C14']::text[],'기준 없이 생각나는 대로 아무렇게나 나누어도 된다고 여긴다','다른 사람이 보고 알 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X16','kor',3,'u5',ARRAY['K3-2-u5-C15']::text[],'같은 낱말을 나눈 결과가 달라지면 앞에서 잘못 나누었기 때문이라고 여겨, 기준이 달라졌다는 것을 놓친다','두 번 나누는 동안 무엇이 바뀌었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X17','kor',3,'u5',ARRAY['K3-2-u5-C16','K3-2-u5-C26']::text[],'글에 나온 일의 까닭이나 내용을 글에 없는 것으로 짐작해 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X18','kor',3,'u5',ARRAY['K3-2-u5-C17']::text[],'글자의 짜임에서 첫 자음자·모음자·받침을 엇갈리게 가른다','천천히 소리 내어 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X19','kor',3,'u5',ARRAY['K3-2-u5-C18']::text[],'첫 자음자의 차례를 틀리게 알아, ㄲ·ㄸ·ㅃ·ㅆ·ㅉ 같은 쌍자음자를 맨 뒤에 놓거나 ㄱ·ㄴ·ㄷ 차례를 엇갈린다','ㄱ 다음은 ㄲ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X20','kor',3,'u5',ARRAY['K3-2-u5-C19']::text[],'첫 자음자가 같을 때 모음자의 차례를 틀리게 안다','ㅏ가 맨 앞, ㅣ가 맨 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X21','kor',3,'u5',ARRAY['K3-2-u5-C20']::text[],'받침이 있는 글자가 받침이 없는 글자보다 먼저 실린다고 여긴다','받침은 없는 쪽이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X22','kor',3,'u5',ARRAY['K3-2-u5-C21']::text[],'첫 글자가 같은 낱말의 차례를 다음 글자가 아니라 낱말의 길이(짧은 것이 먼저)로 정한다','다음 글자를 같은 방법으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X23','kor',3,'u5',ARRAY['K3-2-u5-C22']::text[],'모양이 바뀐 낱말을 바뀐 모양 그대로 사전에서 찾으려 한다','사전을 펴기 전에 할 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X24','kor',3,'u5',ARRAY['K3-2-u5-C23']::text[],'국어사전에는 낱말의 뜻만 적혀 있다고 여긴다','한 낱말 옆에 함께 적힌 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X25','kor',3,'u5',ARRAY['K3-2-u5-C24']::text[],'뜻을 짐작할 때 앞뒤 문장을 살피지 않고 낱말의 소리나 모양만 보고 짐작한다','앞뒤 문장에 실마리가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X26','kor',3,'u5',ARRAY['K3-2-u5-C25']::text[],'짐작한 뜻이 사전의 뜻과 다르면 그 글은 못 읽는다고 여기거나, 내 짐작이 맞고 사전이 틀렸다고 여긴다','사전의 뜻으로 고쳐 알고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X27','kor',3,'u5',ARRAY['K3-2-u5-C25']::text[],'사전마다 뜻풀이의 말이 조금씩 다르면 어느 하나는 틀린 것이라고 여긴다','말이 달라도 뜻이 같으면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X28','kor',3,'u5',ARRAY['K3-2-u5-C26']::text[],'국어사전을 쓰며 글을 읽는 까닭을 글을 더 빨리 읽기 위해서라고 여긴다','두 번째로 읽을 때 무엇이 달라졌나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X29','kor',3,'u5',ARRAY['K3-2-u5-C27']::text[],'단서 카드에 알아맞힐 낱말을 그대로 적거나, 쓰인 문장에서 낱말 자리를 비우지 않는다','단서는 답을 가리킬 뿐 답이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X30','kor',3,'u5',ARRAY['K3-2-u5-C28']::text[],'낱말 공책을 낱말이 긴 차례나 좋아하는 차례로 적거나, 나중에 찾아볼 때 도움이 안 되는 것(그날 날씨 등)을 적는다','나중에 다시 찾아볼 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X31','kor',3,'u5',ARRAY['K3-2-u5-C29']::text[],'낱말 놀이의 목표를 이기는 것으로 여겨 못 맞히면 실패라고 여긴다','단서를 보며 헤아려 보는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X32','kor',3,'u5',ARRAY['K3-2-u5-C30']::text[],'‘ㄴ’ 소리가 더해지는 조건을 잘못 알아, 앞 글자에 받침이 없어도 소리가 더해진다고 여긴다','앞 글자에 받침이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X33','kor',3,'u5',ARRAY['K3-2-u5-C30']::text[],'‘ㄴ’ 소리가 더해져 소리 나는 대로 낱말을 쓴다(한녀름·논닐)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X34','kor',3,'u5',ARRAY['K3-2-u5-C31']::text[],'아우르다·북돋우다·여미다의 뜻을 엇갈리게 안다','어울리는 장면을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X35','kor',3,'u5',ARRAY['K3-2-u5-C32']::text[],'ㅘ·ㅚ·ㅙ를 이루는 두 모음자를 엇갈리게 알아 글자를 틀리게 쓴다(괜·관·외)','ㅗ 옆에 무엇이 붙었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X36','kor',3,'u5',ARRAY['K3-2-u5-C17','K3-2-u5-C18']::text[],'낱말을 찾을 때 첫 자음자 자리의 ‘ㅇ’을 빼고 받침이나 소리 나는 자음으로 찾는다(‘얼음’을 ‘ㄹ’로 시작하는 곳에서 찾음)','첫 글자의 맨 앞 자음자는? ‘ㅇ’도 자음자예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X37','kor',3,'u5',ARRAY['K3-2-u5-C20']::text[],'첫 글자의 받침이 둘 다 있을 때 받침끼리의 차례(ㄱ·ㄴ·ㄷ·ㄹ … ㅇ …)를 모른다(‘강조’를 ‘갈래’보다 먼저 놓음)','받침도 자음자 차례대로 — ㄹ이 먼저일까, ㅇ이 먼저일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X38','kor',3,'u5',ARRAY['K3-2-u5-C23','K3-2-u5-C26']::text[],'국어사전에 뜻이 여러 개 실려 있으면 글의 앞뒤와 상관없이 맨 앞의 뜻을 고르거나 아무 뜻이나 고른다','그 뜻을 문장에 넣어 읽으면 자연스러운가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X39','kor',3,'u5',ARRAY['K3-2-u5-C3']::text[],'이름을 나타내는 낱말은 눈에 보이고 만질 수 있는 물건만이라고 여겨, ‘사랑’·‘행복’·‘기쁨’ 같은 낱말은 이름을 나타내지 않는다고 여긴다','‘무엇이 무엇이다’의 ‘무엇’ 자리에 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X40','kor',3,'u5',ARRAY['K3-2-u5-C33','K3-2-u5-C34']::text[],'글쓴이가 빗대어 나타낸 표현(낱말을 ‘먹는다’, 지도에 성과가 ‘알알이 박혀 있다’)을 글자 그대로 읽어 그 뜻을 놓친다','정말 그런 일이 일어났을까? 무엇을 그렇게 나타냈을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#1','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C2',1,'mc','auto','『국어』 217쪽 「생각 열기」예요. 안내문을 읽는 아이가 곤란해하는 까닭은 무엇인가요?',ARRAY['K3-2-u5-X01','K3-2-u5-X17','K3-2-u5-X28']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 「생각 열기」예요. 안내문을 읽는 아이가 곤란해하는 까닭은 무엇인가요?","options":[{"t":"‘당일’, ‘우천’이라는 낱말의 정확한 뜻을 몰라서","correct":true},{"t":"모르는 낱말은 건너뛰면 되니 곤란할 까닭이 없다","mis":"K3-2-u5-X01"},{"t":"안내문에 체육 대회가 열린다는 말이 없어서","mis":"K3-2-u5-X17"},{"t":"안내문을 빨리 읽지 못해서","mis":"K3-2-u5-X28"}],"explanation":["아이는 「당일? 우천? 무슨 뜻이지?」라고 말했어요.","글자는 다 읽어도 낱말의 뜻을 모르면 내용을 알 수 없어요.","그래서 낱말의 뜻을 알아보는 방법이 필요해요."],"asset":{"type":"passage","lines":["[그림] 국어사전이 꽂힌 책꽂이 앞에서 안내문을 읽는 아이","체육 대회 안내","가을 체육 대회가 열립니다.","당일 우천 시에는 체육관에서 진행합니다.","○○초등학교","[말풍선] 당일? 우천? 무슨 뜻이지?"],"title":"생각 열기 — 『국어』 217쪽","hi":["당일","우천"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#2','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C1',1,'mc','auto','『국어』 219쪽 「무엇을 배울까요」예요. 이 단원에서 공부할 두 가지로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X07','K3-2-u5-X24','K3-2-u5-X01']::text[],false,'{"seq":2,"concept":"K3-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 219쪽 「무엇을 배울까요」예요. 이 단원에서 공부할 두 가지로 알맞은 것은 무엇인가요?","options":[{"t":"기준에 따라 낱말 분류하기, 국어사전 활용하기","correct":true},{"t":"낱말 종류의 이름 외우기, 글씨 빨리 쓰기","mis":"K3-2-u5-X07"},{"t":"국어사전의 뜻풀이를 모두 외우기","mis":"K3-2-u5-X24"},{"t":"모르는 낱말을 건너뛰며 빨리 읽기","mis":"K3-2-u5-X01"}],"explanation":["소단원 1은 「기준에 따라 낱말 분류하기」예요.","소단원 2는 「국어사전 활용하기」예요.","둘 다 낱말을 다루는 힘을 기르는 공부예요."],"asset":{"type":"passage","lines":["소단원 1 — ① 낱말의 종류 알기 ② 형태가 바뀌는 낱말 알기 ③ 기준에 따라 낱말 분류하기","소단원 2 — ① 국어사전에서 낱말을 찾는 방법 알기 ② 국어사전을 활용하며 글 읽기"],"title":"무엇을 배울까요 — 『국어』 219쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#3','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C1',1,'sa','auto','『국어』 218쪽 낱말 알아맞히기 놀이예요. 친구가 설명한 낱말은 무엇일까요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u5-C1","difficulty":1,"kind":"sa","stem":"『국어』 218쪽 낱말 알아맞히기 놀이예요. 친구가 설명한 낱말은 무엇일까요? 한 글자로 쓰세요.","answer":["소"],"explanation":["집에서 기르고, 뿔이 있고, 풀을 먹는 동물이에요.","「음매!」는 소의 울음소리예요.","낱말을 설명하는 말을 잘 들으면 알아맞힐 수 있어요."],"asset":{"type":"passage","lines":["① 카드에 낱말을 쓴다.","② 카드를 모아서 한곳에 놓는다.","③ 뒤집어 놓은 카드에서 뽑은 낱말을 친구들에게 설명한다.","④ 설명을 듣고 낱말을 알아맞힌다.","[말풍선] 동물이야. 옛날부터 사람들이 집에서 길렀대.","[말풍선] 뿔이 있는 경우도 있어. 풀을 먹고 살아. 음매!","[말풍선] 무슨 낱말일까?"],"title":"낱말 알아맞히기 놀이 — 『국어』 218쪽"},"mis":"K3-2-u5-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#4','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C4',1,'blank','auto','‘그리고 뭐 했어?’ 놀이예요. 「그리고 의자에 (     ).」의 빈칸에 알맞은 낱말을 보기에서 고르세요.',ARRAY['K3-2-u5-X04','K3-2-u5-X05']::text[],false,'{"seq":4,"concept":"K3-2-u5-C4","difficulty":1,"kind":"blank","stem":"‘그리고 뭐 했어?’ 놀이예요. 「그리고 의자에 (     ).」의 빈칸에 알맞은 낱말을 보기에서 고르세요.","options":[{"t":"앉았어","correct":true},{"t":"의자","mis":"K3-2-u5-X04"},{"t":"착해","mis":"K3-2-u5-X05"},{"t":"교실","mis":"K3-2-u5-X04"}],"explanation":["이 놀이는 한 일을 차례로 말하는 놀이예요.","의자에 하는 움직임은 「앉았어」예요.","그래서 움직임을 나타내는 낱말을 써야 해요."],"asset":{"type":"passage","lines":["운동장에서 뛰었어.","그리고 축구공을 찼어.","그리고 물을 마셨어.","그리고 의자에 (     ).","그리고 교실로 (     ).","[보기] 멋있어 · 의자 · 돌아갔어 · 교실 · 착해 · 앉았어"],"title":"‘그리고 뭐 했어?’ 놀이 — 『국어』 221쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#5','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C5',2,'blank','auto','‘……은/는 어때?’ 놀이예요. 「멋있으면 내 친구. 내 친구는 (     ).」의 빈칸에 알맞은 낱말을 보기에서 고르세요.',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":5,"concept":"K3-2-u5-C5","difficulty":2,"kind":"blank","stem":"‘……은/는 어때?’ 놀이예요. 「멋있으면 내 친구. 내 친구는 (     ).」의 빈칸에 알맞은 낱말을 보기에서 고르세요.","options":[{"t":"착해","correct":true},{"t":"앉았어","mis":"K3-2-u5-X05"},{"t":"교실","mis":"K3-2-u5-X04"},{"t":"돌아갔어","mis":"K3-2-u5-X05"}],"explanation":["이 놀이는 대상이 어떠한지 이어 말하는 놀이예요.","친구가 어떠한지를 나타내는 말은 「착해」예요.","그래서 성질이나 상태를 나타내는 낱말을 써야 해요."],"asset":{"type":"passage","lines":["사과는 맛있어. 맛있으면 바나나.","바나나는 길어. 길면 기차.","기차는 빨라.","멋있으면 내 친구. 내 친구는 (     ).","빠르면 자동차. 자동차는 (     ).","[보기] 멋있어 · 의자 · 돌아갔어 · 교실 · 착해 · 앉았어"],"title":"‘……은/는 어때?’ 놀이 — 『국어』 221쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#6','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C6',2,'match','auto','『국어』 223쪽 3번이에요. 세 놀이에서 쓴 낱말과 낱말의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u5-C6","difficulty":2,"kind":"match","stem":"『국어』 223쪽 3번이에요. 세 놀이에서 쓴 낱말과 낱말의 종류를 알맞게 이으세요.","pairs":[{"l":"운동장, 축구공, 자전거, 학교, 친구","r":"이름을 나타내는 낱말"},{"l":"뛰다, 차다, 마시다, 먹다, 던지다","r":"움직임을 나타내는 낱말"},{"l":"맛있다, 길다, 빠르다, 뜨겁다, 즐겁다","r":"성질이나 상태를 나타내는 낱말"}],"mis":"K3-2-u5-X04","explanation":["‘……에 가면’ 놀이에서는 볼 수 있는 것의 이름을 말했어요.","‘그리고 뭐 했어?’ 놀이에서는 한 일, 곧 움직임을 말했어요.","‘……은/는 어때?’ 놀이에서는 대상의 성질이나 상태를 말했어요."],"asset":{"type":"passage","lines":["‘……에 가면’ 놀이 — 운동장, 축구공, 자전거, 학교, 친구","‘그리고 뭐 했어?’ 놀이 — 뛰다, 차다, 마시다, 먹다, 던지다","‘……은/는 어때?’ 놀이 — 맛있다, 길다, 빠르다, 뜨겁다, 즐겁다"],"title":"세 놀이에서 쓴 낱말 — 『국어』 222~223쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#7','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C3',2,'mc','auto','『국어』 223쪽 3번 (2)예요. 「울다, 칠판, 무섭다」 가운데에서 이름을 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":7,"concept":"K3-2-u5-C3","difficulty":2,"kind":"mc","stem":"『국어』 223쪽 3번 (2)예요. 「울다, 칠판, 무섭다」 가운데에서 이름을 나타내는 낱말은 무엇인가요?","options":[{"t":"칠판","correct":true},{"t":"울다","mis":"K3-2-u5-X04"},{"t":"무섭다","mis":"K3-2-u5-X04"}],"explanation":["「이것은 칠판이다.」처럼 ‘무엇’ 자리에 넣어 봐요.","「울다」는 움직임, 「무섭다」는 성질이나 상태를 나타내요.","「칠판」은 대상의 이름을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#8','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C4',2,'mc','auto','『국어』 224쪽 4번 (1)이에요. 사진을 보고 떠오른 낱말 가운데에서 움직임을 나타내는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05','K3-2-u5-X06']::text[],false,'{"seq":8,"concept":"K3-2-u5-C4","difficulty":2,"kind":"mc","stem":"『국어』 224쪽 4번 (1)이에요. 사진을 보고 떠오른 낱말 가운데에서 움직임을 나타내는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"날다, 펼치다, 잡다","correct":true},{"t":"날개, 발톱, 깃털","mis":"K3-2-u5-X04"},{"t":"가볍다, 날카롭다, 크다","mis":"K3-2-u5-X05"},{"t":"날다, 날개, 날카롭다","mis":"K3-2-u5-X06"}],"explanation":["「새가 날다」처럼 ‘어찌하다’ 자리에 들어가는 낱말을 찾아요.","날개·발톱·깃털은 이름, 가볍다·날카롭다·크다는 성질이나 상태예요.","「날다」와 「날개」는 모양이 닮았지만 종류가 달라요."],"asset":{"type":"passage","lines":["[사진] 날개를 활짝 펼치고 하늘을 나는 큰 새","날다 · 날개 · 펼치다 · 잡다 · 가볍다","깃털 · 크다 · 날카롭다 · 발톱"],"title":"사진을 보고 떠오르는 낱말 — 『국어』 224쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#9','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C6',2,'ox','auto','‘무엇이 어떠하다’ 틀의 ‘어떠하다’ 자리에 넣어 읽을 수 있는 낱말은 성질이나 상태를 나타내는 낱말이에요.',ARRAY['K3-2-u5-X05']::text[],false,'{"seq":9,"concept":"K3-2-u5-C6","difficulty":2,"kind":"ox","stem":"‘무엇이 어떠하다’ 틀의 ‘어떠하다’ 자리에 넣어 읽을 수 있는 낱말은 성질이나 상태를 나타내는 낱말이에요.","answer":"O","reason_options":[{"t":"「발톱이 날카롭다」처럼 ‘어떠하다’ 자리에 들어가면 성질이나 상태를 나타내요.","correct":true},{"t":"‘-다’로 끝나는 낱말은 모두 움직임을 나타내니 틀에 넣을 필요가 없어요.","mis":"K3-2-u5-X05"}],"mis":"K3-2-u5-X05","explanation":["이름은 ‘무엇이 무엇이다’의 ‘무엇’ 자리에 들어가요.","움직임은 ‘무엇이 어찌하다’의 ‘어찌하다’ 자리에 들어가요.","성질이나 상태는 ‘무엇이 어떠하다’의 ‘어떠하다’ 자리에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_basic#10','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C4',3,'error','auto','『국어』 225쪽 말놀이예요. 「‘움직임을 나타내는 낱말’을 돌아가며 말해 보자. 우리가 운동장에 와 있다고 생각하자. 시작!」 규칙에 맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":10,"concept":"K3-2-u5-C4","difficulty":3,"kind":"error","stem":"『국어』 225쪽 말놀이예요. 「‘움직임을 나타내는 낱말’을 돌아가며 말해 보자. 우리가 운동장에 와 있다고 생각하자. 시작!」 규칙에 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지아: “축구 골대.”","correct":true,"mis_target":"K3-2-u5-X04"},{"t":"도윤: “달리다.”","mis":"K3-2-u5-X04"},{"t":"하린: “던지다.”","mis":"K3-2-u5-X04"}],"explanation":["고른 종류는 「움직임을 나타내는 낱말」이에요.","「달리다」, 「던지다」는 운동장에서 할 수 있는 움직임이에요.","「축구 골대」는 이름을 나타내는 낱말이라 규칙에 맞지 않아요."],"asset":{"type":"passage","lines":["① 이름, 움직임, 성질이나 상태를 나타내는 낱말 가운데 하나를 고른다.","② 상황을 정하고 “시작!”을 외치며 왼쪽이나 오른쪽을 가리킨다.","③ 가리킨 방향으로 한 사람씩 차례대로 낱말을 외친다.","[예] 이름을 나타내는 낱말 · 점심시간 → “젓가락.” “반찬.”","[예] 움직임을 나타내는 낱말 · 운동장 → “달리다.” “던지다.”"],"title":"낱말의 종류를 이용한 말놀이 — 『국어』 225쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#1','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C5',2,'mc','auto','『국어활동』 72쪽이에요. 그림 속 문장에서 성질이나 상태를 나타내는 낱말(△ 표)끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":1,"concept":"K3-2-u5-C5","difficulty":2,"kind":"mc","stem":"『국어활동』 72쪽이에요. 그림 속 문장에서 성질이나 상태를 나타내는 낱말(△ 표)끼리 묶은 것은 무엇인가요?","options":[{"t":"크다, 길다, 짧다, 따뜻하다","correct":true},{"t":"신다, 쓰다, 매다, 끼다","mis":"K3-2-u5-X05"},{"t":"양말, 모자, 단추, 장갑","mis":"K3-2-u5-X04"},{"t":"크다, 두르다, 짧다, 끼다","mis":"K3-2-u5-X05"}],"explanation":["「단추가 크다」, 「목도리가 길다」처럼 ‘어떠하다’ 자리에 들어가는 낱말을 찾아요.","신다·쓰다·매다·끼다·두르다는 움직임(□ 표)이에요.","양말·모자·단추·장갑은 이름(○ 표)이에요."],"asset":{"type":"passage","lines":["외출 준비 시작!","양말을 신다. · 모자를 쓰다. · 단추가 크다.","목도리를 두르다. · 목도리가 길다. · 안경을 쓰다.","신발을 신다. · 신발 끈을 매다. · 신발 끈이 짧다.","장갑을 끼다. · 장갑이 따뜻하다. · 외출 준비 끝!","○ 이름 · □ 움직임 · △ 성질이나 상태"],"title":"그림 속 문장 — 『국어활동』 72쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#2','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C1',2,'mc','auto','『국어』 219쪽 3번이에요. 낱말 알아맞히기 놀이에서 「켜다」를 뽑았다면 어떻게 설명하면 좋을까요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05','K3-2-u5-X29']::text[],false,'{"seq":2,"concept":"K3-2-u5-C1","difficulty":2,"kind":"mc","stem":"『국어』 219쪽 3번이에요. 낱말 알아맞히기 놀이에서 「켜다」를 뽑았다면 어떻게 설명하면 좋을까요?","options":[{"t":"“전등이나 텔레비전을 쓰려고 단추를 눌러 불이 들어오게 하는 거야.”","correct":true},{"t":"“동그랗고 유리로 되어 있어. 불을 밝히는 물건이야.”","mis":"K3-2-u5-X04"},{"t":"“불빛이 환해서 잘 보이는 거야.”","mis":"K3-2-u5-X05"},{"t":"“켜, 켜, 켜!”라고 낱말을 그대로 말해 준다","mis":"K3-2-u5-X29"}],"explanation":["「켜다」는 무엇을 하는 움직임을 나타내요.","첫째 설명은 「전구」, 둘째 설명은 「밝다」에 어울려요.","낱말을 그대로 말하면 설명이 아니라 답을 알려 주는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#3','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C7',3,'mc','auto','「사랑」, 「사랑하다」, 「사랑스럽다」는 각각 어떤 종류의 낱말인가요?',ARRAY['K3-2-u5-X06','K3-2-u5-X04']::text[],false,'{"seq":3,"concept":"K3-2-u5-C7","difficulty":3,"kind":"mc","stem":"「사랑」, 「사랑하다」, 「사랑스럽다」는 각각 어떤 종류의 낱말인가요?","options":[{"t":"사랑 — 이름, 사랑하다 — 움직임, 사랑스럽다 — 성질이나 상태","correct":true},{"t":"셋 다 「사랑」이 들어 있으니 모두 같은 종류","mis":"K3-2-u5-X06"},{"t":"셋 다 마음을 나타내니 모두 성질이나 상태","mis":"K3-2-u5-X06"},{"t":"사랑 — 움직임, 사랑하다 — 이름, 사랑스럽다 — 성질이나 상태","mis":"K3-2-u5-X04"}],"explanation":["「사랑이 크다」에서 「사랑」은 ‘무엇’ 자리에 들어가요.","「동생을 사랑하다」는 ‘어찌하다’, 「강아지가 사랑스럽다」는 ‘어떠하다’ 자리예요.","모양이 닮아도 문장에 넣어 보면 종류가 달라요."],"asset":{"type":"passage","lines":["자랑 · 자랑스럽다","사랑 · 사랑하다 · 사랑스럽다"],"title":"모양이 닮은 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#4','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C3',3,'ox','auto','「행복」, 「기쁨」처럼 눈에 보이지 않고 만질 수 없는 것은 이름을 나타내는 낱말이 될 수 없어요.',ARRAY['K3-2-u5-X39']::text[],false,'{"seq":4,"concept":"K3-2-u5-C3","difficulty":3,"kind":"ox","stem":"「행복」, 「기쁨」처럼 눈에 보이지 않고 만질 수 없는 것은 이름을 나타내는 낱말이 될 수 없어요.","answer":"X","reason_options":[{"t":"「기쁨이 크다」처럼 ‘무엇’ 자리에 들어가니 이름을 나타내는 낱말이에요.","correct":true},{"t":"이름을 나타내는 낱말은 눈에 보이는 물건만 가리켜요.","mis":"K3-2-u5-X39"}],"mis":"K3-2-u5-X39","explanation":["이름을 나타내는 낱말에는 물건 이름만 있는 것이 아니에요.","「행복」, 「기쁨」, 「사랑」도 ‘무엇이 무엇이다’의 ‘무엇’ 자리에 들어가요.","그래서 이름을 나타내는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#5','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C6',3,'mc','auto','「납작하다」가 어떤 종류의 낱말인지 알아보려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X15','K3-2-u5-X04']::text[],false,'{"seq":5,"concept":"K3-2-u5-C6","difficulty":3,"kind":"mc","stem":"「납작하다」가 어떤 종류의 낱말인지 알아보려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"「떡이 납작하다.」처럼 ‘무엇이 어떠하다’ 틀에 넣어 읽어 본다","correct":true},{"t":"‘-다’로 끝나니 틀에 넣어 보지 않아도 움직임이라고 정한다","mis":"K3-2-u5-X05"},{"t":"글자 수가 네 글자이니 이름이라고 정한다","mis":"K3-2-u5-X15"},{"t":"「납작하다가 의자이다.」처럼 아무 틀에나 넣는다","mis":"K3-2-u5-X04"}],"explanation":["낱말만 보고 정하지 않고 문장 틀에 넣어 읽어 봐요.","「떡이 납작하다」가 자연스러우니 ‘어떠하다’ 자리예요.","「납작하다」는 성질이나 상태를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#6','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C5',3,'mc','auto','『국어』 224쪽 4번 (2)예요. 운동장에서 노는 그림을 보고 떠오른 낱말 가운데에서 성질이나 상태를 나타내는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":6,"concept":"K3-2-u5-C5","difficulty":3,"kind":"mc","stem":"『국어』 224쪽 4번 (2)예요. 운동장에서 노는 그림을 보고 떠오른 낱말 가운데에서 성질이나 상태를 나타내는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"빠르다, 즐겁다","correct":true},{"t":"던지다, 피하다","mis":"K3-2-u5-X05"},{"t":"공, 운동장","mis":"K3-2-u5-X04"},{"t":"던지다, 즐겁다","mis":"K3-2-u5-X05"}],"explanation":["「공이 빠르다」, 「놀이가 즐겁다」처럼 ‘어떠하다’ 자리에 들어가요.","「던지다」, 「피하다」는 움직임이에요.","「공」, 「운동장」은 이름이에요."],"asset":{"type":"passage","lines":["[그림] 운동장에서 친구들이 공을 던지고 피하며 노는 모습","떠오르는 낱말: 공 · 운동장 · 던지다 · 피하다 · 빠르다 · 즐겁다"],"title":"그림을 보고 떠오르는 낱말 — 『국어』 224쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#7','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C8',3,'mc','auto','낱말의 종류를 알면 무엇이 좋을까요? 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X07','K3-2-u5-X01']::text[],false,'{"seq":7,"concept":"K3-2-u5-C8","difficulty":3,"kind":"mc","stem":"낱말의 종류를 알면 무엇이 좋을까요? 가장 알맞은 것은 무엇인가요?","options":[{"t":"낱말을 기준에 따라 나누고, 국어사전에서 찾을 때 도움이 된다","correct":true},{"t":"종류의 이름만 외우면 낱말 공부가 끝난다","mis":"K3-2-u5-X07"},{"t":"글씨를 더 빨리 쓸 수 있다","mis":"K3-2-u5-X07"},{"t":"모르는 낱말을 건너뛰어도 된다","mis":"K3-2-u5-X01"}],"explanation":["이 단원에서는 낱말을 기준에 따라 나누어요.","움직임·성질이나 상태를 나타내는 낱말은 형태가 바뀌어 국어사전에서 찾는 방법이 달라요.","종류를 알면 이런 일에 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#8','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C4',4,'essay','teacher','『국어』 225쪽 말놀이를 계획해요. 낱말의 종류 하나와 상황을 정하고, 그 상황에서 말할 낱말 세 개를 쓴 뒤, 그 낱말들이 고른 종류에 맞는 까닭을 문장 틀로 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u5-C4","difficulty":4,"kind":"essay","stem":"『국어』 225쪽 말놀이를 계획해요. 낱말의 종류 하나와 상황을 정하고, 그 상황에서 말할 낱말 세 개를 쓴 뒤, 그 낱말들이 고른 종류에 맞는 까닭을 문장 틀로 설명하세요.","answer_guide":{"answer":"예: 종류 — 움직임을 나타내는 낱말. 상황 — 우리가 수영장에 와 있다고 생각하자. 낱말 — 헤엄치다, 뛰어들다, 씻다. 까닭 — 「내가 헤엄치다」, 「친구가 뛰어들다」처럼 ‘무엇이 어찌하다’의 ‘어찌하다’ 자리에 들어가기 때문이다.","scoring_points":["낱말의 종류 하나와 상황을 정했는가","그 상황에 맞고 고른 종류에 맞는 낱말 세 개를 썼는가","문장 틀(무엇이 무엇이다·어찌하다·어떠하다)로 까닭을 설명했는가"]},"explanation":["그 밖의 주제로 교실의 이름 낱말, 친구의 좋은 점을 나타내는 성질이나 상태 낱말도 있어요.","상황이 정해지면 떠올릴 낱말이 쉬워져요.","문장 틀에 넣어 보면 종류를 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#9','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C7',4,'error','auto','「자랑」과 「자랑스럽다」의 종류를 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X06','K3-2-u5-X05']::text[],false,'{"seq":9,"concept":"K3-2-u5-C7","difficulty":4,"kind":"error","stem":"「자랑」과 「자랑스럽다」의 종류를 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서아: 「자랑」과 「자랑스럽다」는 모양이 닮았으니 같은 종류야.","correct":true,"mis_target":"K3-2-u5-X06"},{"t":"도윤: 「자랑을 늘어놓다」처럼 ‘무엇’ 자리에 들어가니 「자랑」은 이름을 나타내.","mis":"K3-2-u5-X06"},{"t":"하준: 「상을 받은 내가 자랑스럽다」처럼 ‘어떠하다’ 자리에 들어가니 성질이나 상태를 나타내.","mis":"K3-2-u5-X05"}],"explanation":["모양이 닮았다고 종류가 같은 것은 아니에요.","「자랑」은 이름, 「자랑스럽다」는 성질이나 상태를 나타내요.","문장에 넣어 읽어 보면 종류가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L02_challenge#10','kor',3,2,'u5','L02','tb_g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C6',4,'mc','auto','선생님이 친구들이 말한 낱말을 칠판에 세 무리로 나누어 적었어요. 선생님이 나눈 기준은 무엇일까요?',ARRAY['K3-2-u5-X15','K3-2-u5-X05']::text[],false,'{"seq":10,"concept":"K3-2-u5-C6","difficulty":4,"kind":"mc","stem":"선생님이 친구들이 말한 낱말을 칠판에 세 무리로 나누어 적었어요. 선생님이 나눈 기준은 무엇일까요?","options":[{"t":"낱말의 종류 — 이름 / 움직임 / 성질이나 상태","correct":true},{"t":"낱말의 글자 수","mis":"K3-2-u5-X15"},{"t":"‘-다’로 끝나는가","mis":"K3-2-u5-X05"},{"t":"첫 글자의 자음자","mis":"K3-2-u5-X15"}],"explanation":["책상·교실·안경은 이름이에요.","웃다·말하다·앉다는 움직임, 노랗다·곱슬하다·길다는 성질이나 상태예요.","‘-다’로 끝나는가로 나누면 두 무리만 생겨요."],"asset":{"type":"passage","lines":["[칠판 왼쪽] 책상 · 교실 · 안경","[칠판 가운데] 웃다 · 말하다 · 앉다","[칠판 오른쪽] 노랗다 · 곱슬하다 · 길다"],"title":"선생님이 친구들이 말한 낱말을 나누어 적은 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#1','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C9',1,'mc','auto','『국어』 226쪽이에요. 「본다, 보고, 보면」에서 형태가 바뀌지 않는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08','K3-2-u5-X09']::text[],false,'{"seq":1,"concept":"K3-2-u5-C9","difficulty":1,"kind":"mc","stem":"『국어』 226쪽이에요. 「본다, 보고, 보면」에서 형태가 바뀌지 않는 부분은 무엇인가요?","options":[{"t":"보","correct":true},{"t":"보고","mis":"K3-2-u5-X08"},{"t":"면","mis":"K3-2-u5-X08"},{"t":"까치","mis":"K3-2-u5-X09"}],"explanation":["세 낱말에 빠짐없이 든 부분을 찾아요.","「보」는 그대로이고 「ㄴ다·고·면」이 바뀌어요.","형태가 바뀌지 않는 부분은 「보」예요."],"asset":{"type":"passage","lines":["준우가 까치를 본다.","준우가 까치를 보고 손을 흔든다.","준우는 까치를 보면 반가운 기분이 든다."],"title":"『국어』 226쪽 1번 ①","hi":["본다","보고","보면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#2','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C9',1,'mc','auto','「하늘이 높으면 내 마음도 넓어진다.」에서 「높으면」의 형태가 바뀌는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":2,"concept":"K3-2-u5-C9","difficulty":1,"kind":"mc","stem":"「하늘이 높으면 내 마음도 넓어진다.」에서 「높으면」의 형태가 바뀌는 부분은 무엇인가요?","options":[{"t":"으면","correct":true},{"t":"높으면","mis":"K3-2-u5-X08"},{"t":"높","mis":"K3-2-u5-X08"},{"t":"면","mis":"K3-2-u5-X08"}],"explanation":["「높다, 높고, 높으면」을 나란히 놓아 봐요.","「높」은 그대로이고 「다·고·으면」이 바뀌어요.","「으」까지 바뀌는 부분에 들어가요."],"asset":{"type":"passage","lines":["하늘이 높다.","하늘이 높고 바람은 시원하다.","하늘이 높으면 내 마음도 넓어진다."],"title":"『국어』 226쪽 1번 ②","hi":["높다","높고","높으면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#3','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C10',1,'mc','auto','『국어』 227쪽이에요. 문장에서 쓰임에 따라 형태가 바뀌는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":3,"concept":"K3-2-u5-C10","difficulty":1,"kind":"mc","stem":"『국어』 227쪽이에요. 문장에서 쓰임에 따라 형태가 바뀌는 낱말은 무엇인가요?","options":[{"t":"움직임을 나타내는 낱말과 성질이나 상태를 나타내는 낱말","correct":true},{"t":"이름을 나타내는 낱말","mis":"K3-2-u5-X09"},{"t":"모든 낱말","mis":"K3-2-u5-X09"},{"t":"이름을 나타내는 낱말과 움직임을 나타내는 낱말","mis":"K3-2-u5-X09"}],"explanation":["「먹고, 먹으니」는 움직임, 「맛있고, 맛있으니」는 성질이나 상태를 나타내요.","이 두 종류는 문장에 따라 형태가 바뀌어요.","「하늘이, 하늘을」처럼 이름은 낱말 자체가 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#4','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C11',1,'ox','auto','『국어』 228쪽 만화에서 국어사전은 「막고, 막으니, 막아서, 막으면」을 모두 실을 수 없어 곤란해했어요. 그래서 기본이 되는 형태 하나를 정해 싣기로 해요.',ARRAY['K3-2-u5-X10']::text[],false,'{"seq":4,"concept":"K3-2-u5-C11","difficulty":1,"kind":"ox","stem":"『국어』 228쪽 만화에서 국어사전은 「막고, 막으니, 막아서, 막으면」을 모두 실을 수 없어 곤란해했어요. 그래서 기본이 되는 형태 하나를 정해 싣기로 해요.","answer":"O","reason_options":[{"t":"바뀐 모양을 모두 실으면 사전이 너무 두꺼워지니 기본형 하나를 정해 실어요.","correct":true},{"t":"사전을 만든 사람이 깜빡 빠뜨려서 싣지 못하는 거예요.","mis":"K3-2-u5-X10"}],"mis":"K3-2-u5-X10","explanation":["한 낱말에 형태가 아주 많아요.","모두 실을 수는 없으니 기본이 되는 형태를 정해요.","이것을 기본형이라고 해요."],"asset":{"type":"passage","lines":["① 국어사전: “길이나 통로가 통하지 못하게 하다.”를 뜻하는 낱말을 싣고 싶어.","② 막고 · 막으니 · 막아서 · 막으면: “저요! 저요!”","③ 국어사전: 이런, 곤란해. 너희 모두를 실을 수는 없어. 어떻게 하면 좋을까?"],"title":"만화 — 『국어』 228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#5','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C12',2,'mc','auto','『국어』 229쪽 표예요. 「낮고, 낮아서, 낮으니, 낮으면」의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":5,"concept":"K3-2-u5-C12","difficulty":2,"kind":"mc","stem":"『국어』 229쪽 표예요. 「낮고, 낮아서, 낮으니, 낮으면」의 기본형은 무엇인가요?","options":[{"t":"낮다","correct":true},{"t":"낮아다","mis":"K3-2-u5-X11"},{"t":"낮으다","mis":"K3-2-u5-X11"},{"t":"낮고","mis":"K3-2-u5-X11"}],"explanation":["형태가 바뀌지 않는 부분은 「낮」이에요.","바뀌지 않는 부분에 ‘-다’를 붙여요.","기본형은 「낮다」예요."],"asset":{"type":"passage","lines":["낮고 · 낮아서 · 낮으니 · 낮으면 → 낮 → 낮다","잡고 · 잡아서 · 잡으니 · 잡으면 → (   ) → (   )","매고 · 매서 · 매니 · 매면 → (   ) → (   )","짧고 · 짧아서 · 짧으니 · 짧으면 → (   ) → (   )"],"title":"낱말의 기본형 만들기 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#6','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C12',2,'sa','auto','『국어』 229쪽 표예요. 「잡고, 잡아서, 잡으니, 잡으면」의 기본형을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u5-C12","difficulty":2,"kind":"sa","stem":"『국어』 229쪽 표예요. 「잡고, 잡아서, 잡으니, 잡으면」의 기본형을 쓰세요.","answer":["잡다"],"explanation":["네 낱말에 모두 든 부분은 「잡」이에요.","「잡」에 ‘-다’를 붙여요.","기본형은 「잡다」예요."],"asset":{"type":"passage","lines":["낮고 · 낮아서 · 낮으니 · 낮으면 → 낮 → 낮다","잡고 · 잡아서 · 잡으니 · 잡으면 → (   ) → (   )","매고 · 매서 · 매니 · 매면 → (   ) → (   )","짧고 · 짧아서 · 짧으니 · 짧으면 → (   ) → (   )"],"title":"낱말의 기본형 만들기 — 『국어』 229쪽"},"mis":"K3-2-u5-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#7','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C9',2,'mc','auto','『국어』 227쪽 2번이에요. 「먹고, 먹으니, 먹으면, 먹어서」를 형태가 바뀌지 않는 부분과 바뀌는 부분으로 바르게 나눈 것은 무엇인가요?',ARRAY['K3-2-u5-X08','K3-2-u5-X09']::text[],false,'{"seq":7,"concept":"K3-2-u5-C9","difficulty":2,"kind":"mc","stem":"『국어』 227쪽 2번이에요. 「먹고, 먹으니, 먹으면, 먹어서」를 형태가 바뀌지 않는 부분과 바뀌는 부분으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"먹 / 고, 으니, 으면, 어서","correct":true},{"t":"먹으 / 고, 니, 면, 서","mis":"K3-2-u5-X08"},{"t":"동생 / 이, 밥을, 먹고","mis":"K3-2-u5-X09"},{"t":"먹고 / 으니, 으면, 어서","mis":"K3-2-u5-X08"}],"explanation":["네 낱말에 빠짐없이 든 부분은 「먹」이에요.","「먹고」에는 「으」가 없으니 「으」는 바뀌는 부분이에요.","그래서 「먹 / 고, 으니, 으면, 어서」로 나눠요."],"asset":{"type":"passage","lines":["동생이 밥을 먹고 이를 닦았다.","동생이 밥을 먹으니 이제 나도 먹을 수 있겠다.","동생이 밥을 먹으면 좋겠다.","동생이 밥을 먹어서 기분이 좋다."],"title":"『국어』 227쪽 2번 ①","hi":["먹고","먹으니","먹으면","먹어서"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#8','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C12',2,'mc','auto','『국어』 229쪽 「낱말의 기본형을 만드는 방법」으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":8,"concept":"K3-2-u5-C12","difficulty":2,"kind":"mc","stem":"『국어』 229쪽 「낱말의 기본형을 만드는 방법」으로 알맞은 것은 무엇인가요?","options":[{"t":"형태가 바뀌지 않는 부분과 바뀌는 부분을 나눈 뒤, 바뀌지 않는 부분에 ‘-다’를 붙인다","correct":true},{"t":"형태가 바뀌는 부분에 ‘-다’를 붙인다","mis":"K3-2-u5-X11"},{"t":"여러 모양 가운데에서 가장 짧은 모양을 그대로 쓴다","mis":"K3-2-u5-X11"},{"t":"가장 먼저 떠오른 모양을 기본형으로 삼는다","mis":"K3-2-u5-X11"}],"explanation":["먼저 바뀌지 않는 부분과 바뀌는 부분을 나눠요.","바뀌지 않는 부분에 ‘-다’를 붙여요.","「높아서, 높고, 높으니, 높으면」 → 「높」 → 「높다」예요."],"asset":{"type":"passage","lines":["① 낱말의 형태가 바뀌지 않는 부분과 바뀌는 부분을 나눠요.","   높아서 · 높고 · 높으니 · 높으면 → 높 / 아서 · 고 · 으니 · 으면","② 낱말의 형태가 바뀌지 않는 부분에 ‘-다’를 붙여요. → 높다","낱말의 기본형 완성!"],"title":"낱말의 기본형을 만드는 방법 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#9','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C9',2,'mc','auto','『국어』 227쪽 2번이에요. 「맛있고, 맛있으니, 맛있으면, 맛있어서」에서 형태가 바뀌지 않는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08','K3-2-u5-X09']::text[],false,'{"seq":9,"concept":"K3-2-u5-C9","difficulty":2,"kind":"mc","stem":"『국어』 227쪽 2번이에요. 「맛있고, 맛있으니, 맛있으면, 맛있어서」에서 형태가 바뀌지 않는 부분은 무엇인가요?","options":[{"t":"맛있","correct":true},{"t":"맛","mis":"K3-2-u5-X08"},{"t":"맛있으","mis":"K3-2-u5-X08"},{"t":"밥","mis":"K3-2-u5-X09"}],"explanation":["네 낱말에 빠짐없이 든 부분을 찾아요.","「맛있」 뒤에 「고·으니·으면·어서」가 붙었어요.","형태가 바뀌지 않는 부분은 「맛있」이에요."],"asset":{"type":"passage","lines":["밥이 맛있고 국도 맛있다.","밥이 맛있으니 기분이 좋다.","밥이 맛있으면 좋겠다.","밥이 맛있어서 또 먹고 싶다."],"title":"『국어』 227쪽 2번 ②","hi":["맛있고","맛있으니","맛있으면","맛있어서"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_basic#10','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C12',3,'mc','auto','『국어』 229쪽 표예요. 「매고, 매서, 매니, 매면」의 기본형과 그렇게 만든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":10,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"『국어』 229쪽 표예요. 「매고, 매서, 매니, 매면」의 기본형과 그렇게 만든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"매다 — 네 낱말에 빠짐없이 든 「매」에 ‘-다’를 붙여서","correct":true},{"t":"매서다 — 가장 긴 「매서」에 ‘-다’를 붙여서","mis":"K3-2-u5-X11"},{"t":"매어다 — 「매」 뒤에 「어」를 넣고 ‘-다’를 붙여서","mis":"K3-2-u5-X11"},{"t":"매면 — 가장 자주 쓰는 모양이라서","mis":"K3-2-u5-X11"}],"explanation":["「매서」에는 「어」가 보이지 않아요.","네 낱말에 모두 든 부분은 「매」뿐이에요.","「매」에 ‘-다’를 붙인 「매다」가 기본형이에요."],"asset":{"type":"passage","lines":["낮고 · 낮아서 · 낮으니 · 낮으면 → 낮 → 낮다","잡고 · 잡아서 · 잡으니 · 잡으면 → (   ) → (   )","매고 · 매서 · 매니 · 매면 → (   ) → (   )","짧고 · 짧아서 · 짧으니 · 짧으면 → (   ) → (   )"],"title":"낱말의 기본형 만들기 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#1','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C10',2,'ox','auto','「하늘이 높다.」, 「하늘은 넓다.」, 「하늘을 본다.」에서 「하늘」은 문장에 따라 형태가 바뀌는 낱말이에요.',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":1,"concept":"K3-2-u5-C10","difficulty":2,"kind":"ox","stem":"「하늘이 높다.」, 「하늘은 넓다.」, 「하늘을 본다.」에서 「하늘」은 문장에 따라 형태가 바뀌는 낱말이에요.","answer":"X","reason_options":[{"t":"뒤에 붙는 「이·은·을」만 달라지고 「하늘」은 그대로예요.","correct":true},{"t":"뒤에 붙는 말이 달라지면 낱말도 바뀐 거예요.","mis":"K3-2-u5-X09"}],"mis":"K3-2-u5-X09","explanation":["「하늘」은 이름을 나타내는 낱말이에요.","뒤에 「이·은·을」이 붙어도 「하늘」은 그대로예요.","높다·보다·먹다는 문장에 따라 형태가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#2','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C9',2,'sa','auto','『국어』 229쪽 표예요. 「짧고, 짧아서, 짧으니, 짧으면」에서 형태가 바뀌지 않는 부분을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u5-C9","difficulty":2,"kind":"sa","stem":"『국어』 229쪽 표예요. 「짧고, 짧아서, 짧으니, 짧으면」에서 형태가 바뀌지 않는 부분을 쓰세요.","answer":["짧"],"explanation":["네 낱말에 모두 든 부분을 찾아요.","「짧」 뒤에 「고·아서·으니·으면」이 붙었어요.","형태가 바뀌지 않는 부분은 「짧」이에요."],"asset":{"type":"passage","lines":["낮고 · 낮아서 · 낮으니 · 낮으면 → 낮 → 낮다","잡고 · 잡아서 · 잡으니 · 잡으면 → (   ) → (   )","매고 · 매서 · 매니 · 매면 → (   ) → (   )","짧고 · 짧아서 · 짧으니 · 짧으면 → (   ) → (   )"],"title":"낱말의 기본형 만들기 — 『국어』 229쪽"},"mis":"K3-2-u5-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#3','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C11',3,'mc','auto','「막고, 막으니, 막으면, 막아서」를 들으면 떠오르는 장면은 어떠한가요? 이것으로 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u5-X13','K3-2-u5-X12']::text[],false,'{"seq":3,"concept":"K3-2-u5-C11","difficulty":3,"kind":"mc","stem":"「막고, 막으니, 막으면, 막아서」를 들으면 떠오르는 장면은 어떠한가요? 이것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"떠오르는 장면이 크게 다르지 않으니 대표가 되는 낱말 하나를 정해 실으면 된다","correct":true},{"t":"네 낱말의 장면이 모두 달라서 사전에 모두 실어야 한다","mis":"K3-2-u5-X13"},{"t":"「막아서」만 바른 말이라 그것만 실어야 한다","mis":"K3-2-u5-X12"},{"t":"네 낱말은 모두 틀린 말이라 싣지 않는다","mis":"K3-2-u5-X12"}],"explanation":["네 낱말 모두 길이나 통로가 통하지 못하게 하는 장면이 떠올라요.","뜻이 같으니 대표 낱말 하나만 정하면 돼요.","그래서 기본형 「막다」를 정해 실어요."],"asset":{"type":"passage","lines":["① 국어사전: “길이나 통로가 통하지 못하게 하다.”를 뜻하는 낱말을 싣고 싶어.","② 막고 · 막으니 · 막아서 · 막으면: “저요! 저요!”","③ 국어사전: 이런, 곤란해. 너희 모두를 실을 수는 없어. 어떻게 하면 좋을까?"],"title":"만화 — 『국어』 228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#4','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C13',3,'error','auto','「먹어서」에 대해 친구들이 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13']::text[],false,'{"seq":4,"concept":"K3-2-u5-C13","difficulty":3,"kind":"error","stem":"「먹어서」에 대해 친구들이 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"라희: 「먹어서」는 국어사전에 실려 있지 않으니 틀린 말이야.","correct":true,"mis_target":"K3-2-u5-X12"},{"t":"은호: 「먹어서」는 문장에 알맞게 형태가 바뀐 거야.","mis":"K3-2-u5-X12"},{"t":"준서: 국어사전에는 기본형 「먹다」를 실어.","mis":"K3-2-u5-X13"}],"explanation":["기본형은 사전에 실으려고 정한 대표 모양이에요.","「먹어서」는 「동생이 밥을 먹어서 기분이 좋다」처럼 바르게 쓰인 말이에요.","사전에 없다고 틀린 말이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#5','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C10',3,'mc','auto','『국어활동』 73쪽 2번 글에서 움직임을 나타내는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":5,"concept":"K3-2-u5-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 73쪽 2번 글에서 움직임을 나타내는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"날아서, 앉으면, 떨어져요","correct":true},{"t":"높고, 맑으니, 시원해요","mis":"K3-2-u5-X05"},{"t":"하늘, 잠자리, 꽃","mis":"K3-2-u5-X04"},{"t":"날아서, 맑으니, 떨어져요","mis":"K3-2-u5-X05"}],"explanation":["「잠자리가 날다」처럼 ‘어찌하다’ 자리에 들어가는 낱말을 찾아요.","높고·맑으니·시원해요는 성질이나 상태를 나타내요.","두 종류 모두 문장에 따라 형태가 바뀌었어요."],"asset":{"type":"passage","lines":["가을 하늘이 높고 맑으니 내 마음도 시원해요.","잠자리가 날아서 꽃에 앉으면 물방울이 떨어져요."],"title":"『국어활동』 73쪽 2번 글","hi":["높고","맑으니","시원해요","날아서","앉으면","떨어져요"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#6','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C12',3,'mc','auto','『국어활동』 73쪽 글의 「날아서」를 형태가 바뀌지 않는 부분과 바뀌는 부분으로 나누어 기본형을 만들었어요. 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":6,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"『국어활동』 73쪽 글의 「날아서」를 형태가 바뀌지 않는 부분과 바뀌는 부분으로 나누어 기본형을 만들었어요. 알맞은 것은 무엇인가요?","options":[{"t":"날 / 아서 → 날다","correct":true},{"t":"날아 / 서 → 날아다","mis":"K3-2-u5-X11"},{"t":"날 / 아서 → 날으다","mis":"K3-2-u5-X11"},{"t":"날아서 / 없음 → 날아서다","mis":"K3-2-u5-X11"}],"explanation":["「날아서」는 「날」과 「아서」로 나눠요.","바뀌지 않는 부분 「날」에 ‘-다’를 붙여요.","기본형은 「날다」예요."],"asset":{"type":"passage","lines":["가을 하늘이 높고 맑으니 내 마음도 시원해요.","잠자리가 날아서 꽃에 앉으면 물방울이 떨어져요."],"title":"『국어활동』 73쪽 2번 글","hi":["높고","맑으니","시원해요","날아서","앉으면","떨어져요"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#7','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C12',3,'mc','auto','「입어서, 입으니, 입으면」의 기본형을 만드는 과정으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":7,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"「입어서, 입으니, 입으면」의 기본형을 만드는 과정으로 알맞은 것은 무엇인가요?","options":[{"t":"입 + 다 = 입다","correct":true},{"t":"입어 + 다 = 입어다","mis":"K3-2-u5-X11"},{"t":"입으 + 다 = 입으다","mis":"K3-2-u5-X11"},{"t":"입으면 + 다 = 입으면다","mis":"K3-2-u5-X11"}],"explanation":["세 낱말에 모두 든 부분은 「입」이에요.","「어서·으니·으면」은 바뀌는 부분이에요.","「입」에 ‘-다’를 붙인 「입다」가 기본형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#8','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C11',4,'essay','teacher','『국어』 228쪽 (1)이에요. 「막고, 막으니, 막아서, 막으면」 가운데에서 무엇을 기본형으로 삼아야 할지 쓰고, 그렇게 생각한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u5-C11","difficulty":4,"kind":"essay","stem":"『국어』 228쪽 (1)이에요. 「막고, 막으니, 막아서, 막으면」 가운데에서 무엇을 기본형으로 삼아야 할지 쓰고, 그렇게 생각한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 기본형 — 막다. 까닭 1 — 네 낱말은 떠오르는 장면이 같아서 모두 실을 필요 없이 대표 낱말 하나만 실으면 된다. 까닭 2 — 네 낱말에 빠짐없이 든 「막」에 ‘-다’를 붙이면 누구나 같은 기본형을 만들 수 있어 국어사전에서 쉽게 찾을 수 있다.","scoring_points":["기본형을 「막다」로 바르게 썼는가","모든 형태를 실을 수 없어 대표 낱말이 필요하다는 까닭을 썼는가","바뀌지 않는 부분에 ‘-다’를 붙인다는 방법이나 사전에서 찾기 쉽다는 까닭을 썼는가"]},"explanation":["형태가 바뀌는 낱말에는 기본이 되는 형태가 있어요.","이것을 기본형이라고 해요.","국어사전에서 낱말을 찾으려면 낱말의 기본형을 알아야 해요."],"asset":{"type":"passage","lines":["① 국어사전: “길이나 통로가 통하지 못하게 하다.”를 뜻하는 낱말을 싣고 싶어.","② 막고 · 막으니 · 막아서 · 막으면: “저요! 저요!”","③ 국어사전: 이런, 곤란해. 너희 모두를 실을 수는 없어. 어떻게 하면 좋을까?"],"title":"만화 — 『국어』 228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#9','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C9',4,'mc','auto','노랫말 바꾸어 부르기예요. 「먹, 먹, 먹 자로 시작하는 말은 (     )」을 형태가 바뀌는 낱말로 알맞게 부른 것은 무엇인가요?',ARRAY['K3-2-u5-X09','K3-2-u5-X04']::text[],false,'{"seq":9,"concept":"K3-2-u5-C9","difficulty":4,"kind":"mc","stem":"노랫말 바꾸어 부르기예요. 「먹, 먹, 먹 자로 시작하는 말은 (     )」을 형태가 바뀌는 낱말로 알맞게 부른 것은 무엇인가요?","options":[{"t":"먹고, 먹으면, 먹으니, 먹어서","correct":true},{"t":"먹이, 먹물, 먹구름","mis":"K3-2-u5-X09"},{"t":"밥, 국, 반찬","mis":"K3-2-u5-X04"},{"t":"먹고, 먹물, 먹어서","mis":"K3-2-u5-X09"}],"explanation":["형태가 바뀌지 않는 부분 「먹」 뒤에 바뀌는 부분을 붙여 불러요.","먹이·먹물·먹구름은 「먹」으로 시작할 뿐 「먹다」가 바뀐 모양이 아니에요.","그래서 「먹고, 먹으면, 먹으니, 먹어서」가 알맞아요."],"asset":{"type":"passage","lines":["노래 「‘리’ 자로 끝나는 말」을 바꾸어 불러요.","“가, 가, 가 자로 시작하는 말은 가지, 가재, 가수, 가시”","“먹, 먹, 먹 자로 시작하는 말은 (                    )”"],"title":"노랫말 바꾸어 부르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L04_challenge#10','kor',3,2,'u5','L04','tb_g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C12',4,'error','auto','친구들이 낱말의 기본형을 만들었어요. 기본형을 잘못 만든 친구는 누구인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":10,"concept":"K3-2-u5-C12","difficulty":4,"kind":"error","stem":"친구들이 낱말의 기본형을 만들었어요. 기본형을 잘못 만든 친구는 누구인가요?","options":[{"t":"서아: 「짧아서」 → 짧아다","correct":true,"mis_target":"K3-2-u5-X11"},{"t":"도윤: 「잡으면」 → 잡다","mis":"K3-2-u5-X11"},{"t":"하준: 「높으니」 → 높다","mis":"K3-2-u5-X11"}],"explanation":["「짧아서」에서 「아서」는 바뀌는 부분이에요.","바뀌지 않는 부분 「짧」에 ‘-다’를 붙여야 해요.","바른 기본형은 「짧다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#1','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C1',1,'mc','auto','『국어』 230쪽 「경험 떠올리기」예요. 준우가 새로 배운 낱말은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":1,"concept":"K3-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 230쪽 「경험 떠올리기」예요. 준우가 새로 배운 낱말은 무엇인가요?","options":[{"t":"설레다","correct":true},{"t":"두근두근","mis":"K3-2-u5-X17"},{"t":"체육 대회","mis":"K3-2-u5-X17"},{"t":"내일","mis":"K3-2-u5-X17"}],"explanation":["준우는 가슴이 두근두근한 기분을 무엇이라고 하는지 물었어요.","엄마는 「마음이 몹시 설레나 보다」라고 했어요.","준우는 이럴 때 「설렌다」고 한다는 것을 알았어요."],"asset":{"type":"speech","turns":[{"who":"준우","text":"으……. 기다리던 체육 대회 날이 내일이에요. 가슴이 두근두근한 이 기분은 뭘까요?"},{"who":"엄마","text":"우리 준우가 마음이 몹시 설레나 보다."},{"who":"준우","text":"아하, 이럴 때 설렌다고 하는군요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#2','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C1',1,'mc','auto','새로운 낱말을 사용했을 때의 생각이나 느낌으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X28','K3-2-u5-X31','K3-2-u5-X17']::text[],false,'{"seq":2,"concept":"K3-2-u5-C1","difficulty":1,"kind":"mc","stem":"새로운 낱말을 사용했을 때의 생각이나 느낌으로 알맞은 것은 무엇인가요?","options":[{"t":"내가 느낀 마음을 더 자세하고 정확하게 표현할 수 있었다","correct":true},{"t":"낱말을 많이 알면 말을 더 빨리 할 수 있었다","mis":"K3-2-u5-X28"},{"t":"어려운 낱말을 쓰면 친구를 이길 수 있었다","mis":"K3-2-u5-X31"},{"t":"새 낱말을 쓰니 친구와 대화가 안 되었다","mis":"K3-2-u5-X17"}],"explanation":["새 낱말로 내 생각을 조금 더 정확하게 표현할 수 있어요.","답답했던 감정을 자세히 표현할 수 있어요.","상대와 대화도 더 잘돼요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"내 생각을 조금 더 정확하게 표현할 수 있게 되었어."},{"who":"친구 2","text":"내가 느낀 감정을 어떻게 표현할지 몰라 답답했어. 그런데 새롭게 배운 낱말로 보다 자세히 표현할 수 있게 되었어."},{"who":"친구 3","text":"상대와 대화가 더 잘되는 것 같았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#3','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C33',1,'mc','auto','「낱말을 먹는 아이」에서 ‘사랑’이라는 낱말을 먹은 ‘나’는 어떻게 되었나요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":3,"concept":"K3-2-u5-C33","difficulty":1,"kind":"mc","stem":"「낱말을 먹는 아이」에서 ‘사랑’이라는 낱말을 먹은 ‘나’는 어떻게 되었나요?","options":[{"t":"모든 사람을 안아 주고 싶었다","correct":true},{"t":"하루 종일 무서웠다","mis":"K3-2-u5-X17"},{"t":"사람들을 다 밀쳐 버리고 싶었다","mis":"K3-2-u5-X17"},{"t":"계속 울기만 했다","mis":"K3-2-u5-X17"}],"explanation":["‘사랑’을 먹은 날을 찾아 다시 읽어요.","그날은 모든 사람을 안아 주고 싶었어요.","무서웠던 날은 ‘두려움’, 밀치고 싶던 날은 ‘분노’를 먹은 날이에요."],"asset":{"type":"passage","lines":["(간추림) 기쁨이라는 낱말을 먹은 날 — 무척 즐거웠고 쉴 새 없이 웃었다.","(간추림) 슬픔이라는 낱말을 먹은 날 — 너무 슬퍼서 울기만 했다.","하루는 사랑이라는 낱말을 먹었어. 그건 참 좋았어.","(간추림) 모든 사람을 안아 주고 싶었고, 말이 모두 하트 모양이 되었다.","(간추림) 분노를 먹은 날은 내내 화가 나고 기분이 안 좋았다.","(간추림) 두려움을 먹은 날은 하루 종일 무서웠다. 침대 밑에서 괴물까지 봤다."],"title":"「낱말을 먹는 아이」(마를레트 수니에르 글) 앞부분 — 『국어』 231~233쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#4','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C14',1,'blank','auto','『국어』 237쪽이에요. 「여럿 가운데에서 (     )을 가진 것끼리 갈라놓는 것을 분류라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u5-X15','K3-2-u5-X14']::text[],false,'{"seq":4,"concept":"K3-2-u5-C14","difficulty":1,"kind":"blank","stem":"『국어』 237쪽이에요. 「여럿 가운데에서 (     )을 가진 것끼리 갈라놓는 것을 분류라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"같은 특징","correct":true},{"t":"서로 다른 특징","mis":"K3-2-u5-X15"},{"t":"같은 글자 수","mis":"K3-2-u5-X14"},{"t":"아무 특징","mis":"K3-2-u5-X15"}],"explanation":["분류는 같은 특징을 가진 것끼리 묶는 일이에요.","무엇을 같은 특징으로 볼지가 바로 분류 기준이에요.","기준이 있어야 다른 사람도 나눈 까닭을 알 수 있어요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류 — 이름 / 움직임 / 성질이나 상태","기준 ② 형태가 바뀌는 부분이 있는가 — 있는 낱말 / 없는 낱말","여럿 가운데에서 같은 특징을 가진 것끼리 갈라놓는 것을 분류라고 해요."],"title":"분류 기준 두 가지 — 『국어』 236~237쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#5','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C14',2,'match','auto','『국어』 236쪽이에요. 보기의 낱말을 낱말의 종류에 따라 나누었어요. 낱말과 분류 기준을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u5-C14","difficulty":2,"kind":"match","stem":"『국어』 236쪽이에요. 보기의 낱말을 낱말의 종류에 따라 나누었어요. 낱말과 분류 기준을 알맞게 이으세요.","pairs":[{"l":"침대, 칠판, 초콜릿","r":"이름을 나타내는 낱말"},{"l":"웃다, 흐르다, 울다","r":"움직임을 나타내는 낱말"},{"l":"슬프다, 괴롭다, 즐겁다","r":"성질이나 상태를 나타내는 낱말"}],"mis":"K3-2-u5-X04","explanation":["「침대가 있다」의 「침대」는 ‘무엇’ 자리에 들어가요.","「눈물이 흐르다」의 「흐르다」는 ‘어찌하다’ 자리에 들어가요.","「마음이 괴롭다」의 「괴롭다」는 ‘어떠하다’ 자리에 들어가요."],"asset":{"type":"passage","lines":["[보기] 웃다 · 침대 · 슬프다 · 칠판 · 울다","[보기] 흐르다 · 괴롭다 · 초콜릿 · 즐겁다"],"title":"「낱말을 먹는 아이」에 나온 낱말 — 『국어』 236쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#6','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C15',2,'mc','auto','『국어』 237쪽이에요. 같은 보기 낱말을 「형태가 바뀌는 부분이 있는가」로 새롭게 나누었어요. 「형태가 바뀌는 부분이 없는 낱말」 칸에 들어갈 낱말은 무엇인가요?',ARRAY['K3-2-u5-X09','K3-2-u5-X14']::text[],false,'{"seq":6,"concept":"K3-2-u5-C15","difficulty":2,"kind":"mc","stem":"『국어』 237쪽이에요. 같은 보기 낱말을 「형태가 바뀌는 부분이 있는가」로 새롭게 나누었어요. 「형태가 바뀌는 부분이 없는 낱말」 칸에 들어갈 낱말은 무엇인가요?","options":[{"t":"침대, 칠판, 초콜릿","correct":true},{"t":"웃다, 흐르다, 울다","mis":"K3-2-u5-X09"},{"t":"슬프다, 괴롭다, 즐겁다","mis":"K3-2-u5-X09"},{"t":"슬프다, 침대, 울다","mis":"K3-2-u5-X14"}],"explanation":["움직임과 성질이나 상태를 나타내는 낱말은 형태가 바뀌어요.","이름을 나타내는 낱말은 형태가 바뀌는 부분이 없어요.","그래서 「침대, 칠판, 초콜릿」이 들어가요."],"asset":{"type":"passage","lines":["[보기] 웃다 · 침대 · 슬프다 · 칠판 · 울다","[보기] 흐르다 · 괴롭다 · 초콜릿 · 즐겁다"],"title":"「낱말을 먹는 아이」에 나온 낱말 — 『국어』 236쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#7','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C33',2,'mc','auto','「낱말을 먹는 아이」에서 마음이 텅 빈 것 같다고 느낀 ‘나’는 무엇을 하기로 했나요?',ARRAY['K3-2-u5-X17','K3-2-u5-X40']::text[],false,'{"seq":7,"concept":"K3-2-u5-C33","difficulty":2,"kind":"mc","stem":"「낱말을 먹는 아이」에서 마음이 텅 빈 것 같다고 느낀 ‘나’는 무엇을 하기로 했나요?","options":[{"t":"낱말을 모두 먹어 버리기로 했다","correct":true},{"t":"더 이상 아무 낱말도 먹지 않기로 했다","mis":"K3-2-u5-X17"},{"t":"초콜릿만 양껏 먹기로 했다","mis":"K3-2-u5-X40"},{"t":"칠판 앞에 나가 발표하기로 했다","mis":"K3-2-u5-X17"}],"explanation":["낱말을 먹지 않기로 한 것은 마음이 텅 비기 전의 일이에요.","텅 빈 마음을 느낀 뒤 「그래서 나는 낱말을 모두 먹어 버리기로 했어.」라고 했어요.","초콜릿은 행복한 느낌을 빗댄 말이에요."],"asset":{"type":"passage","lines":["(간추림) 나는 입을 꼭 다물고 더 이상 아무 낱말도 먹지 않기로 결심했다.","(간추림) 웃지도 슬퍼하지도 못하고, 마음이 텅 빈 것 같았다.","그래서 나는 낱말을 모두 먹어 버리기로 했어.","(간추림) 배가 부르고 행복했다. 초콜릿을 양껏 먹은 것처럼.","(간추림) 어떤 날은 행복하면서도 두렵거나 슬프거나 화가 난다.","모든 낱말이 나를 도와주는 걸.","내 기분이 어떤지 내가 누구인지 잘 알 수 있도록."],"title":"「낱말을 먹는 아이」 뒷부분 — 『국어』 234~235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#8','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C33',2,'mc','auto','「낱말을 먹는 아이」에서 ‘나’가 「모든 낱말이 나를 도와주는 걸.」이라고 한 까닭은 무엇일까요?',ARRAY['K3-2-u5-X40','K3-2-u5-X17']::text[],false,'{"seq":8,"concept":"K3-2-u5-C33","difficulty":2,"kind":"mc","stem":"「낱말을 먹는 아이」에서 ‘나’가 「모든 낱말이 나를 도와주는 걸.」이라고 한 까닭은 무엇일까요?","options":[{"t":"낱말이 내 기분이 어떤지, 내가 누구인지 잘 알 수 있게 해 주어서","correct":true},{"t":"낱말을 먹으면 배가 불러서","mis":"K3-2-u5-X40"},{"t":"낱말을 먹으면 늘 행복하기만 해서","mis":"K3-2-u5-X17"},{"t":"낱말을 먹으면 무서운 일이 생기지 않아서","mis":"K3-2-u5-X17"}],"explanation":["끝부분 「내 기분이 어떤지 내가 누구인지 잘 알 수 있도록.」을 찾아요.","낱말이 있어야 내 마음을 알고 나타낼 수 있어요.","그래서 모든 낱말이 나를 도와준다고 했어요."],"asset":{"type":"passage","lines":["(간추림) 나는 입을 꼭 다물고 더 이상 아무 낱말도 먹지 않기로 결심했다.","(간추림) 웃지도 슬퍼하지도 못하고, 마음이 텅 빈 것 같았다.","그래서 나는 낱말을 모두 먹어 버리기로 했어.","(간추림) 배가 부르고 행복했다. 초콜릿을 양껏 먹은 것처럼.","(간추림) 어떤 날은 행복하면서도 두렵거나 슬프거나 화가 난다.","모든 낱말이 나를 도와주는 걸.","내 기분이 어떤지 내가 누구인지 잘 알 수 있도록."],"title":"「낱말을 먹는 아이」 뒷부분 — 『국어』 234~235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#9','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C15',2,'ox','auto','같은 아홉 낱말을 처음에는 낱말의 종류로, 다음에는 형태가 바뀌는 부분이 있는가로 나누었더니 칸의 수와 칸에 든 낱말이 달라졌어요. 처음에 잘못 나누었기 때문이에요.',ARRAY['K3-2-u5-X16']::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":2,"kind":"ox","stem":"같은 아홉 낱말을 처음에는 낱말의 종류로, 다음에는 형태가 바뀌는 부분이 있는가로 나누었더니 칸의 수와 칸에 든 낱말이 달라졌어요. 처음에 잘못 나누었기 때문이에요.","answer":"X","reason_options":[{"t":"나누는 기준이 바뀌면 분류 결과도 달라질 수 있어요.","correct":true},{"t":"같은 낱말을 나누면 결과는 언제나 같아야 해요.","mis":"K3-2-u5-X16"}],"mis":"K3-2-u5-X16","explanation":["처음 기준은 낱말의 종류라 세 칸이에요.","다음 기준은 형태가 바뀌는 부분이 있는가라 두 칸이에요.","결과가 달라진 까닭은 기준이 달라졌기 때문이에요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류 — 이름 / 움직임 / 성질이나 상태","기준 ② 형태가 바뀌는 부분이 있는가 — 있는 낱말 / 없는 낱말","여럿 가운데에서 같은 특징을 가진 것끼리 갈라놓는 것을 분류라고 해요."],"title":"분류 기준 두 가지 — 『국어』 236~237쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_basic#10','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C33',3,'mc','auto','「낱말을 먹는 아이」에서 낱말을 ‘먹었다’고 나타낸 것은 무슨 뜻일까요?',ARRAY['K3-2-u5-X40','K3-2-u5-X28','K3-2-u5-X17']::text[],false,'{"seq":10,"concept":"K3-2-u5-C33","difficulty":3,"kind":"mc","stem":"「낱말을 먹는 아이」에서 낱말을 ‘먹었다’고 나타낸 것은 무슨 뜻일까요?","options":[{"t":"그 낱말이 나타내는 마음을 내 것으로 느끼고 알게 되었다는 뜻","correct":true},{"t":"낱말이 적힌 종이를 정말 입에 넣어 먹었다는 뜻","mis":"K3-2-u5-X40"},{"t":"낱말을 소리 내어 빨리 읽었다는 뜻","mis":"K3-2-u5-X28"},{"t":"낱말을 잊어버렸다는 뜻","mis":"K3-2-u5-X17"}],"explanation":["‘기쁨’을 먹은 날은 즐거웠고 ‘슬픔’을 먹은 날은 슬펐어요.","낱말을 먹으면 그 낱말의 마음이 되었어요.","‘먹는다’는 낱말을 내 것으로 받아들인다는 것을 빗댄 말이에요."],"asset":{"type":"passage","lines":["(간추림) 기쁨이라는 낱말을 먹은 날 — 무척 즐거웠고 쉴 새 없이 웃었다.","(간추림) 슬픔이라는 낱말을 먹은 날 — 너무 슬퍼서 울기만 했다.","하루는 사랑이라는 낱말을 먹었어. 그건 참 좋았어.","(간추림) 모든 사람을 안아 주고 싶었고, 말이 모두 하트 모양이 되었다.","(간추림) 분노를 먹은 날은 내내 화가 나고 기분이 안 좋았다.","(간추림) 두려움을 먹은 날은 하루 종일 무서웠다. 침대 밑에서 괴물까지 봤다."],"title":"「낱말을 먹는 아이」(마를레트 수니에르 글) 앞부분 — 『국어』 231~233쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#1','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',2,'mc','auto','기분이나 마음을 나타내는 낱말을 「기쁜 마음」과 「슬픈 마음」으로 나누어요. 「슬픈 마음」 칸에 들어갈 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X15']::text[],false,'{"seq":1,"concept":"K3-2-u5-C14","difficulty":2,"kind":"mc","stem":"기분이나 마음을 나타내는 낱말을 「기쁜 마음」과 「슬픈 마음」으로 나누어요. 「슬픈 마음」 칸에 들어갈 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"서럽다, 허전하다, 실망하다, 우울하다","correct":true},{"t":"설레다, 든든하다, 신나다, 자랑스럽다","mis":"K3-2-u5-X14"},{"t":"설레다, 서럽다, 신나다, 우울하다","mis":"K3-2-u5-X15"},{"t":"든든하다, 허전하다, 자랑스럽다, 실망하다","mis":"K3-2-u5-X15"}],"explanation":["기준은 「기쁜 마음인가, 슬픈 마음인가」예요.","설레다·든든하다·신나다·자랑스럽다는 기쁜 마음이에요.","서럽다·허전하다·실망하다·우울하다는 슬픈 마음이에요."],"asset":{"type":"passage","lines":["설레다 · 서럽다 · 든든하다 · 허전하다","신나다 · 실망하다 · 자랑스럽다 · 우울하다"],"title":"기분이나 마음을 나타내는 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#2','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C33',2,'sa','auto','「낱말을 먹는 아이」에서 ‘두려움’을 먹은 날, ‘나’는 밤에 침대 밑에서 무엇까지 봤다고 했나요?','{}'::text[],false,'{"seq":2,"concept":"K3-2-u5-C33","difficulty":2,"kind":"sa","stem":"「낱말을 먹는 아이」에서 ‘두려움’을 먹은 날, ‘나’는 밤에 침대 밑에서 무엇까지 봤다고 했나요?","answer":["괴물"],"explanation":["‘두려움’을 먹은 날을 찾아요.","그날은 하루 종일 무서웠어요.","밤에는 침대 밑에서 「괴물」까지 봤다고 했어요."],"asset":{"type":"passage","lines":["(간추림) 기쁨이라는 낱말을 먹은 날 — 무척 즐거웠고 쉴 새 없이 웃었다.","(간추림) 슬픔이라는 낱말을 먹은 날 — 너무 슬퍼서 울기만 했다.","하루는 사랑이라는 낱말을 먹었어. 그건 참 좋았어.","(간추림) 모든 사람을 안아 주고 싶었고, 말이 모두 하트 모양이 되었다.","(간추림) 분노를 먹은 날은 내내 화가 나고 기분이 안 좋았다.","(간추림) 두려움을 먹은 날은 하루 종일 무서웠다. 침대 밑에서 괴물까지 봤다."],"title":"「낱말을 먹는 아이」(마를레트 수니에르 글) 앞부분 — 『국어』 231~233쪽"},"mis":"K3-2-u5-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#3','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',3,'mc','auto','「웃다, 침대, 슬프다」를 낱말의 종류로 나누면 세 칸, 형태가 바뀌는 부분이 있는가로 나누면 두 칸이 돼요. 칸의 수가 달라진 까닭은 무엇인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X15']::text[],false,'{"seq":3,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"「웃다, 침대, 슬프다」를 낱말의 종류로 나누면 세 칸, 형태가 바뀌는 부분이 있는가로 나누면 두 칸이 돼요. 칸의 수가 달라진 까닭은 무엇인가요?","options":[{"t":"나누는 기준이 달라졌기 때문","correct":true},{"t":"낱말이 바뀌었기 때문","mis":"K3-2-u5-X16"},{"t":"처음에 잘못 나누었기 때문","mis":"K3-2-u5-X16"},{"t":"낱말마다 칸이 정해져 있지 않아 아무렇게나 나누었기 때문","mis":"K3-2-u5-X15"}],"explanation":["두 번 모두 같은 낱말을 나누었어요.","바뀐 것은 무엇을 보고 나누었는가, 곧 기준이에요.","기준이 바뀌면 결과도 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#4','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',3,'error','auto','낱말 분류 릴레이를 해요. 첫 번째 친구가 「침대」와 「웃다」를 양쪽에 놓으며 「이름을 나타내는 낱말 / 움직임을 나타내는 낱말」이라고 기준을 말했어요. 다음 친구들은 모두 ‘선택 1’을 했어요. 잘못한 친구는 누구인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":4,"concept":"K3-2-u5-C14","difficulty":3,"kind":"error","stem":"낱말 분류 릴레이를 해요. 첫 번째 친구가 「침대」와 「웃다」를 양쪽에 놓으며 「이름을 나타내는 낱말 / 움직임을 나타내는 낱말」이라고 기준을 말했어요. 다음 친구들은 모두 ‘선택 1’을 했어요. 잘못한 친구는 누구인가요?","options":[{"t":"은재: 「즐겁다」를 「웃다」 쪽에 놓았다.","correct":true,"mis_target":"K3-2-u5-X05"},{"t":"태오: 「칠판」을 「침대」 쪽에 놓았다.","mis":"K3-2-u5-X04"},{"t":"라온: 「울다」를 「웃다」 쪽에 놓았다.","mis":"K3-2-u5-X04"}],"explanation":["‘선택 1’은 앞선 분류 기준에 따라 분류하는 거예요.","「즐겁다」는 움직임이 아니라 성질이나 상태를 나타내요.","「즐겁다」를 놓으려면 ‘선택 2’로 새 기준을 외쳐야 해요."],"asset":{"type":"passage","lines":["① 모둠 친구들이 각자 다섯 개의 낱말을 카드에 쓴다.","② 모둠 친구들이 쓴 낱말 카드를 모두 모아 섞는다.","③ 첫 번째 학생이 카드 두 개를 양쪽에 놓으며 분류 기준을 말한다.","④ 다음 학생은 둘 가운데 하나를 고른다.","   선택 1. 낱말 한 개를 골라 앞선 분류 기준에 따라 분류하기","   선택 2. 낱말 한 개를 골라 새 분류 기준을 외치며 분류하기","⑤ 모든 낱말 카드를 분류할 때까지 돌아가며 계속한다."],"title":"낱말 분류 릴레이 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#5','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C33',3,'mc','auto','「낱말을 먹는 아이」에서 ‘나’가 아무 낱말도 먹지 않기로 결심한 뒤에는 어떤 날들이 이어졌나요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":5,"concept":"K3-2-u5-C33","difficulty":3,"kind":"mc","stem":"「낱말을 먹는 아이」에서 ‘나’가 아무 낱말도 먹지 않기로 결심한 뒤에는 어떤 날들이 이어졌나요?","options":[{"t":"웃지도 슬퍼하지도 못하고 마음이 텅 빈 것 같은 날들","correct":true},{"t":"날마다 행복하고 즐겁기만 한 날들","mis":"K3-2-u5-X17"},{"t":"모든 사람을 안아 주고 싶은 날들","mis":"K3-2-u5-X17"},{"t":"배가 부르고 행복한 날들","mis":"K3-2-u5-X17"}],"explanation":["「그러자 아주 이상한 날들이 계속되었어.」 다음을 읽어요.","‘나’는 웃지도 슬퍼하지도 못하고 화나지도 않았어요.","마음이 텅 빈 것 같았어요."],"asset":{"type":"passage","lines":["(간추림) 나는 입을 꼭 다물고 더 이상 아무 낱말도 먹지 않기로 결심했다.","(간추림) 웃지도 슬퍼하지도 못하고, 마음이 텅 빈 것 같았다.","그래서 나는 낱말을 모두 먹어 버리기로 했어.","(간추림) 배가 부르고 행복했다. 초콜릿을 양껏 먹은 것처럼.","(간추림) 어떤 날은 행복하면서도 두렵거나 슬프거나 화가 난다.","모든 낱말이 나를 도와주는 걸.","내 기분이 어떤지 내가 누구인지 잘 알 수 있도록."],"title":"「낱말을 먹는 아이」 뒷부분 — 『국어』 234~235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#6','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',3,'mc','auto','여러 낱말을 나누기 전에 가장 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X15','K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C14","difficulty":3,"kind":"mc","stem":"여러 낱말을 나누기 전에 가장 먼저 할 일은 무엇인가요?","options":[{"t":"무엇을 보고 나눌지 분류 기준을 정한다","correct":true},{"t":"낱말마다 정해진 칸을 찾아 넣는다","mis":"K3-2-u5-X14"},{"t":"생각나는 대로 나눈다","mis":"K3-2-u5-X15"},{"t":"낱말을 글자 수대로 늘어놓는다","mis":"K3-2-u5-X22"}],"explanation":["낱말마다 들어갈 칸이 하나로 정해져 있는 것이 아니에요.","먼저 기준을 정하면 같은 특징끼리 묶을 수 있어요.","기준을 말하면 친구도 나눈 까닭을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#7','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C33',3,'mc','auto','「낱말을 먹는 아이」 끝에서 「어떤 날은 행복하면서도 두렵거나 슬프거나 화가 나거든.」이라고 했어요. 이 말로 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":7,"concept":"K3-2-u5-C33","difficulty":3,"kind":"mc","stem":"「낱말을 먹는 아이」 끝에서 「어떤 날은 행복하면서도 두렵거나 슬프거나 화가 나거든.」이라고 했어요. 이 말로 알 수 있는 것은 무엇인가요?","options":[{"t":"하루에도 여러 마음이 함께 들 수 있어서 그 마음을 나타내는 낱말이 모두 필요하다","correct":true},{"t":"기쁜 마음을 나타내는 낱말만 먹어야 한다","mis":"K3-2-u5-X17"},{"t":"슬픈 낱말은 먹지 않는 것이 좋다","mis":"K3-2-u5-X17"},{"t":"한 날에는 한 가지 마음만 든다","mis":"K3-2-u5-X17"}],"explanation":["‘나’는 이제 모든 낱말이 늘 나와 함께한다고 했어요.","행복하면서도 두렵거나 슬플 수 있어요.","그래서 모든 낱말과 감정이 내 일부분이에요."],"asset":{"type":"passage","lines":["(간추림) 나는 입을 꼭 다물고 더 이상 아무 낱말도 먹지 않기로 결심했다.","(간추림) 웃지도 슬퍼하지도 못하고, 마음이 텅 빈 것 같았다.","그래서 나는 낱말을 모두 먹어 버리기로 했어.","(간추림) 배가 부르고 행복했다. 초콜릿을 양껏 먹은 것처럼.","(간추림) 어떤 날은 행복하면서도 두렵거나 슬프거나 화가 난다.","모든 낱말이 나를 도와주는 걸.","내 기분이 어떤지 내가 누구인지 잘 알 수 있도록."],"title":"「낱말을 먹는 아이」 뒷부분 — 『국어』 234~235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#8','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C33',4,'essay','teacher','『국어』 237쪽 「자신과 관련짓기」예요. 자신을 설명할 수 있는 낱말을 하나 떠올리고, 「어느 날, 나는 (     )(이)라는 낱말을 먹었어. 그랬더니 …」로 시작하는 이야기의 한 장면을 완성하세요. 떠올린 낱말의 종류도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u5-C33","difficulty":4,"kind":"essay","stem":"『국어』 237쪽 「자신과 관련짓기」예요. 자신을 설명할 수 있는 낱말을 하나 떠올리고, 「어느 날, 나는 (     )(이)라는 낱말을 먹었어. 그랬더니 …」로 시작하는 이야기의 한 장면을 완성하세요. 떠올린 낱말의 종류도 쓰세요.","answer_guide":{"answer":"예: 낱말 — 용기(이름을 나타내는 낱말). 어느 날, 나는 용기라는 낱말을 먹었어. 그랬더니 수업 시간에 발표를 할 때 떨지 않게 되었어. 나는 평소라면 발표가 두려워 말도 제대로 못 할 아이였어. 그런데 ‘용기’를 먹고 숨겨진 힘이 몸속에 퍼지는 것을 느꼈어.","scoring_points":["자신을 설명할 수 있는 낱말을 떠올렸는가","주어진 첫 문장으로 시작해 그 낱말을 먹은 뒤의 일을 이야기로 썼는가","떠올린 낱말의 종류를 바르게 썼는가"]},"explanation":["꿈, 추억, 좋아하는 것, 취미처럼 나를 설명하는 낱말을 떠올려요.","주인공이 되었다고 생각하고 그 낱말을 먹은 뒤의 마음과 일을 써요.","같은 낱말이라도 친구마다 다른 이야기를 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#9','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',4,'essay','teacher','「웃다, 침대, 슬프다, 칠판, 울다, 흐르다, 괴롭다, 초콜릿, 즐겁다」를 낱말의 종류도, 형태가 바뀌는가도 아닌 새 기준으로 나누어 보세요. 기준과 나눈 결과를 쓰고, 종류로 나눈 결과와 왜 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":4,"kind":"essay","stem":"「웃다, 침대, 슬프다, 칠판, 울다, 흐르다, 괴롭다, 초콜릿, 즐겁다」를 낱말의 종류도, 형태가 바뀌는가도 아닌 새 기준으로 나누어 보세요. 기준과 나눈 결과를 쓰고, 종류로 나눈 결과와 왜 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 기준 — 기분이 좋을 때 쓰는 낱말인가. 결과 — 좋을 때: 웃다, 즐겁다, 초콜릿 / 아닐 때: 슬프다, 울다, 괴롭다, 흐르다, 침대, 칠판. 달라진 까닭 — 종류로 나누면 세 칸이었지만 나는 다른 기준으로 나누었기 때문에 칸의 수와 칸에 든 낱말이 달라졌다.","scoring_points":["새 분류 기준을 분명하게 썼는가","아홉 낱말을 그 기준에 맞게 빠짐없이 나누었는가","결과가 달라진 까닭을 기준이 달라졌기 때문이라고 썼는가"]},"explanation":["분류 기준은 여러 가지가 될 수 있어요.","기준을 정하면 그 기준에 맞게 빠짐없이 나눠요.","기준이 바뀌면 분류 결과도 달라져요."],"asset":{"type":"passage","lines":["[보기] 웃다 · 침대 · 슬프다 · 칠판 · 울다","[보기] 흐르다 · 괴롭다 · 초콜릿 · 즐겁다"],"title":"「낱말을 먹는 아이」에 나온 낱말 — 『국어』 236쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L06_challenge#10','kor',3,2,'u5','L06','tb_g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',4,'mc','auto','보기의 아홉 낱말을 낱말의 종류로 한 번, 형태가 바뀌는 부분이 있는가로 한 번 나누었어요. 두 번 모두 같은 칸에 함께 들어가는 짝은 무엇인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X04']::text[],false,'{"seq":10,"concept":"K3-2-u5-C15","difficulty":4,"kind":"mc","stem":"보기의 아홉 낱말을 낱말의 종류로 한 번, 형태가 바뀌는 부분이 있는가로 한 번 나누었어요. 두 번 모두 같은 칸에 함께 들어가는 짝은 무엇인가요?","options":[{"t":"침대와 초콜릿","correct":true},{"t":"웃다와 슬프다","mis":"K3-2-u5-X16"},{"t":"칠판과 울다","mis":"K3-2-u5-X04"},{"t":"흐르다와 괴롭다","mis":"K3-2-u5-X16"}],"explanation":["「침대」, 「초콜릿」은 둘 다 이름이고, 둘 다 형태가 바뀌지 않아요.","「웃다」와 「슬프다」는 형태가 바뀌는 칸에는 함께 들지만 종류가 달라요.","기준이 바뀌면 함께 묶이는 낱말도 달라져요."],"asset":{"type":"passage","lines":["[보기] 웃다 · 침대 · 슬프다 · 칠판 · 울다","[보기] 흐르다 · 괴롭다 · 초콜릿 · 즐겁다"],"title":"「낱말을 먹는 아이」에 나온 낱말 — 『국어』 236쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#1','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C2',1,'mc','auto','『국어』 238쪽 1번이에요. 「보건」, 「사흘」처럼 낱말의 뜻을 알고 싶을 때에는 어떻게 하면 좋을까요?',ARRAY['K3-2-u5-X01','K3-2-u5-X03','K3-2-u5-X02']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 238쪽 1번이에요. 「보건」, 「사흘」처럼 낱말의 뜻을 알고 싶을 때에는 어떻게 하면 좋을까요?","options":[{"t":"국어사전을 찾아보거나 어른께 여쭈어본다","correct":true},{"t":"뜻을 모르는 낱말은 그냥 지나친다","mis":"K3-2-u5-X01"},{"t":"아무 뜻이나 짐작하고 끝낸다","mis":"K3-2-u5-X03"},{"t":"그 글은 더 읽지 않는다","mis":"K3-2-u5-X02"}],"explanation":["뜻을 모르면 글의 내용을 바르게 알 수 없어요.","국어사전을 찾거나 어른께 여쭈어볼 수 있어요.","인터넷으로 찾아볼 수도 있어요."],"asset":{"type":"passage","lines":["[그림] 보건실 문패 앞 — “‘보건’이 무슨 뜻일까?”","[그림] 가게 안내문 「○○월 ○○일부터 사흘 동안 쉽니다.」","   — “‘사흘’이 무슨 뜻일까?”","[그림] 박물관 「조상의 얼이 깃든 도자기」 — “얼? 깃든?”"],"title":"낱말의 뜻이 궁금했던 경험 — 『국어』 238쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#2','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C17',1,'mc','auto','『국어』 239쪽 2번 (3)이에요. 글자 「학」의 짜임을 바르게 나눈 것은 무엇인가요?',ARRAY['K3-2-u5-X18']::text[],false,'{"seq":2,"concept":"K3-2-u5-C17","difficulty":1,"kind":"mc","stem":"『국어』 239쪽 2번 (3)이에요. 글자 「학」의 짜임을 바르게 나눈 것은 무엇인가요?","options":[{"t":"첫 자음자 ㅎ · 모음자 ㅏ · 받침 ㄱ","correct":true},{"t":"첫 자음자 ㄱ · 모음자 ㅏ · 받침 ㅎ","mis":"K3-2-u5-X18"},{"t":"첫 자음자 ㅎ · 모음자 ㄱ · 받침 ㅏ","mis":"K3-2-u5-X18"},{"t":"첫 자음자 ㅏ · 모음자 ㅎ · 받침 ㄱ","mis":"K3-2-u5-X18"}],"explanation":["글자를 천천히 소리 내며 나눠요.","맨 앞 자음자 ㅎ, 가운데 모음자 ㅏ, 아래 받침 ㄱ이에요.","국어사전에서 낱말을 찾으려면 글자의 짜임을 살펴봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#3','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C23',1,'mc','auto','『국어』 241쪽이에요. 「○○월 ○○일부터 사흘 동안 쉽니다.」에서 국어사전에서 찾은 「사흘」의 뜻은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":3,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"『국어』 241쪽이에요. 「○○월 ○○일부터 사흘 동안 쉽니다.」에서 국어사전에서 찾은 「사흘」의 뜻은 무엇인가요?","options":[{"t":"세 날","correct":true},{"t":"네 날","mis":"K3-2-u5-X25"},{"t":"두 날","mis":"K3-2-u5-X25"},{"t":"한 주일","mis":"K3-2-u5-X25"}],"explanation":["「사흘」은 소리가 「사(넷)」와 비슷해도 넷이 아니에요.","국어사전에는 「세 날」이라고 실려 있어요.","소리만 보고 짐작하지 말고 사전으로 확인해요."],"asset":{"type":"passage","lines":["보건 — 건강을 온전하게 잘 지킴.","사흘 — 세 날.","얼 — 정신의 줏대.","깃들다 — 감정, 생각, 노력 따위가 어리거나 스미다."],"title":"국어사전에서 찾은 뜻 — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#4','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C18',1,'ox','auto','활동지예요. 「나라」와 「가을」 가운데에서 국어사전에 먼저 싣는 낱말은 「가을」이에요.',ARRAY['K3-2-u5-X22']::text[],false,'{"seq":4,"concept":"K3-2-u5-C18","difficulty":1,"kind":"ox","stem":"활동지예요. 「나라」와 「가을」 가운데에서 국어사전에 먼저 싣는 낱말은 「가을」이에요.","answer":"O","reason_options":[{"t":"「가을」의 첫 자음자 ㄱ이 「나라」의 ㄴ보다 앞이에요.","correct":true},{"t":"글자 수가 같으면 어느 것을 먼저 싣는지 정할 수 없어요.","mis":"K3-2-u5-X22"}],"mis":"K3-2-u5-X22","explanation":["첫 자음자를 살펴봐요.","「나라」는 ㄴ, 「가을」은 ㄱ으로 시작해요.","ㄱ이 ㄴ보다 앞이니 「가을」을 먼저 실어요."],"asset":{"type":"passage","lines":["나라, 가을","사자, 소리","자라, 장구","강조, 갈래","발사, 발레"],"title":"짝 지은 두 낱말 — 국어사전에 먼저 싣는 낱말은?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#5','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C19',2,'mc','auto','활동지예요. 「사자」와 「소리」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X19']::text[],false,'{"seq":5,"concept":"K3-2-u5-C19","difficulty":2,"kind":"mc","stem":"활동지예요. 「사자」와 「소리」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"사자 — 첫 번째 글자의 모음자 ㅏ가 ㅗ보다 앞이라서","correct":true},{"t":"소리 — 첫 번째 글자의 모음자 ㅗ가 ㅏ보다 앞이라서","mis":"K3-2-u5-X20"},{"t":"소리 — ㅅ으로 시작하는 낱말 가운데에서 맨 앞이라서","mis":"K3-2-u5-X19"}],"explanation":["첫 자음자는 둘 다 ㅅ으로 같아요.","그럼 첫 번째 글자의 모음자를 봐요.","ㅏ가 ㅗ보다 앞이니 「사자」가 먼저예요."],"asset":{"type":"passage","lines":["나라, 가을","사자, 소리","자라, 장구","강조, 갈래","발사, 발레"],"title":"짝 지은 두 낱말 — 국어사전에 먼저 싣는 낱말은?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#6','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C20',2,'mc','auto','활동지예요. 「자라」와 「장구」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"활동지예요. 「자라」와 「장구」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"자라 — 받침이 없는 글자가 먼저라서","correct":true},{"t":"장구 — 받침이 있는 글자가 먼저라서","mis":"K3-2-u5-X21"},{"t":"장구 — 받침이 있어 글자가 더 꽉 차서","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자 ㅈ과 모음자 ㅏ가 같아요.","그럼 받침을 봐요. 「자」는 받침이 없고 「장」은 받침이 있어요.","받침이 없는 글자가 먼저이니 「자라」가 먼저예요."],"asset":{"type":"passage","lines":["나라, 가을","사자, 소리","자라, 장구","강조, 갈래","발사, 발레"],"title":"짝 지은 두 낱말 — 국어사전에 먼저 싣는 낱말은?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#7','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C20',2,'mc','auto','활동지예요. 「강조」와 「갈래」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X37']::text[],false,'{"seq":7,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"활동지예요. 「강조」와 「갈래」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"갈래 — 받침 ㄹ이 ㅇ보다 앞이라서","correct":true},{"t":"강조 — 받침 ㅇ이 ㄹ보다 앞이라서","mis":"K3-2-u5-X37"},{"t":"정할 수 없다 — 두 글자 모두 받침이 있어서","mis":"K3-2-u5-X37"}],"explanation":["첫 자음자 ㄱ, 모음자 ㅏ가 같고 둘 다 받침이 있어요.","받침끼리도 자음자 차례대로 봐요.","ㄹ이 ㅇ보다 앞이니 「갈래」가 먼저예요."],"asset":{"type":"passage","lines":["나라, 가을","사자, 소리","자라, 장구","강조, 갈래","발사, 발레"],"title":"짝 지은 두 낱말 — 국어사전에 먼저 싣는 낱말은?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#8','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C21',2,'mc','auto','활동지예요. 「발사」와 「발레」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":8,"concept":"K3-2-u5-C21","difficulty":2,"kind":"mc","stem":"활동지예요. 「발사」와 「발레」 가운데에서 먼저 싣는 낱말과 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"발레 — 첫 번째 글자가 같으니 두 번째 글자의 첫 자음자 ㄹ이 ㅅ보다 앞이라서","correct":true},{"t":"발사 — 두 번째 글자의 첫 자음자 ㅅ이 ㄹ보다 앞이라서","mis":"K3-2-u5-X19"},{"t":"정할 수 없다 — 첫 번째 글자가 같아서","mis":"K3-2-u5-X22"}],"explanation":["첫 번째 글자 「발」이 같아요.","그럼 두 번째 글자를 같은 방법으로 봐요.","「레」의 ㄹ이 「사」의 ㅅ보다 앞이니 「발레」가 먼저예요."],"asset":{"type":"passage","lines":["나라, 가을","사자, 소리","자라, 장구","강조, 갈래","발사, 발레"],"title":"짝 지은 두 낱말 — 국어사전에 먼저 싣는 낱말은?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#9','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C18',2,'mc','auto','『국어』 239쪽 2번 (4)예요. 「학교, 교실, 가방, 하루」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X21','K3-2-u5-X20']::text[],false,'{"seq":9,"concept":"K3-2-u5-C18","difficulty":2,"kind":"mc","stem":"『국어』 239쪽 2번 (4)예요. 「학교, 교실, 가방, 하루」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"가방 → 교실 → 하루 → 학교","correct":true},{"t":"학교 → 교실 → 가방 → 하루","mis":"K3-2-u5-X19"},{"t":"가방 → 교실 → 학교 → 하루","mis":"K3-2-u5-X21"},{"t":"교실 → 가방 → 하루 → 학교","mis":"K3-2-u5-X20"}],"explanation":["첫 자음자 ㄱ인 「가방」, 「교실」이 앞이고 ㅏ가 ㅛ보다 앞이에요.","ㅎ인 「하루」, 「학교」는 첫 글자 받침을 봐요.","받침 없는 「하」가 「학」보다 먼저예요."],"asset":{"type":"passage","lines":["학교 · 교실 · 가방 · 하루"],"title":"『국어』 239쪽 2번 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_basic#10','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C22',3,'mc','auto','『국어활동』 74쪽 세희의 말이에요. 「맛있는 사과를 먹었다.」에서 「먹었다」의 뜻이 궁금하면 국어사전에서 어떤 낱말을 찾아야 하나요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":10,"concept":"K3-2-u5-C22","difficulty":3,"kind":"mc","stem":"『국어활동』 74쪽 세희의 말이에요. 「맛있는 사과를 먹었다.」에서 「먹었다」의 뜻이 궁금하면 국어사전에서 어떤 낱말을 찾아야 하나요?","options":[{"t":"먹다","correct":true},{"t":"먹었다","mis":"K3-2-u5-X23"},{"t":"먹었","mis":"K3-2-u5-X11"},{"t":"먹어","mis":"K3-2-u5-X23"}],"explanation":["「먹었다」는 형태가 바뀐 낱말이에요.","국어사전에는 기본형만 실려 있어요.","바뀌지 않는 부분 「먹」에 ‘-다’를 붙인 「먹다」를 찾아요."],"asset":{"type":"speech","turns":[{"who":"진영","text":"국어사전에는 첫 번째 글자의 첫 자음자가 같은 낱말끼리 모여 있어."},{"who":"선우","text":"그럼 ‘얼음’을 찾을 때 ‘ㄹ’로 시작하는 낱말이 있는 곳을 찾아야겠네."},{"who":"세희","text":"“맛있는 사과를 먹었다.”라는 문장에서 ‘먹었다’의 뜻이 궁금하면 ‘먹다’라는 낱말을 찾아야 해."},{"who":"민호","text":"국어사전에는 ‘맛있는’, ‘맛있고’, ‘맛있어서’처럼 형태가 바뀐 낱말이 모두 실려 있을 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#1','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C18',2,'mc','auto','『국어』 240쪽이에요. 국어사전에서 「친구」를 찾을 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X18','K3-2-u5-X15']::text[],false,'{"seq":1,"concept":"K3-2-u5-C18","difficulty":2,"kind":"mc","stem":"『국어』 240쪽이에요. 국어사전에서 「친구」를 찾을 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"첫 번째 글자 「친」의 첫 자음자 ㅊ으로 시작하는 낱말이 모인 곳을 찾는다","correct":true},{"t":"두 번째 글자 「구」의 ㄱ으로 시작하는 낱말부터 찾는다","mis":"K3-2-u5-X21"},{"t":"받침 ㄴ으로 시작하는 낱말이 모인 곳을 찾는다","mis":"K3-2-u5-X18"},{"t":"사전 맨 앞쪽부터 한 쪽씩 넘긴다","mis":"K3-2-u5-X15"}],"explanation":["먼저 첫 번째 글자 「친」을 찾아요.","「친」의 첫 자음자 ㅊ으로 시작하는 낱말이 모인 곳을 펴요.","그다음 모음자 → 받침 → 두 번째 글자 차례로 찾아요."],"asset":{"type":"passage","lines":["① 먼저 첫 번째 글자인 ‘친’을 찾아야 해.","② 첫 자음자인 (   )으로 시작하는 낱말은 여기에 모여 있어.","③ ‘층’으로 시작하는 낱말들이네. 더 뒤로 가야 해. ‘ㅊ’ 다음 모음자는 (   )야.","④ ‘치’로 시작하는 낱말들이네. 이제 받침 (   )을 찾아보자.","   여기는 ‘칙’이니까 다음에 곧 나오겠다.","⑤ 여기 있다! 이제 두 번째 글자인 ‘구’의 첫 자음자 ‘ㄱ’을 찾으면 돼.","⑥ 다음 모음자 (   )가 나올 때까지……. 찾았다!"],"title":"국어사전에서 ‘친구’ 찾기 — 『국어』 240쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#2','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C19',2,'blank','auto','『국어』 240쪽 ③이에요. 「‘ㅊ’ 다음에 이어지는 모음자는 (     )야.」 빈칸에 알맞은 낱자는 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X18']::text[],false,'{"seq":2,"concept":"K3-2-u5-C19","difficulty":2,"kind":"blank","stem":"『국어』 240쪽 ③이에요. 「‘ㅊ’ 다음에 이어지는 모음자는 (     )야.」 빈칸에 알맞은 낱자는 무엇인가요?","options":[{"t":"ㅣ","correct":true},{"t":"ㅡ","mis":"K3-2-u5-X20"},{"t":"ㅜ","mis":"K3-2-u5-X20"},{"t":"ㄴ","mis":"K3-2-u5-X18"}],"explanation":["「친」을 짜임대로 나누면 ㅊ · ㅣ · ㄴ이에요.","ㅊ 다음 모음자는 ㅣ예요.","ㅜ는 두 번째 글자 「구」의 모음자예요."],"asset":{"type":"passage","lines":["① 먼저 첫 번째 글자인 ‘친’을 찾아야 해.","② 첫 자음자인 (   )으로 시작하는 낱말은 여기에 모여 있어.","③ ‘층’으로 시작하는 낱말들이네. 더 뒤로 가야 해. ‘ㅊ’ 다음 모음자는 (   )야.","④ ‘치’로 시작하는 낱말들이네. 이제 받침 (   )을 찾아보자.","   여기는 ‘칙’이니까 다음에 곧 나오겠다.","⑤ 여기 있다! 이제 두 번째 글자인 ‘구’의 첫 자음자 ‘ㄱ’을 찾으면 돼.","⑥ 다음 모음자 (   )가 나올 때까지……. 찾았다!"],"title":"국어사전에서 ‘친구’ 찾기 — 『국어』 240쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#3','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C20',3,'mc','auto','『국어』 240쪽 ④예요. 「‘치’로 시작하는 낱말들이네. 이제 받침 (ㄴ)을 찾아보자. 여기는 ‘칙’이니까 다음에 곧 나오겠다.」 ‘칙’ 다음에 곧 ‘친’이 나오는 까닭은 무엇인가요?',ARRAY['K3-2-u5-X37','K3-2-u5-X21']::text[],false,'{"seq":3,"concept":"K3-2-u5-C20","difficulty":3,"kind":"mc","stem":"『국어』 240쪽 ④예요. 「‘치’로 시작하는 낱말들이네. 이제 받침 (ㄴ)을 찾아보자. 여기는 ‘칙’이니까 다음에 곧 나오겠다.」 ‘칙’ 다음에 곧 ‘친’이 나오는 까닭은 무엇인가요?","options":[{"t":"받침 ㄱ 다음에 받침 ㄴ이 오기 때문","correct":true},{"t":"받침 ㄴ이 ㄱ보다 앞이라서 ‘칙’ 앞에 ‘친’이 있기 때문","mis":"K3-2-u5-X37"},{"t":"받침이 없는 글자가 받침이 있는 글자보다 뒤에 오기 때문","mis":"K3-2-u5-X21"}],"explanation":["「칙」과 「친」은 첫 자음자와 모음자가 같아요.","받침도 자음자 차례로 보면 ㄱ이 ㄴ보다 앞이에요.","그래서 「칙」을 지나면 곧 「친」이 나와요."],"asset":{"type":"passage","lines":["① 먼저 첫 번째 글자인 ‘친’을 찾아야 해.","② 첫 자음자인 (   )으로 시작하는 낱말은 여기에 모여 있어.","③ ‘층’으로 시작하는 낱말들이네. 더 뒤로 가야 해. ‘ㅊ’ 다음 모음자는 (   )야.","④ ‘치’로 시작하는 낱말들이네. 이제 받침 (   )을 찾아보자.","   여기는 ‘칙’이니까 다음에 곧 나오겠다.","⑤ 여기 있다! 이제 두 번째 글자인 ‘구’의 첫 자음자 ‘ㄱ’을 찾으면 돼.","⑥ 다음 모음자 (   )가 나올 때까지……. 찾았다!"],"title":"국어사전에서 ‘친구’ 찾기 — 『국어』 240쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#4','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C19',3,'mc','auto','『국어』 240쪽 ③에서 ‘층’으로 시작하는 낱말을 보고 「더 뒤로 가야 해.」라고 했어요. 그 까닭은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X21']::text[],false,'{"seq":4,"concept":"K3-2-u5-C19","difficulty":3,"kind":"mc","stem":"『국어』 240쪽 ③에서 ‘층’으로 시작하는 낱말을 보고 「더 뒤로 가야 해.」라고 했어요. 그 까닭은 무엇인가요?","options":[{"t":"모음자 ㅡ가 ㅣ보다 앞이라서 「치」는 「층」보다 뒤에 있기 때문","correct":true},{"t":"모음자 ㅣ가 ㅡ보다 앞이라서 「치」는 「층」보다 앞에 있기 때문","mis":"K3-2-u5-X20"},{"t":"「층」은 받침이 있어서 「친」보다 무조건 앞에 있기 때문","mis":"K3-2-u5-X21"}],"explanation":["첫 자음자 ㅊ은 같아요.","모음자 차례에서 ㅡ 다음에 ㅢ, ㅣ가 와요.","그래서 「층」 다음, 더 뒤에 「치」가 있어요."],"asset":{"type":"passage","lines":["① 먼저 첫 번째 글자인 ‘친’을 찾아야 해.","② 첫 자음자인 (   )으로 시작하는 낱말은 여기에 모여 있어.","③ ‘층’으로 시작하는 낱말들이네. 더 뒤로 가야 해. ‘ㅊ’ 다음 모음자는 (   )야.","④ ‘치’로 시작하는 낱말들이네. 이제 받침 (   )을 찾아보자.","   여기는 ‘칙’이니까 다음에 곧 나오겠다.","⑤ 여기 있다! 이제 두 번째 글자인 ‘구’의 첫 자음자 ‘ㄱ’을 찾으면 돼.","⑥ 다음 모음자 (   )가 나올 때까지……. 찾았다!"],"title":"국어사전에서 ‘친구’ 찾기 — 『국어』 240쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#5','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C17',3,'mc','auto','『국어활동』 74쪽 선우의 말을 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u5-X36']::text[],false,'{"seq":5,"concept":"K3-2-u5-C17","difficulty":3,"kind":"mc","stem":"『국어활동』 74쪽 선우의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"「얼음」은 첫 자음자가 ㅇ이니 ㅇ으로 시작하는 낱말이 있는 곳에서 찾는다","correct":true},{"t":"「얼음」은 소리가 [어름]이니 ㄹ로 시작하는 곳에서 찾는다","mis":"K3-2-u5-X36"},{"t":"「얼음」은 모음자 ㅓ로 시작하는 곳에서 찾는다","mis":"K3-2-u5-X36"},{"t":"선우의 말이 맞다","mis":"K3-2-u5-X36"}],"explanation":["「얼」을 짜임대로 나누면 ㅇ · ㅓ · ㄹ이에요.","ㄹ은 받침이고 첫 자음자는 ㅇ이에요.","그래서 ㅇ으로 시작하는 낱말이 있는 곳에서 찾아요."],"asset":{"type":"speech","turns":[{"who":"진영","text":"국어사전에는 첫 번째 글자의 첫 자음자가 같은 낱말끼리 모여 있어."},{"who":"선우","text":"그럼 ‘얼음’을 찾을 때 ‘ㄹ’로 시작하는 낱말이 있는 곳을 찾아야겠네."},{"who":"세희","text":"“맛있는 사과를 먹었다.”라는 문장에서 ‘먹었다’의 뜻이 궁금하면 ‘먹다’라는 낱말을 찾아야 해."},{"who":"민호","text":"국어사전에는 ‘맛있는’, ‘맛있고’, ‘맛있어서’처럼 형태가 바뀐 낱말이 모두 실려 있을 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#6','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C22',3,'mc','auto','『국어활동』 74쪽 민호의 말을 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u5-X13','K3-2-u5-X23','K3-2-u5-X12']::text[],false,'{"seq":6,"concept":"K3-2-u5-C22","difficulty":3,"kind":"mc","stem":"『국어활동』 74쪽 민호의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"형태가 바뀌는 낱말은 국어사전에 기본형 「맛있다」만 실려 있다","correct":true},{"t":"민호의 말이 맞다","mis":"K3-2-u5-X13"},{"t":"국어사전에는 「맛있는」만 실려 있다","mis":"K3-2-u5-X23"},{"t":"「맛있고」는 틀린 말이라 실려 있지 않다","mis":"K3-2-u5-X12"}],"explanation":["형태가 바뀐 모양을 모두 실을 수는 없어요.","국어사전에는 기본형을 실어요.","「맛있는, 맛있고, 맛있어서」의 뜻은 「맛있다」에서 찾아요."],"asset":{"type":"speech","turns":[{"who":"진영","text":"국어사전에는 첫 번째 글자의 첫 자음자가 같은 낱말끼리 모여 있어."},{"who":"선우","text":"그럼 ‘얼음’을 찾을 때 ‘ㄹ’로 시작하는 낱말이 있는 곳을 찾아야겠네."},{"who":"세희","text":"“맛있는 사과를 먹었다.”라는 문장에서 ‘먹었다’의 뜻이 궁금하면 ‘먹다’라는 낱말을 찾아야 해."},{"who":"민호","text":"국어사전에는 ‘맛있는’, ‘맛있고’, ‘맛있어서’처럼 형태가 바뀐 낱말이 모두 실려 있을 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#7','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C21',3,'mc','auto','『국어활동』 75쪽 ㉰예요. 「한과, 학문, 하교, 한파」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X21']::text[],false,'{"seq":7,"concept":"K3-2-u5-C21","difficulty":3,"kind":"mc","stem":"『국어활동』 75쪽 ㉰예요. 「한과, 학문, 하교, 한파」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"하교 → 학문 → 한과 → 한파","correct":true},{"t":"한과 → 학문 → 하교 → 한파","mis":"K3-2-u5-X19"},{"t":"학문 → 하교 → 한과 → 한파","mis":"K3-2-u5-X21"},{"t":"하교 → 학문 → 한파 → 한과","mis":"K3-2-u5-X19"}],"explanation":["받침 없는 「하」가 먼저, 그다음 받침 ㄱ인 「학」, ㄴ인 「한」이에요.","「한과」와 「한파」는 두 번째 글자를 봐요.","ㄱ이 ㅍ보다 앞이니 「한과」가 먼저예요."],"asset":{"type":"passage","lines":["㉮ 너비 · 시루","㉯ 고요 · 겨레 · 구기","㉰ 한과 · 학문 · 하교 · 한파"],"title":"『국어활동』 75쪽 2번 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#8','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C19',4,'mc','auto','『국어활동』 75쪽 ㉯예요. 「고요, 겨레, 구기」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X20']::text[],false,'{"seq":8,"concept":"K3-2-u5-C19","difficulty":4,"kind":"mc","stem":"『국어활동』 75쪽 ㉯예요. 「고요, 겨레, 구기」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"겨레 → 고요 → 구기","correct":true},{"t":"고요 → 겨레 → 구기","mis":"K3-2-u5-X20"},{"t":"구기 → 고요 → 겨레","mis":"K3-2-u5-X20"},{"t":"겨레 → 구기 → 고요","mis":"K3-2-u5-X20"}],"explanation":["세 낱말의 첫 자음자는 모두 ㄱ이에요.","첫 번째 글자의 모음자를 보면 ㅕ, ㅗ, ㅜ예요.","모음자 차례는 ㅕ → ㅗ → ㅜ이니 「겨레 → 고요 → 구기」예요."],"asset":{"type":"passage","lines":["㉮ 너비 · 시루","㉯ 고요 · 겨레 · 구기","㉰ 한과 · 학문 · 하교 · 한파"],"title":"『국어활동』 75쪽 2번 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#9','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C22',4,'mc','auto','『국어』 241쪽이에요. 「조상의 얼이 깃든 도자기」에서 「깃든」의 뜻을 국어사전에서 찾으려면 어떻게 해야 하나요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":9,"concept":"K3-2-u5-C22","difficulty":4,"kind":"mc","stem":"『국어』 241쪽이에요. 「조상의 얼이 깃든 도자기」에서 「깃든」의 뜻을 국어사전에서 찾으려면 어떻게 해야 하나요?","options":[{"t":"기본형 「깃들다」로 바꾸어 찾는다","correct":true},{"t":"「깃든」을 그대로 찾는다","mis":"K3-2-u5-X23"},{"t":"「깃」만 찾는다","mis":"K3-2-u5-X11"},{"t":"「깃드다」로 바꾸어 찾는다","mis":"K3-2-u5-X11"}],"explanation":["「깃든」은 형태가 바뀐 낱말이에요.","형태가 바뀌는 낱말을 국어사전에서 찾을 때에는 기본형을 찾아야 해요.","「깃들다」는 「감정, 생각, 노력 따위가 어리거나 스미다.」라는 뜻이에요."],"asset":{"type":"passage","lines":["보건 — 건강을 온전하게 잘 지킴.","사흘 — 세 날.","얼 — 정신의 줏대.","깃들다 — 감정, 생각, 노력 따위가 어리거나 스미다."],"title":"국어사전에서 찾은 뜻 — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L08_challenge#10','kor',3,2,'u5','L08','tb_g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C18',4,'essay','teacher','『국어활동』 75쪽 ㉮ 「너비」와 「시루」 가운데에서 국어사전에 먼저 나오는 낱말과 그 까닭을 쓰고, 「시루」를 국어사전에서 찾는 과정을 『국어』 240쪽처럼 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C18","difficulty":4,"kind":"essay","stem":"『국어활동』 75쪽 ㉮ 「너비」와 「시루」 가운데에서 국어사전에 먼저 나오는 낱말과 그 까닭을 쓰고, 「시루」를 국어사전에서 찾는 과정을 『국어』 240쪽처럼 차례대로 쓰세요.","answer_guide":{"answer":"예: 먼저 나오는 낱말 — 너비. 까닭 — 첫 자음자가 「너비」는 ㄴ, 「시루」는 ㅅ인데 ㄴ이 ㅅ보다 앞이기 때문이다. 찾는 과정 — 먼저 첫 번째 글자 「시」의 첫 자음자 ㅅ으로 시작하는 곳을 찾는다. 모음자 ㅣ가 나올 때까지 넘긴다. 「시」는 받침이 없으니 「시」로 시작하는 낱말의 앞쪽을 본다. 두 번째 글자 「루」의 첫 자음자 ㄹ, 모음자 ㅜ를 찾으면 「시루」가 나온다.","scoring_points":["먼저 나오는 낱말 「너비」를 바르게 골랐는가","첫 자음자 차례로 까닭을 썼는가","첫 자음자 → 모음자 → 받침 → 두 번째 글자 차례로 찾는 과정을 썼는가"]},"explanation":["국어사전에는 첫 번째 글자의 첫 자음자가 같은 낱말끼리 모여 있어요.","자음자 → 모음자 → 받침 차례로 찾아요.","첫 번째 글자를 찾으면 두 번째 글자도 같은 방법으로 찾아요."],"asset":{"type":"passage","lines":["㉮ 너비 · 시루","㉯ 고요 · 겨레 · 구기","㉰ 한과 · 학문 · 하교 · 한파"],"title":"『국어활동』 75쪽 2번 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#1','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C2',1,'mc','auto','『국어』 242쪽 「경험 떠올리기」예요. 두 친구가 글을 읽다가 모르는 낱말이 나왔을 때 한 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X01','K3-2-u5-X02','K3-2-u5-X03']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 242쪽 「경험 떠올리기」예요. 두 친구가 글을 읽다가 모르는 낱말이 나왔을 때 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"사전을 찾아보거나 뜻을 짐작해 보았다","correct":true},{"t":"모르는 낱말을 건너뛰고 끝까지 읽었다","mis":"K3-2-u5-X01"},{"t":"읽기를 그만두었다","mis":"K3-2-u5-X02"},{"t":"아무 뜻이나 정하고 확인하지 않았다","mis":"K3-2-u5-X03"}],"explanation":["한 친구는 놀이 방법을 보다가 사전을 찾아봤어요.","한 친구는 조립 설명서를 보다가 뜻을 짐작해 봤어요.","모르는 낱말은 짐작하거나 사전으로 알아볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"놀이 방법을 보다가 모르는 낱말이 나와서 사전을 찾아봤어."},{"who":"친구 2","text":"조립 설명서에 모르는 낱말이 나와서 뜻을 짐작해 봤어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#2','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',1,'mc','auto','「아직도 미지의 세계는 남아 있다」를 읽다가 뜻을 잘 모르는 낱말이 나왔어요. 처음에 어떻게 하면 좋을까요?',ARRAY['K3-2-u5-X02','K3-2-u5-X01','K3-2-u5-X03']::text[],false,'{"seq":2,"concept":"K3-2-u5-C24","difficulty":1,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」를 읽다가 뜻을 잘 모르는 낱말이 나왔어요. 처음에 어떻게 하면 좋을까요?","options":[{"t":"밑줄을 긋고 뜻을 짐작하며 계속 읽는다","correct":true},{"t":"멈추어서 바로 국어사전부터 찾는다","mis":"K3-2-u5-X02"},{"t":"모르는 낱말은 건너뛰고 표시도 하지 않는다","mis":"K3-2-u5-X01"},{"t":"짐작한 뜻을 맞는 뜻으로 정하고 끝낸다","mis":"K3-2-u5-X03"}],"explanation":["뜻을 모르는 낱말에 밑줄을 그으며 읽어요.","멈추지 않고 우선 뜻을 짐작하며 읽어요.","다 읽은 뒤 국어사전에서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#3','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C34',1,'blank','auto','「아직도 미지의 세계는 남아 있다」의 첫 문장이에요. 「인간은 잘 모르거나 알려지지 않은 세계에 대한 (     )에서 여행을 합니다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":3,"concept":"K3-2-u5-C34","difficulty":1,"kind":"blank","stem":"「아직도 미지의 세계는 남아 있다」의 첫 문장이에요. 「인간은 잘 모르거나 알려지지 않은 세계에 대한 (     )에서 여행을 합니다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"호기심","correct":true},{"t":"두려움","mis":"K3-2-u5-X17"},{"t":"욕심","mis":"K3-2-u5-X17"},{"t":"심심함","mis":"K3-2-u5-X17"}],"explanation":["글의 첫 문장을 다시 읽어요.","인간은 잘 모르거나 알려지지 않은 세계에 호기심을 가져요.","그래서 여행과 모험을 하며 지도를 만들었어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#4','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C34',1,'sa','auto','「아직도 미지의 세계는 남아 있다」에서 땅속 세계에 관심을 가지게 되어 생겨난 지도는 무엇에 대한 지도인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u5-C34","difficulty":1,"kind":"sa","stem":"「아직도 미지의 세계는 남아 있다」에서 땅속 세계에 관심을 가지게 되어 생겨난 지도는 무엇에 대한 지도인가요? 두 글자로 쓰세요.","answer":["암석"],"explanation":["땅속에 관심을 갖기 시작한 부분을 찾아요.","답사와 연구를 거듭한 끝에 땅속을 이루는 암석에 대한 지도를 만들었어요.","답은 「암석」이에요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]},"mis":"K3-2-u5-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#5','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',2,'mc','auto','『국어』 245쪽이에요. 두 친구가 ‘미지’의 뜻을 짐작한 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25','K3-2-u5-X02']::text[],false,'{"seq":5,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"『국어』 245쪽이에요. 두 친구가 ‘미지’의 뜻을 짐작한 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"앞뒤 내용을 살펴보고, 다른 낱말로 바꾸어 문장의 뜻이 통하는지 보았다","correct":true},{"t":"낱말의 소리가 비슷한 다른 낱말을 떠올렸다","mis":"K3-2-u5-X25"},{"t":"낱말의 글자 수를 세었다","mis":"K3-2-u5-X25"},{"t":"짐작하지 않고 바로 사전을 찾았다","mis":"K3-2-u5-X02"}],"explanation":["한 친구는 뒤에 이어지는 문장을 살펴보았어요.","한 친구는 ‘미지’를 ‘새로운’으로 바꾸어 읽어 보았어요.","두 방법 모두 낱말의 뜻을 짐작할 때 도움이 돼요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"뒤에 이어지는 문장을 보면 ‘세상의 잘 모르는 곳을 구석구석 다니는 사람들’이라는 내용이 나와. ‘미지’는 잘 모른다는 뜻이 아닐까?"},{"who":"친구 2","text":"‘미지’를 ‘새로운’으로 바꾸어도 문장의 뜻이 통하는 것을 보면 새롭다는 뜻일 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#6','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',2,'mc','auto','『국어』 245쪽 (3)이에요. 「육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.」에서 ‘표면’의 뜻을 짐작해 보세요. 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X17','K3-2-u5-X25']::text[],false,'{"seq":6,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"『국어』 245쪽 (3)이에요. 「육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.」에서 ‘표면’의 뜻을 짐작해 보세요. 가장 알맞은 것은 무엇인가요?","options":[{"t":"겉 부분","correct":true},{"t":"땅속 깊은 곳","mis":"K3-2-u5-X17"},{"t":"표를 붙여 둔 면","mis":"K3-2-u5-X25"},{"t":"지도를 그리는 종이","mis":"K3-2-u5-X25"}],"explanation":["‘표면’은 ‘땅속’과 맞서는 말로 쓰였어요.","땅속이 아니라면 땅의 겉 부분이에요.","소리나 글자 모양만 보고 짐작하지 않아요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#7','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C25',2,'mc','auto','『국어』 246쪽이에요. ‘미지’의 뜻을 「잘 모르거나 새로움」으로 짐작했는데 국어사전에는 「아직 알지 못함」이라고 실려 있어요. 어떻게 하면 좋을까요?',ARRAY['K3-2-u5-X26']::text[],false,'{"seq":7,"concept":"K3-2-u5-C25","difficulty":2,"kind":"mc","stem":"『국어』 246쪽이에요. ‘미지’의 뜻을 「잘 모르거나 새로움」으로 짐작했는데 국어사전에는 「아직 알지 못함」이라고 실려 있어요. 어떻게 하면 좋을까요?","options":[{"t":"국어사전의 뜻으로 알고 그 부분을 다시 읽는다","correct":true},{"t":"내 짐작이 맞고 사전이 틀렸다고 생각한다","mis":"K3-2-u5-X26"},{"t":"짐작이 사전과 달랐으니 이 글은 이제 읽을 수 없다","mis":"K3-2-u5-X26"}],"explanation":["짐작한 뜻과 사전의 뜻을 견주어 봐요.","다르면 사전의 뜻으로 고쳐 알아요.","그 뜻을 넣어 다시 읽으면 내용이 더 정확해져요."],"asset":{"type":"passage","lines":["낱말 — 짐작한 뜻 — 국어사전에서 찾은 뜻","미지 — 잘 모르거나 새로움. — 아직 알지 못함.","표면 — 겉 부분. — 사물의 가장 바깥쪽."],"title":"낱말의 뜻 찾아보기 (예시) — 『국어』 246쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#8','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C26',2,'mc','auto','『국어』 246쪽 (2)예요. 국어사전을 활용해 글을 읽으면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X28','K3-2-u5-X01','K3-2-u5-X03']::text[],false,'{"seq":8,"concept":"K3-2-u5-C26","difficulty":2,"kind":"mc","stem":"『국어』 246쪽 (2)예요. 국어사전을 활용해 글을 읽으면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"어려운 낱말의 뜻을 알게 되어 글의 내용을 정확하게 이해할 수 있다","correct":true},{"t":"글을 더 빨리 읽을 수 있다","mis":"K3-2-u5-X28"},{"t":"모르는 낱말을 건너뛰어도 된다","mis":"K3-2-u5-X01"},{"t":"짐작할 필요가 없어진다","mis":"K3-2-u5-X03"}],"explanation":["어려운 낱말의 뜻을 알면 글의 내용을 정확하게 이해할 수 있어요.","내가 짐작한 뜻이 맞는지도 확인할 수 있어요.","빨리 읽으려고 사전을 쓰는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#9','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C34',2,'mc','auto','「아직도 미지의 세계는 남아 있다」에서 바다와 관련 있는 지도로 나온 것은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":9,"concept":"K3-2-u5-C34","difficulty":2,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」에서 바다와 관련 있는 지도로 나온 것은 무엇인가요?","options":[{"t":"해저 지도, 해류의 흐름을 나타낸 지도, 수온의 분포를 나타낸 지도","correct":true},{"t":"땅속 암석 지도, 우주 지도","mis":"K3-2-u5-X17"},{"t":"세계 지도, 사람 마음속 지도","mis":"K3-2-u5-X17"},{"t":"학교 안내도, 버스 노선도","mis":"K3-2-u5-X17"}],"explanation":["바다 밑을 지도로 만들기 시작한 부분을 찾아요.","바다 자원을 찾으려고 여러 바다 지도를 만들었어요.","해저 지도, 해류의 흐름 지도, 수온의 분포 지도예요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_basic#10','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C34',3,'mc','auto','『국어』 247쪽 「내용 알기」예요. 지도를 「탐험의 성과가 알알이 박혀 있는 결과물」이라고 나타낸 까닭은 무엇인가요?',ARRAY['K3-2-u5-X40','K3-2-u5-X17']::text[],false,'{"seq":10,"concept":"K3-2-u5-C34","difficulty":3,"kind":"mc","stem":"『국어』 247쪽 「내용 알기」예요. 지도를 「탐험의 성과가 알알이 박혀 있는 결과물」이라고 나타낸 까닭은 무엇인가요?","options":[{"t":"인간이 세상 구석구석을 탐험해서 알아낸 것을 모아 지도를 만들었기 때문","correct":true},{"t":"지도에 보석 같은 알갱이가 정말 박혀 있기 때문","mis":"K3-2-u5-X40"},{"t":"지도는 아무나 쉽게 만들 수 있기 때문","mis":"K3-2-u5-X17"},{"t":"탐험을 하지 않고 상상으로 그렸기 때문","mis":"K3-2-u5-X17"}],"explanation":["「알알이 박혀 있다」는 빗대어 나타낸 말이에요.","탐험해서 알아낸 것 하나하나가 지도에 담겨 있다는 뜻이에요.","많은 사람의 탐험 덕에 거의 완벽한 세계 지도를 가지게 되었어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#1','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C24',2,'mc','auto','『국어』 245쪽 (2)예요. 낱말의 뜻을 짐작하는 방법 두 가지를 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X25','K3-2-u5-X03','K3-2-u5-X02']::text[],false,'{"seq":1,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"『국어』 245쪽 (2)예요. 낱말의 뜻을 짐작하는 방법 두 가지를 바르게 묶은 것은 무엇인가요?","options":[{"t":"낱말의 앞뒤 내용을 살펴본다 · 다른 낱말로 바꾸어 문장의 뜻이 통하는지 본다","correct":true},{"t":"낱말을 크게 여러 번 읽는다 · 글자 모양을 본다","mis":"K3-2-u5-X25"},{"t":"앞뒤 내용을 살펴본다 · 짐작한 뒤에는 확인하지 않는다","mis":"K3-2-u5-X03"},{"t":"바로 사전을 찾는다 · 모르는 줄은 건너뛴다","mis":"K3-2-u5-X02"}],"explanation":["앞뒤 내용에 낱말의 뜻을 알려 주는 실마리가 있어요.","다른 낱말로 바꾸어 뜻이 통하면 짐작이 가까워요.","짐작한 뒤에는 국어사전으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#2','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C25',2,'mc','auto','『국어』 246쪽이에요. ‘표면’을 「겉 부분」으로 짐작했고, 국어사전에는 「사물의 가장 바깥쪽」이라고 실려 있어요. 이 짐작에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X27','K3-2-u5-X26']::text[],false,'{"seq":2,"concept":"K3-2-u5-C25","difficulty":2,"kind":"mc","stem":"『국어』 246쪽이에요. ‘표면’을 「겉 부분」으로 짐작했고, 국어사전에는 「사물의 가장 바깥쪽」이라고 실려 있어요. 이 짐작에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"말은 조금 달라도 뜻이 비슷하니 짐작이 맞았다고 볼 수 있다","correct":true},{"t":"말이 다르니 짐작이 틀렸다","mis":"K3-2-u5-X27"},{"t":"사전의 뜻이 틀렸다","mis":"K3-2-u5-X26"}],"explanation":["「겉 부분」과 「사물의 가장 바깥쪽」은 뜻이 같아요.","말이 똑같지 않아도 뜻이 같으면 돼요.","사전으로 확인하면 짐작이 맞았는지 알 수 있어요."],"asset":{"type":"passage","lines":["낱말 — 짐작한 뜻 — 국어사전에서 찾은 뜻","미지 — 잘 모르거나 새로움. — 아직 알지 못함.","표면 — 겉 부분. — 사물의 가장 바깥쪽."],"title":"낱말의 뜻 찾아보기 (예시) — 『국어』 246쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#3','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C34',3,'mc','auto','「아직도 미지의 세계는 남아 있다」에서 인간이 새로운 곳을 찾아 나선 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":3,"concept":"K3-2-u5-C34","difficulty":3,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」에서 인간이 새로운 곳을 찾아 나선 차례로 알맞은 것은 무엇인가요?","options":[{"t":"아메리카와 남극 → 바닷속 세상 → 달과 다른 행성","correct":true},{"t":"달과 다른 행성 → 바닷속 세상 → 아메리카와 남극","mis":"K3-2-u5-X17"},{"t":"바닷속 세상 → 아메리카와 남극 → 달과 다른 행성","mis":"K3-2-u5-X17"},{"t":"아메리카와 남극 → 달과 다른 행성 → 바닷속 세상","mis":"K3-2-u5-X17"}],"explanation":["보물섬을 찾던 서양 사람들이 아메리카를 발견했고 남극도 알려졌어요.","더 발견할 땅이 없다고 생각했을 때 바닷속 세상을 떠올렸어요.","그 뒤 달에도 가 보고 다른 행성들을 관찰했어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#4','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C26',3,'mc','auto','「아직도 미지의 세계는 남아 있다」를 읽다가 표시한 낱말을 국어사전에서 찾았더니 뜻이 여러 개 실려 있어요. 어떻게 하면 좋을까요?',ARRAY['K3-2-u5-X38','K3-2-u5-X01']::text[],false,'{"seq":4,"concept":"K3-2-u5-C26","difficulty":3,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」를 읽다가 표시한 낱말을 국어사전에서 찾았더니 뜻이 여러 개 실려 있어요. 어떻게 하면 좋을까요?","options":[{"t":"뜻을 하나씩 그 문장에 넣어 읽어 보고, 글의 흐름에 자연스러운 뜻을 고른다","correct":true},{"t":"사전에 맨 먼저 나온 뜻을 그대로 고른다","mis":"K3-2-u5-X38"},{"t":"어느 뜻을 골라도 상관없다","mis":"K3-2-u5-X38"},{"t":"뜻이 여러 개인 낱말은 찾지 않고 건너뛴다","mis":"K3-2-u5-X01"}],"explanation":["한 낱말에 뜻이 여러 개 실려 있을 수 있어요.","뜻을 하나씩 문장에 넣어 읽어 보면 알맞은 뜻이 드러나요.","글의 앞뒤에 자연스럽게 이어지는 뜻을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#5','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C22',3,'mc','auto','「많은 사람이 탐험을 거듭할수록」의 ‘거듭할수록’을 국어사전에서 찾으려고 해요. 어떤 낱말을 찾아야 하나요?',ARRAY['K3-2-u5-X23']::text[],false,'{"seq":5,"concept":"K3-2-u5-C22","difficulty":3,"kind":"mc","stem":"「많은 사람이 탐험을 거듭할수록」의 ‘거듭할수록’을 국어사전에서 찾으려고 해요. 어떤 낱말을 찾아야 하나요?","options":[{"t":"거듭하다","correct":true},{"t":"거듭할수록","mis":"K3-2-u5-X23"},{"t":"거듭하니","mis":"K3-2-u5-X23"}],"explanation":["‘거듭할수록’은 형태가 바뀐 낱말이에요.","기본형으로 바꾸어 찾아요.","기본형 ‘거듭하다’를 찾아 뜻을 확인하고 문장을 다시 읽어요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#6','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C24',3,'error','auto','친구들이 ‘미지’의 뜻을 짐작했어요. 알맞지 않은 방법으로 짐작한 친구는 누구인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":6,"concept":"K3-2-u5-C24","difficulty":3,"kind":"error","stem":"친구들이 ‘미지’의 뜻을 짐작했어요. 알맞지 않은 방법으로 짐작한 친구는 누구인가요?","options":[{"t":"도하: ‘미지’는 소리가 ‘미지근하다’와 비슷하니 미지근한 곳이라는 뜻일 거야.","correct":true,"mis_target":"K3-2-u5-X25"},{"t":"서진: 뒤 문장 「세상의 잘 모르는 곳을 구석구석 다닌 사람들」을 보니 잘 모른다는 뜻 같아.","mis":"K3-2-u5-X25"},{"t":"유나: ‘미지의 세계’를 ‘새로운 세계’로 바꾸어도 뜻이 통해.","mis":"K3-2-u5-X25"}],"explanation":["소리가 비슷하다고 뜻이 같은 것은 아니에요.","앞뒤 내용을 살피거나 다른 낱말로 바꾸어 짐작해요.","도하는 소리만 보고 짐작했어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#7','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C34',3,'mc','auto','「아직도 미지의 세계는 남아 있다」에서 바다 탐험은 선진국이 중심이 되었다고 했어요. 그 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":7,"concept":"K3-2-u5-C34","difficulty":3,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」에서 바다 탐험은 선진국이 중심이 되었다고 했어요. 그 까닭은 무엇인가요?","options":[{"t":"바다 탐험에는 비싼 장비가 많이 필요하기 때문","correct":true},{"t":"바다가 선진국에만 있기 때문","mis":"K3-2-u5-X17"},{"t":"땅속 지도를 먼저 만들어야 하기 때문","mis":"K3-2-u5-X17"},{"t":"바다에는 자원이 없기 때문","mis":"K3-2-u5-X17"}],"explanation":["바다 밑을 지도로 만들기 시작한 부분을 다시 읽어요.","바다 탐험은 비싼 장비가 많이 필요했어요.","그래서 선진국이 중심이 되었어요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#8','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C34',4,'essay','teacher','『국어』 247쪽 「세상과 연결하기」예요. 자신이 만들고 싶은 지도를 정하고, 만들고 싶은 까닭과 그 지도의 쓰임새를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u5-C34","difficulty":4,"kind":"essay","stem":"『국어』 247쪽 「세상과 연결하기」예요. 자신이 만들고 싶은 지도를 정하고, 만들고 싶은 까닭과 그 지도의 쓰임새를 쓰세요.","answer_guide":{"answer":"예: 지도 — 우리 동네 쉼터 지도. 까닭 — 더운 날 할머니, 할아버지께서 쉬어 갈 곳을 몰라 힘들어하시는 것을 보았다. 쓰임새 — 그늘이 있는 쉼터와 물을 마실 수 있는 곳을 표시해 누구나 쉽게 쉬어 갈 수 있다.","scoring_points":["만들고 싶은 지도를 정했는가","그 지도를 만들고 싶은 까닭을 썼는가","그 지도가 사람들에게 어떻게 쓰일지, 어떤 가치가 있는지 썼는가"]},"explanation":["인간이 아직 탐험하지 못한 곳이나 자신의 관심 분야를 떠올려요.","우주 지도, 사람 마음속 지도처럼 자유롭게 생각해도 돼요.","그 지도가 사람들에게 어떤 도움이 될지까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#9','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C25',4,'essay','teacher','「지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,」에서 ‘길잡이’의 뜻을 짐작하는 방법과 짐작한 뜻을 쓰고, 국어사전으로 확인한 뒤에 할 일을 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C25","difficulty":4,"kind":"essay","stem":"「지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,」에서 ‘길잡이’의 뜻을 짐작하는 방법과 짐작한 뜻을 쓰고, 국어사전으로 확인한 뒤에 할 일을 차례대로 쓰세요.","answer_guide":{"answer":"예: 방법 — ‘길잡이’를 ‘안내자’로 바꾸어 읽어 보니 뜻이 통하고, 탐험하는 사람들에게 지도가 길을 알려 주었다는 앞뒤 내용이 있다. 짐작한 뜻 — 길을 알려 주는 것. 할 일 — 국어사전에서 ‘길잡이’를 찾아 짐작한 뜻과 비교한다. 다르면 사전의 뜻으로 고쳐 알고, 그 문장을 다시 읽어 내용을 정확히 이해한다.","scoring_points":["앞뒤 내용 살피기나 다른 낱말로 바꾸기로 짐작하는 방법을 썼는가","문장에 어울리게 뜻을 짐작해 썼는가","사전에서 찾아 비교하고, 다시 읽는 차례를 썼는가"]},"explanation":["짐작은 앞뒤 내용과 바꾸어 읽기로 해요.","짐작한 뜻은 국어사전에서 확인해요.","확인한 뜻을 넣어 다시 읽으면 글을 정확하게 이해할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L10_challenge#10','kor',3,2,'u5','L10','tb_g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C26',4,'mc','auto','조립 설명서를 읽다가 모르는 낱말이 여러 개 나왔어요. 국어사전을 활용하며 읽는 차례로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X02','K3-2-u5-X23','K3-2-u5-X03']::text[],false,'{"seq":10,"concept":"K3-2-u5-C26","difficulty":4,"kind":"mc","stem":"조립 설명서를 읽다가 모르는 낱말이 여러 개 나왔어요. 국어사전을 활용하며 읽는 차례로 가장 알맞은 것은 무엇인가요?","options":[{"t":"밑줄을 긋고 짐작하며 끝까지 읽기 → 기본형으로 바꾸어 사전에서 찾기 → 짐작과 비교하기 → 다시 읽기","correct":true},{"t":"모르는 낱말이 나올 때마다 멈추어 사전 찾기 → 다음 줄 읽기","mis":"K3-2-u5-X02"},{"t":"짐작하며 끝까지 읽기 → 바뀐 모양 그대로 사전에서 찾기 → 다시 읽기","mis":"K3-2-u5-X23"},{"t":"짐작하며 끝까지 읽기 → 짐작한 뜻을 그대로 믿고 조립하기","mis":"K3-2-u5-X03"}],"explanation":["먼저 뜻을 짐작하며 끝까지 읽어요.","형태가 바뀐 낱말은 기본형으로 바꾸어 사전에서 찾아요.","짐작한 뜻과 견주어 보고 다시 읽으면 정확하게 이해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#1','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C27',1,'mc','auto','『국어』 248쪽 「세 가지 단서로 낱말 놀이 하기」예요. 단서 카드에 쓰는 세 가지 단서는 무엇인가요?',ARRAY['K3-2-u5-X15','K3-2-u5-X29','K3-2-u5-X30']::text[],false,'{"seq":1,"concept":"K3-2-u5-C27","difficulty":1,"kind":"mc","stem":"『국어』 248쪽 「세 가지 단서로 낱말 놀이 하기」예요. 단서 카드에 쓰는 세 가지 단서는 무엇인가요?","options":[{"t":"낱말의 종류, 낱말의 뜻, 낱말이 쓰이는 문장","correct":true},{"t":"낱말의 글자 수, 첫 글자, 끝 글자","mis":"K3-2-u5-X15"},{"t":"낱말 그대로, 낱말의 뜻, 낱말의 종류","mis":"K3-2-u5-X29"},{"t":"낱말을 쓴 친구 이름, 쓴 날짜, 낱말","mis":"K3-2-u5-X30"}],"explanation":["단서는 ‘낱말의 종류’, ‘낱말의 뜻’, ‘낱말이 쓰이는 문장’의 세 가지예요.","단서를 카드에 하나씩 써요.","낱말을 그대로 쓰면 단서가 아니라 답이 돼요."],"asset":{"type":"passage","lines":["① 정한 낱말에 대한 단서를 카드에 하나씩 쓴다.","② 단서는 ‘낱말의 종류’, ‘낱말의 뜻’, ‘낱말이 쓰이는 문장’의 세 가지로 한다.","③ 단서 카드는 모두 뒤집어 책상 위에 놓는다.","④ 가위바위보를 하여 이긴 사람부터 상대의 단서 카드를 하나씩 열어 본다.","⑤ 상대의 낱말을 먼저 알아맞힌 사람이 이긴다."],"title":"세 가지 단서로 낱말 놀이 하기 — 『국어』 248쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#2','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C27',1,'mc','auto','『국어』 248쪽 보기의 단서 카드 세 장이에요. 알아맞힐 낱말은 무엇인가요?',ARRAY['K3-2-u5-X17','K3-2-u5-X04']::text[],false,'{"seq":2,"concept":"K3-2-u5-C27","difficulty":1,"kind":"mc","stem":"『국어』 248쪽 보기의 단서 카드 세 장이에요. 알아맞힐 낱말은 무엇인가요?","options":[{"t":"학교","correct":true},{"t":"선생님","mis":"K3-2-u5-X17"},{"t":"가르치다","mis":"K3-2-u5-X04"},{"t":"교과서","mis":"K3-2-u5-X17"}],"explanation":["종류 단서를 보면 이름을 나타내는 낱말이에요.","뜻 단서는 「학생을 가르치는 교육 기관」이에요.","「나는 날마다 (학교)에 간다.」가 자연스러워요."],"asset":{"type":"passage","lines":["종류 — 이름을 나타내는 낱말","뜻 — 학생을 가르치는 교육 기관.","문장 — 나는 날마다 (     )에 간다."],"title":"단서 카드 세 장 — 『국어』 248쪽 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#3','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C29',1,'mc','auto','세 가지 단서로 낱말 놀이를 할 때 가장 중요하게 생각할 것은 무엇인가요?',ARRAY['K3-2-u5-X31','K3-2-u5-X29']::text[],false,'{"seq":3,"concept":"K3-2-u5-C29","difficulty":1,"kind":"mc","stem":"세 가지 단서로 낱말 놀이를 할 때 가장 중요하게 생각할 것은 무엇인가요?","options":[{"t":"단서를 보며 낱말을 추리하는 과정을 즐기는 것","correct":true},{"t":"어떻게 해서든 반드시 이기는 것","mis":"K3-2-u5-X31"},{"t":"상대가 못 맞히게 낱말을 그대로 적는 것","mis":"K3-2-u5-X29"},{"t":"못 맞힌 낱말은 그냥 넘어가는 것","mis":"K3-2-u5-X31"}],"explanation":["놀이를 할 때 이기고 지는 것에 너무 마음 쓰지 않아요.","단서를 보며 낱말을 헤아리는 과정이 즐거워요.","못 맞힌 낱말은 국어사전에서 함께 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#4','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C28',1,'mc','auto','『국어』 249쪽 「나만의 국어사전 만들기」의 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X30']::text[],false,'{"seq":4,"concept":"K3-2-u5-C28","difficulty":1,"kind":"mc","stem":"『국어』 249쪽 「나만의 국어사전 만들기」의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"낱말 모으기 → 종류와 뜻 쓰기 → 싣는 차례로 순서 정하기 → 그림 그려 완성하기","correct":true},{"t":"그림 그리기 → 낱말 모으기 → 종류와 뜻 쓰기 → 순서 정하기","mis":"K3-2-u5-X30"},{"t":"낱말 모으기 → 그림 그리기 → 모은 차례대로 묶기","mis":"K3-2-u5-X30"},{"t":"순서 정하기 → 낱말 모으기 → 뜻 쓰기 → 그림 그리기","mis":"K3-2-u5-X30"}],"explanation":["① 생활 속에서 뜻이 궁금한 낱말을 모아요.","② 국어사전으로 종류와 뜻을 쓰고, ③ 싣는 차례대로 순서를 정해요.","④ 낱말 뜻에 어울리는 그림을 그려 완성해요."],"asset":{"type":"passage","lines":["① 생활 속에서 뜻이 궁금한 낱말 모으기","② 국어사전을 활용해 낱말의 종류와 뜻 쓰기","③ 낱말을 싣는 차례를 생각하며 낱말의 순서 정하기","④ 낱말 뜻에 어울리는 그림을 그려 사전 완성하기","[그림] 책 모양 · 종 모양 · 고리로 묶은 책 모양 · 병풍 모양"],"title":"나만의 국어사전 만들기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#5','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C28',2,'mc','auto','나만의 국어사전에 넣으려고 「솜이불, 담요, 갈무리, 마무리」를 모았어요. 국어사전에 싣는 차례대로 바르게 정한 것은 무엇인가요?',ARRAY['K3-2-u5-X30','K3-2-u5-X22','K3-2-u5-X19']::text[],false,'{"seq":5,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"나만의 국어사전에 넣으려고 「솜이불, 담요, 갈무리, 마무리」를 모았어요. 국어사전에 싣는 차례대로 바르게 정한 것은 무엇인가요?","options":[{"t":"갈무리 → 담요 → 마무리 → 솜이불","correct":true},{"t":"솜이불 → 담요 → 갈무리 → 마무리","mis":"K3-2-u5-X30"},{"t":"담요 → 갈무리 → 솜이불 → 마무리","mis":"K3-2-u5-X22"},{"t":"마무리 → 갈무리 → 담요 → 솜이불","mis":"K3-2-u5-X19"}],"explanation":["첫 자음자를 보면 ㄱ(갈무리), ㄷ(담요), ㅁ(마무리), ㅅ(솜이불)이에요.","자음자 차례 ㄱ → ㄷ → ㅁ → ㅅ대로 놓아요.","모은 차례나 글자 수로 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#6','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C30',2,'mc','auto','『국어』 252쪽 1번이에요. 다음 가운데 ‘ㄴ’ 소리가 더해져 소리 나는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":6,"concept":"K3-2-u5-C30","difficulty":2,"kind":"mc","stem":"『국어』 252쪽 1번이에요. 다음 가운데 ‘ㄴ’ 소리가 더해져 소리 나는 낱말은 무엇인가요?","options":[{"t":"맨입","correct":true},{"t":"나이","mis":"K3-2-u5-X32"},{"t":"우유","mis":"K3-2-u5-X32"}],"explanation":["받침 뒤에 ‘이, 야, 여, 요, 유’가 오면 ‘ㄴ’ 소리가 더해지는 경우가 많아요.","「맨입」은 받침 ㄴ 뒤에 「입」이 와서 [맨닙]으로 소리 나요.","「나이」, 「우유」는 앞 글자에 받침이 없어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#7','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C30',2,'sa','auto','『국어』 252쪽 1번이에요. 「담요」는 어떻게 소리 나나요? 대괄호 없이 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u5-C30","difficulty":2,"kind":"sa","stem":"『국어』 252쪽 1번이에요. 「담요」는 어떻게 소리 나나요? 대괄호 없이 소리 나는 대로 쓰세요.","answer":["담뇨"],"explanation":["받침 ㅁ 뒤에 「요」가 왔어요.","‘ㄴ’ 소리가 더해져 [담뇨]로 소리 나요.","쓸 때는 「담요」로 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]},"mis":"K3-2-u5-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#8','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C31',2,'match','auto','『국어』 252쪽 2번이에요. 우리말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u5-C31","difficulty":2,"kind":"match","stem":"『국어』 252쪽 2번이에요. 우리말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"마무리","r":"일의 끝맺음."},{"l":"갈무리","r":"물건 따위를 잘 정리함."},{"l":"또바기","r":"언제나 한결같이 꼭 그렇게."}],"mis":"K3-2-u5-X34","explanation":["「만들기를 거의 마무리했다」 — 일을 끝맺었다는 뜻이에요.","「옷들을 계절별로 갈무리해」 — 잘 정리했다는 뜻이에요.","「나와 또바기 함께 있어 주렴」 — 언제나 한결같이라는 뜻이에요."],"asset":{"type":"passage","lines":["나만의 낱말 사전 만들기를 거의 마무리했다.","옷들을 계절별로 갈무리해 옷장에 넣었다."],"title":"『국어』 252쪽 2번","hi":["마무리","갈무리"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#9','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C32',2,'blank','auto','『국어』 253쪽 글씨 쓰기예요. 「횃불」의 ‘ㅙ’는 두 모음자가 붙은 거예요. 「ㅙ = ㅗ + (     )」 빈칸에 알맞은 모음자는 무엇인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":9,"concept":"K3-2-u5-C32","difficulty":2,"kind":"blank","stem":"『국어』 253쪽 글씨 쓰기예요. 「횃불」의 ‘ㅙ’는 두 모음자가 붙은 거예요. 「ㅙ = ㅗ + (     )」 빈칸에 알맞은 모음자는 무엇인가요?","options":[{"t":"ㅐ","correct":true},{"t":"ㅏ","mis":"K3-2-u5-X35"},{"t":"ㅣ","mis":"K3-2-u5-X35"},{"t":"ㅔ","mis":"K3-2-u5-X35"}],"explanation":["‘ㅘ’는 ㅗ와 ㅏ, ‘ㅚ’는 ㅗ와 ㅣ가 붙은 거예요.","‘ㅙ’는 ㅗ와 ㅐ가 붙은 거예요.","두 모음자가 어느 쪽에 붙는지 살피며 바르게 써요."],"asset":{"type":"passage","lines":["과자 · 영화 · 완성 · 돼지","횃불 · 괴물 · 횡단보도"],"title":"글씨를 바르게 써 봅시다 — 『국어』 253쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_basic#10','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C30',3,'error','auto','「솜이불, 맨입, 담요」를 읽고 쓰는 방법을 친구들이 말했어요. 잘못한 친구는 누구인가요?',ARRAY['K3-2-u5-X33']::text[],false,'{"seq":10,"concept":"K3-2-u5-C30","difficulty":3,"kind":"error","stem":"「솜이불, 맨입, 담요」를 읽고 쓰는 방법을 친구들이 말했어요. 잘못한 친구는 누구인가요?","options":[{"t":"하람: 「맨입」을 공책에 「맨닙」이라고 썼어.","correct":true,"mis_target":"K3-2-u5-X33"},{"t":"은솔: 「솜이불」을 [솜니불]로 읽었어.","mis":"K3-2-u5-X33"},{"t":"지후: 「담요」를 공책에 「담요」라고 썼어.","mis":"K3-2-u5-X33"}],"explanation":["‘ㄴ’ 소리가 더해지는 것은 소리 낼 때예요.","쓸 때는 원래 글자대로 「맨입」이라고 써요.","그래서 하람이가 잘못했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#1','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C27',2,'mc','auto','알아맞힐 낱말이 「우산」이에요. ‘낱말이 쓰이는 문장’ 단서로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X29','K3-2-u5-X17']::text[],false,'{"seq":1,"concept":"K3-2-u5-C27","difficulty":2,"kind":"mc","stem":"알아맞힐 낱말이 「우산」이에요. ‘낱말이 쓰이는 문장’ 단서로 알맞은 것은 무엇인가요?","options":[{"t":"비가 와서 (     )을 썼다.","correct":true},{"t":"비가 와서 우산을 썼다.","mis":"K3-2-u5-X29"},{"t":"우산","mis":"K3-2-u5-X29"},{"t":"비가 왔다.","mis":"K3-2-u5-X17"}],"explanation":["쓰이는 문장 단서에서는 알아맞힐 낱말 자리를 비워요.","낱말을 그대로 쓰면 단서가 아니라 답이에요.","「비가 왔다.」에는 우산이 들어갈 자리가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#2','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C28',2,'mc','auto','나만의 국어사전에 넣을 낱말을 찾았더니 국어사전에 뜻이 여러 개 실려 있어요. 어떻게 쓰면 좋을까요?',ARRAY['K3-2-u5-X38','K3-2-u5-X30']::text[],false,'{"seq":2,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"나만의 국어사전에 넣을 낱말을 찾았더니 국어사전에 뜻이 여러 개 실려 있어요. 어떻게 쓰면 좋을까요?","options":[{"t":"내가 궁금했던 문장에 알맞은 뜻만 골라 쓴다","correct":true},{"t":"맨 앞에 나온 뜻을 그대로 옮긴다","mis":"K3-2-u5-X38"},{"t":"뜻을 모두 옮겨 쓴다","mis":"K3-2-u5-X38"},{"t":"뜻이 여러 개인 낱말은 빼 버린다","mis":"K3-2-u5-X30"}],"explanation":["낱말이 쓰인 문장을 떠올려요.","여러 뜻 가운데에서 그 문장에 맞는 뜻을 골라요.","찾고자 하는 뜻만 골라 기록해요."],"asset":{"type":"passage","lines":["① 생활 속에서 뜻이 궁금한 낱말 모으기","② 국어사전을 활용해 낱말의 종류와 뜻 쓰기","③ 낱말을 싣는 차례를 생각하며 낱말의 순서 정하기","④ 낱말 뜻에 어울리는 그림을 그려 사전 완성하기","[그림] 책 모양 · 종 모양 · 고리로 묶은 책 모양 · 병풍 모양"],"title":"나만의 국어사전 만들기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#3','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C14',3,'mc','auto','낱말 보물 찾기를 해요. 조건이 「ㅅ(시옷)이 들어가는 두 글자 낱말」일 때 알맞게 찾은 낱말은 무엇인가요?',ARRAY['K3-2-u5-X15']::text[],false,'{"seq":3,"concept":"K3-2-u5-C14","difficulty":3,"kind":"mc","stem":"낱말 보물 찾기를 해요. 조건이 「ㅅ(시옷)이 들어가는 두 글자 낱말」일 때 알맞게 찾은 낱말은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"나무","mis":"K3-2-u5-X15"},{"t":"소나무","mis":"K3-2-u5-X15"},{"t":"바다","mis":"K3-2-u5-X15"}],"explanation":["조건 두 가지를 모두 살펴요 — ㅅ이 들어가는가, 두 글자인가.","「나무」, 「바다」에는 ㅅ이 없고, 「소나무」는 세 글자예요.","「사과」는 ㅅ이 들어가는 두 글자 낱말이에요."],"asset":{"type":"passage","lines":["1. 도서관에서 원하는 책을 골라 봅시다.","2. 찾아야 하는 낱말의 조건을 확인해 봅시다.","   예: ㅅ(시옷)이 들어가는 두 글자 낱말 · 색깔을 나타내는 낱말","   예: 자신의 이름에 있는 글자가 들어가는 낱말 · 뜻을 잘 모르는 낱말","3. 조건에 맞는 낱말을 찾아 써 봅시다.","4. 친구들과 찾은 낱말을 비교해 봅시다."],"title":"낱말 보물 찾기 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#4','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C15',3,'error','auto','낱말 분류 릴레이에서 친구들이 한 일이에요. 놀이 방법대로 하지 않은 친구는 누구인가요?',ARRAY['K3-2-u5-X15','K3-2-u5-X14','K3-2-u5-X16']::text[],false,'{"seq":4,"concept":"K3-2-u5-C15","difficulty":3,"kind":"error","stem":"낱말 분류 릴레이에서 친구들이 한 일이에요. 놀이 방법대로 하지 않은 친구는 누구인가요?","options":[{"t":"규리: 새 기준을 말하지 않고 낱말을 아무 쪽에나 놓았다.","correct":true,"mis_target":"K3-2-u5-X15"},{"t":"태오: ‘선택 1’로 앞선 기준에 따라 「칠판」을 「침대」 쪽에 놓았다.","mis":"K3-2-u5-X14"},{"t":"라온: ‘선택 2’로 「형태가 바뀌는 낱말 / 바뀌지 않는 낱말」이라고 새 기준을 외치며 놓았다.","mis":"K3-2-u5-X16"}],"explanation":["‘선택 1’은 앞선 기준에 따라 분류하는 거예요.","‘선택 2’는 새 분류 기준을 외치며 분류하는 거예요.","기준 없이 아무 데나 놓으면 분류가 아니에요."],"asset":{"type":"passage","lines":["① 모둠 친구들이 각자 다섯 개의 낱말을 카드에 쓴다.","② 모둠 친구들이 쓴 낱말 카드를 모두 모아 섞는다.","③ 첫 번째 학생이 카드 두 개를 양쪽에 놓으며 분류 기준을 말한다.","④ 다음 학생은 둘 가운데 하나를 고른다.","   선택 1. 낱말 한 개를 골라 앞선 분류 기준에 따라 분류하기","   선택 2. 낱말 한 개를 골라 새 분류 기준을 외치며 분류하기","⑤ 모든 낱말 카드를 분류할 때까지 돌아가며 계속한다."],"title":"낱말 분류 릴레이 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#5','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C15',3,'mc','auto','낱말 분류 릴레이 놀이를 하는 목적으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X31','K3-2-u5-X14','K3-2-u5-X07']::text[],false,'{"seq":5,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"낱말 분류 릴레이 놀이를 하는 목적으로 알맞은 것은 무엇인가요?","options":[{"t":"낱말을 기준에 알맞게 분류해 보고, 기준이 다르면 결과도 다를 수 있음을 깨닫기","correct":true},{"t":"가장 빨리 낱말 카드를 다 놓은 사람이 이기기","mis":"K3-2-u5-X31"},{"t":"낱말마다 정해진 칸을 외우기","mis":"K3-2-u5-X14"},{"t":"어려운 낱말을 많이 쓰기","mis":"K3-2-u5-X07"}],"explanation":["하나씩 더해지는 낱말을 기준에 맞게 분류해요.","중간에 새 기준이 나오면 같은 낱말도 다르게 묶여요.","기준이 다르면 분류 결과도 다를 수 있어요."],"asset":{"type":"passage","lines":["① 모둠 친구들이 각자 다섯 개의 낱말을 카드에 쓴다.","② 모둠 친구들이 쓴 낱말 카드를 모두 모아 섞는다.","③ 첫 번째 학생이 카드 두 개를 양쪽에 놓으며 분류 기준을 말한다.","④ 다음 학생은 둘 가운데 하나를 고른다.","   선택 1. 낱말 한 개를 골라 앞선 분류 기준에 따라 분류하기","   선택 2. 낱말 한 개를 골라 새 분류 기준을 외치며 분류하기","⑤ 모든 낱말 카드를 분류할 때까지 돌아가며 계속한다."],"title":"낱말 분류 릴레이 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#6','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C31',3,'mc','auto','「쌀을 그릇에 안다미로 퍼 담았다.」에서 ‘안다미로’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X34']::text[],false,'{"seq":6,"concept":"K3-2-u5-C31","difficulty":3,"kind":"mc","stem":"「쌀을 그릇에 안다미로 퍼 담았다.」에서 ‘안다미로’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"담은 것이 그릇에 넘치도록 많이","correct":true},{"t":"언제나 한결같이 꼭 그렇게","mis":"K3-2-u5-X34"},{"t":"충분한 분량으로 만족스러운 모양","mis":"K3-2-u5-X34"},{"t":"조금씩 아껴서","mis":"K3-2-u5-X34"}],"explanation":["그릇에 쌀을 퍼 담는 장면이에요.","‘안다미로’는 담은 것이 그릇에 넘치도록 많이라는 뜻이에요.","‘또바기’는 언제나 한결같이, ‘이드거니’는 충분한 분량으로 만족스러운 모양이에요."],"asset":{"type":"passage","lines":["또바기 — 나와 또바기 함께 있어 주렴.","안다미로 — 쌀을 그릇에 안다미로 퍼 담았다.","이드거니 — 모처럼 이드거니 밥을 먹었다."],"title":"뜻을 알아 두면 좋은 우리말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#7','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C32',3,'mc','auto','‘ㅚ’가 들어간 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":7,"concept":"K3-2-u5-C32","difficulty":3,"kind":"mc","stem":"‘ㅚ’가 들어간 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"괴물, 열쇠, 회오리","correct":true},{"t":"과자, 영화, 완성","mis":"K3-2-u5-X35"},{"t":"돼지, 횃불, 왜가리","mis":"K3-2-u5-X35"},{"t":"괴물, 영화, 돼지","mis":"K3-2-u5-X35"}],"explanation":["‘ㅚ’는 ㅗ와 ㅣ가 붙은 모음자예요.","과자·영화·완성은 ‘ㅘ’, 돼지·횃불·왜가리는 ‘ㅙ’가 들어가요.","괴물·열쇠·회오리에 ‘ㅚ’가 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#8','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C27',4,'essay','teacher','세 가지 단서로 낱말 놀이에 낼 낱말을 하나 정해, 단서 카드 세 장(낱말의 종류 · 국어사전에서 찾은 뜻 · 낱말이 쓰이는 문장)을 만들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u5-C27","difficulty":4,"kind":"essay","stem":"세 가지 단서로 낱말 놀이에 낼 낱말을 하나 정해, 단서 카드 세 장(낱말의 종류 · 국어사전에서 찾은 뜻 · 낱말이 쓰이는 문장)을 만들어 쓰세요.","answer_guide":{"answer":"예: 낱말 — 사흘. 종류 — 이름을 나타내는 낱말. 뜻 — 세 날. 문장 — 할머니 댁에서 (     ) 동안 지냈다.","scoring_points":["낱말의 종류를 바르게 썼는가","국어사전에서 찾은 뜻을 썼는가","쓰이는 문장에서 낱말 자리를 비우고 단서에 낱말을 그대로 쓰지 않았는가"]},"explanation":["단서는 낱말을 가리키되 낱말을 그대로 드러내지 않아요.","뜻은 국어사전에서 찾아 써요.","서로 다른 낱말의 단서 카드가 섞이지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#9','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C28',4,'essay','teacher','생활 속에서 뜻이 궁금했던 낱말을 세 개 쓰고, 국어사전에 싣는 차례대로 늘어놓으세요. 그 가운데 하나를 골라 낱말의 종류와 뜻, 뜻에 어울리는 그림 계획을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C28","difficulty":4,"kind":"essay","stem":"생활 속에서 뜻이 궁금했던 낱말을 세 개 쓰고, 국어사전에 싣는 차례대로 늘어놓으세요. 그 가운데 하나를 골라 낱말의 종류와 뜻, 뜻에 어울리는 그림 계획을 쓰세요.","answer_guide":{"answer":"예: 낱말 — 얼, 보건, 사흘. 싣는 차례 — 보건 → 사흘 → 얼. 고른 낱말 — 보건(이름을 나타내는 낱말). 뜻 — 건강을 온전하게 잘 지킴. 그림 — 보건실에서 손을 깨끗이 씻는 모습을 그린다.","scoring_points":["뜻이 궁금했던 낱말 세 개를 썼는가","국어사전에 싣는 차례대로 바르게 늘어놓았는가","고른 낱말의 종류·뜻·그림 계획을 썼는가"]},"explanation":["생활 속에서 많이 쓰지만 뜻을 잘 몰랐던 낱말을 모아요.","첫 자음자 → 모음자 → 받침 차례로 순서를 정해요.","그림을 그리면 뜻을 오래 기억할 수 있어요."],"asset":{"type":"passage","lines":["① 생활 속에서 뜻이 궁금한 낱말 모으기","② 국어사전을 활용해 낱말의 종류와 뜻 쓰기","③ 낱말을 싣는 차례를 생각하며 낱말의 순서 정하기","④ 낱말 뜻에 어울리는 그림을 그려 사전 완성하기","[그림] 책 모양 · 종 모양 · 고리로 묶은 책 모양 · 병풍 모양"],"title":"나만의 국어사전 만들기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_L12_challenge#10','kor',3,2,'u5','L12','tb_g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C30',4,'mc','auto','‘ㄴ’ 소리가 더해지지 않는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":10,"concept":"K3-2-u5-C30","difficulty":4,"kind":"mc","stem":"‘ㄴ’ 소리가 더해지지 않는 낱말은 무엇인가요?","options":[{"t":"눈사람","correct":true},{"t":"눈요기","mis":"K3-2-u5-X32"},{"t":"솜이불","mis":"K3-2-u5-X32"},{"t":"담요","mis":"K3-2-u5-X32"}],"explanation":["받침 뒤에 ‘이, 야, 여, 요, 유’가 오는지 살펴요.","「눈요기」, 「솜이불」, 「담요」는 받침 뒤에 「요·이·요」가 와요.","「눈사람」은 받침 뒤에 「사」가 와서 ‘ㄴ’ 소리가 더해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#1','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C2',1,'mc','auto','『국어』 217쪽 안내문의 「당일 우천 시에는 체육관에서 진행합니다.」에서 ‘당일’의 뜻은 무엇인가요?',ARRAY['K3-2-u5-X25','K3-2-u5-X17']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 안내문의 「당일 우천 시에는 체육관에서 진행합니다.」에서 ‘당일’의 뜻은 무엇인가요?","options":[{"t":"일이 있는 바로 그날","correct":true},{"t":"일이 있는 다음 날","mis":"K3-2-u5-X25"},{"t":"비가 오는 날씨","mis":"K3-2-u5-X17"},{"t":"일이 있기 하루 전날","mis":"K3-2-u5-X25"}],"explanation":["‘당일’은 「일이 있는 바로 그날」이에요.","‘비가 오는 날씨’는 ‘우천’의 뜻이에요.","두 낱말의 뜻을 알면 체육 대회 날 비가 오면 체육관에서 한다는 것을 알 수 있어요."],"asset":{"type":"passage","lines":["[그림] 국어사전이 꽂힌 책꽂이 앞에서 안내문을 읽는 아이","체육 대회 안내","가을 체육 대회가 열립니다.","당일 우천 시에는 체육관에서 진행합니다.","○○초등학교","[말풍선] 당일? 우천? 무슨 뜻이지?"],"title":"생각 열기 — 『국어』 217쪽","hi":["당일","우천"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#2','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C3',1,'mc','auto','「시계, 강아지, 선생님」은 어떤 종류의 낱말인가요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":2,"concept":"K3-2-u5-C3","difficulty":1,"kind":"mc","stem":"「시계, 강아지, 선생님」은 어떤 종류의 낱말인가요?","options":[{"t":"이름을 나타내는 낱말","correct":true},{"t":"움직임을 나타내는 낱말","mis":"K3-2-u5-X04"},{"t":"성질이나 상태를 나타내는 낱말","mis":"K3-2-u5-X04"}],"explanation":["「이것은 시계이다.」처럼 ‘무엇’ 자리에 넣어 봐요.","셋 다 대상의 이름을 나타내요.","이름을 나타내는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#3','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C4',1,'mc','auto','「씻다, 읽다, 보다」는 어떤 종류의 낱말인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05']::text[],false,'{"seq":3,"concept":"K3-2-u5-C4","difficulty":1,"kind":"mc","stem":"「씻다, 읽다, 보다」는 어떤 종류의 낱말인가요?","options":[{"t":"움직임을 나타내는 낱말","correct":true},{"t":"이름을 나타내는 낱말","mis":"K3-2-u5-X04"},{"t":"성질이나 상태를 나타내는 낱말","mis":"K3-2-u5-X05"}],"explanation":["「손을 씻다」처럼 ‘어찌하다’ 자리에 넣어 봐요.","셋 다 무엇을 하는 움직임이에요.","움직임을 나타내는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#4','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C9',1,'mc','auto','「입어서, 입으니, 입으면」에서 형태가 바뀌지 않는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":4,"concept":"K3-2-u5-C9","difficulty":1,"kind":"mc","stem":"「입어서, 입으니, 입으면」에서 형태가 바뀌지 않는 부분은 무엇인가요?","options":[{"t":"입","correct":true},{"t":"입어","mis":"K3-2-u5-X08"},{"t":"입으","mis":"K3-2-u5-X08"},{"t":"어서","mis":"K3-2-u5-X08"}],"explanation":["세 낱말에 빠짐없이 든 부분을 찾아요.","「어서·으니·으면」이 바뀌는 부분이에요.","형태가 바뀌지 않는 부분은 「입」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#5','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C12',1,'sa','auto','『국어활동』 73쪽 글의 「맑으니」의 기본형을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u5-C12","difficulty":1,"kind":"sa","stem":"『국어활동』 73쪽 글의 「맑으니」의 기본형을 쓰세요.","answer":["맑다"],"explanation":["「맑으니」를 「맑」과 「으니」로 나눠요.","바뀌지 않는 부분 「맑」에 ‘-다’를 붙여요.","기본형은 「맑다」예요."],"asset":{"type":"passage","lines":["가을 하늘이 높고 맑으니 내 마음도 시원해요.","잠자리가 날아서 꽃에 앉으면 물방울이 떨어져요."],"title":"『국어활동』 73쪽 2번 글","hi":["높고","맑으니","시원해요","날아서","앉으면","떨어져요"]},"mis":"K3-2-u5-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#6','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C18',1,'ox','auto','국어사전에서 ㄲ으로 시작하는 낱말은 ㄱ으로 시작하는 낱말 바로 다음에 나와요.',ARRAY['K3-2-u5-X19']::text[],false,'{"seq":6,"concept":"K3-2-u5-C18","difficulty":1,"kind":"ox","stem":"국어사전에서 ㄲ으로 시작하는 낱말은 ㄱ으로 시작하는 낱말 바로 다음에 나와요.","answer":"O","reason_options":[{"t":"첫 자음자 차례는 ㄱ → ㄲ → ㄴ → ㄷ이에요.","correct":true},{"t":"쌍자음자(ㄲ·ㄸ·ㅃ·ㅆ·ㅉ)는 ㅎ 다음 맨 뒤에 나와요.","mis":"K3-2-u5-X19"}],"mis":"K3-2-u5-X19","explanation":["쌍자음자는 맨 뒤가 아니에요.","ㄱ 다음에 ㄲ, 그다음 ㄴ, ㄷ이 와요.","『국어』 붙임 11 차례표를 보며 익혀요."],"asset":{"type":"passage","lines":["첫 자음자: ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ","모음자: ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ","받침: 받침 없음 → ㄱ ㄲ ㄳ ㄴ ㄵ ㄶ ㄷ ㄹ … ㅇ ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"낱말을 싣는 차례표 — 『국어』 붙임 11"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#7','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C23',1,'mc','auto','『국어활동』 75쪽 「더 알아보기」예요. 국어사전에서 얻을 수 있는 정보가 아닌 것은 무엇인가요?',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":7,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"『국어활동』 75쪽 「더 알아보기」예요. 국어사전에서 얻을 수 있는 정보가 아닌 것은 무엇인가요?","options":[{"t":"낱말을 처음 만든 사람의 이름","correct":true},{"t":"낱말의 발음","mis":"K3-2-u5-X24"},{"t":"낱말을 사용하는 예","mis":"K3-2-u5-X24"},{"t":"낱말의 종류","mis":"K3-2-u5-X24"}],"explanation":["국어사전에는 낱말의 뜻만 있는 것이 아니에요.","뜻, 종류, 발음, 사용하는 예를 알 수 있어요.","낱말을 처음 만든 사람의 이름은 실려 있지 않아요."],"asset":{"type":"passage","lines":["국어사전에서 얻을 수 있는 정보","낱말의 뜻, 종류, 발음 외에도 낱말을 사용하는 예와 같은 정보를 얻을 수 있어요."],"title":"더 알아보기 — 『국어활동』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#8','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C30',1,'mc','auto','[솜니불]로 소리 나는 낱말을 공책에 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X33']::text[],false,'{"seq":8,"concept":"K3-2-u5-C30","difficulty":1,"kind":"mc","stem":"[솜니불]로 소리 나는 낱말을 공책에 바르게 쓴 것은 무엇인가요?","options":[{"t":"솜이불","correct":true},{"t":"솜니불","mis":"K3-2-u5-X33"},{"t":"소미불","mis":"K3-2-u5-X33"}],"explanation":["‘ㄴ’ 소리가 더해지는 것은 소리 낼 때예요.","쓸 때는 원래 글자대로 써요.","바르게 쓰면 「솜이불」이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#9','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C6',2,'match','auto','『국어』 251쪽 「스스로 확인하기」예요. 낱말과 낱말의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C6","difficulty":2,"kind":"match","stem":"『국어』 251쪽 「스스로 확인하기」예요. 낱말과 낱말의 종류를 알맞게 이으세요.","pairs":[{"l":"맛있다","r":"성질이나 상태를 나타내는 말"},{"l":"사과","r":"이름을 나타내는 말"},{"l":"먹었다","r":"움직임을 나타내는 말"}],"mis":"K3-2-u5-X04","explanation":["「사과가 맛있다」의 「맛있다」는 ‘어떠하다’ 자리예요.","「사과」는 ‘무엇’ 자리예요.","「사과를 먹었다」의 「먹었다」는 ‘어찌하다’ 자리예요."],"asset":{"type":"passage","lines":["맛있다 · 사과 · 먹었다","(     )을/를 나타내는 말 · (     )을/를 나타내는 말 · (     )을/를 나타내는 말"],"title":"스스로 확인하기 — 『국어』 251쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#10','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C14',2,'blank','auto','「여럿 가운데에서 같은 특징을 가진 것끼리 갈라놓는 것을 (     )(이)라고 해요.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":10,"concept":"K3-2-u5-C14","difficulty":2,"kind":"blank","stem":"「여럿 가운데에서 같은 특징을 가진 것끼리 갈라놓는 것을 (     )(이)라고 해요.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"분류","correct":true},{"t":"기본형","mis":"K3-2-u5-X14"},{"t":"차례","mis":"K3-2-u5-X14"},{"t":"짐작","mis":"K3-2-u5-X14"}],"explanation":["같은 특징끼리 갈라놓는 것을 분류라고 해요.","무엇을 같은 특징으로 볼지가 분류 기준이에요.","기준에 따라 낱말을 분류할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#11','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C33',2,'mc','auto','「낱말을 먹는 아이」에서 ‘분노’라는 낱말을 먹은 날 ‘나’는 어떠했나요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":11,"concept":"K3-2-u5-C33","difficulty":2,"kind":"mc","stem":"「낱말을 먹는 아이」에서 ‘분노’라는 낱말을 먹은 날 ‘나’는 어떠했나요?","options":[{"t":"내내 화가 나고 기분이 안 좋았다","correct":true},{"t":"모든 사람을 안아 주고 싶었다","mis":"K3-2-u5-X17"},{"t":"쉴 새 없이 웃었다","mis":"K3-2-u5-X17"}],"explanation":["‘분노’를 먹은 날을 찾아 다시 읽어요.","그날은 내내 화가 나고 기분이 안 좋았어요.","사람들을 다 밀쳐 버리고 싶었어요."],"asset":{"type":"passage","lines":["(간추림) 기쁨이라는 낱말을 먹은 날 — 무척 즐거웠고 쉴 새 없이 웃었다.","(간추림) 슬픔이라는 낱말을 먹은 날 — 너무 슬퍼서 울기만 했다.","하루는 사랑이라는 낱말을 먹었어. 그건 참 좋았어.","(간추림) 모든 사람을 안아 주고 싶었고, 말이 모두 하트 모양이 되었다.","(간추림) 분노를 먹은 날은 내내 화가 나고 기분이 안 좋았다.","(간추림) 두려움을 먹은 날은 하루 종일 무서웠다. 침대 밑에서 괴물까지 봤다."],"title":"「낱말을 먹는 아이」(마를레트 수니에르 글) 앞부분 — 『국어』 231~233쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#12','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C19',2,'mc','auto','『국어』 240쪽 그림 속 낱말이에요. 「치통」과 「층수」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X22']::text[],false,'{"seq":12,"concept":"K3-2-u5-C19","difficulty":2,"kind":"mc","stem":"『국어』 240쪽 그림 속 낱말이에요. 「치통」과 「층수」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?","options":[{"t":"층수","correct":true},{"t":"치통","mis":"K3-2-u5-X20"},{"t":"정할 수 없다","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자 ㅊ은 같아요.","모음자를 보면 「층」은 ㅡ, 「치」는 ㅣ예요.","ㅡ가 ㅣ보다 앞이니 「층수」가 먼저예요."],"asset":{"type":"passage","lines":["[그림] 국어사전을 펼친 쪽에 보이는 낱말","층간 · 층수 · 치통 · 치하 · 칙사 · 친가 · 친교"],"title":"『국어』 240쪽 그림 속 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#13','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C22',2,'mc','auto','『국어활동』 74쪽 1번 (1)이에요. 국어사전에서 낱말을 찾는 방법을 잘못 알고 있는 친구를 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u5-X13','K3-2-u5-X36']::text[],false,'{"seq":13,"concept":"K3-2-u5-C22","difficulty":2,"kind":"mc","stem":"『국어활동』 74쪽 1번 (1)이에요. 국어사전에서 낱말을 찾는 방법을 잘못 알고 있는 친구를 모두 고른 것은 무엇인가요?","options":[{"t":"선우, 민호","correct":true},{"t":"진영, 선우","mis":"K3-2-u5-X13"},{"t":"세희, 민호","mis":"K3-2-u5-X36"},{"t":"진영, 세희","mis":"K3-2-u5-X13"}],"explanation":["진영이와 세희는 바르게 알고 있어요.","선우는 「얼음」을 ㄹ에서 찾으려 했어요. 첫 자음자는 ㅇ이에요.","민호는 바뀐 모양이 모두 실렸다고 했어요. 사전에는 기본형만 실려요."],"asset":{"type":"speech","turns":[{"who":"진영","text":"국어사전에는 첫 번째 글자의 첫 자음자가 같은 낱말끼리 모여 있어."},{"who":"선우","text":"그럼 ‘얼음’을 찾을 때 ‘ㄹ’로 시작하는 낱말이 있는 곳을 찾아야겠네."},{"who":"세희","text":"“맛있는 사과를 먹었다.”라는 문장에서 ‘먹었다’의 뜻이 궁금하면 ‘먹다’라는 낱말을 찾아야 해."},{"who":"민호","text":"국어사전에는 ‘맛있는’, ‘맛있고’, ‘맛있어서’처럼 형태가 바뀐 낱말이 모두 실려 있을 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#14','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C24',2,'mc','auto','‘미지’를 ‘새로운’으로 바꾸어 읽어 본 친구가 쓴 짐작 방법은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":14,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"‘미지’를 ‘새로운’으로 바꾸어 읽어 본 친구가 쓴 짐작 방법은 무엇인가요?","options":[{"t":"다른 낱말로 바꾸어 문장의 뜻이 통하는지 보기","correct":true},{"t":"앞뒤 문장을 지우고 읽기","mis":"K3-2-u5-X25"},{"t":"소리가 비슷한 낱말 떠올리기","mis":"K3-2-u5-X25"}],"explanation":["「미지의 세계」를 「새로운 세계」로 바꾸어 읽었어요.","뜻이 통하면 짐작이 가까워요.","앞뒤 내용을 살피는 방법도 함께 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"뒤에 이어지는 문장을 보면 ‘세상의 잘 모르는 곳을 구석구석 다니는 사람들’이라는 내용이 나와. ‘미지’는 잘 모른다는 뜻이 아닐까?"},{"who":"친구 2","text":"‘미지’를 ‘새로운’으로 바꾸어도 문장의 뜻이 통하는 것을 보면 새롭다는 뜻일 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#15','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C34',2,'mc','auto','「아직도 미지의 세계는 남아 있다」에서 사람들이 땅속 세계에 관심을 가지게 된 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":15,"concept":"K3-2-u5-C34","difficulty":2,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」에서 사람들이 땅속 세계에 관심을 가지게 된 까닭은 무엇인가요?","options":[{"t":"지하자원이 우리 생활에서 중요해져서","correct":true},{"t":"바다 탐험이 모두 끝나서","mis":"K3-2-u5-X17"},{"t":"우주에 가고 싶어서","mis":"K3-2-u5-X17"}],"explanation":["땅속에 관심을 갖기 시작한 부분을 다시 읽어요.","지하자원이 우리 생활에서 중요해졌어요.","그래서 땅속 세계가 더욱 궁금해졌어요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#16','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C27',2,'mc','auto','친구가 『국어활동』 75쪽에서 찾은 낱말로 단서 카드 세 장을 만들었어요. 알아맞힐 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X17']::text[],false,'{"seq":16,"concept":"K3-2-u5-C27","difficulty":2,"kind":"mc","stem":"친구가 『국어활동』 75쪽에서 찾은 낱말로 단서 카드 세 장을 만들었어요. 알아맞힐 낱말은 무엇인가요?","options":[{"t":"시루","correct":true},{"t":"찌다","mis":"K3-2-u5-X04"},{"t":"떡","mis":"K3-2-u5-X17"},{"t":"너비","mis":"K3-2-u5-X17"}],"explanation":["종류 단서를 보면 이름을 나타내는 낱말이에요.","뜻 단서는 「떡이나 쌀 따위를 찌는 데 쓰는 둥근 질그릇.」이에요.","「할머니께서 (시루)에 떡을 찌셨다.」가 자연스러워요."],"asset":{"type":"passage","lines":["종류 — 이름을 나타내는 낱말","뜻 — 떡이나 쌀 따위를 찌는 데 쓰는 둥근 질그릇.","문장 — 할머니께서 (     )에 떡을 찌셨다."],"title":"친구가 만든 단서 카드 세 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#17','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C3',3,'mc','auto','「큰절하는 방법」에서 이름을 나타내는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X15']::text[],false,'{"seq":17,"concept":"K3-2-u5-C3","difficulty":3,"kind":"mc","stem":"「큰절하는 방법」에서 이름을 나타내는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"한복, 방바닥, 눈높이","correct":true},{"t":"올립니다, 숙입니다, 짚고","mis":"K3-2-u5-X04"},{"t":"다릅니다, 특별한","mis":"K3-2-u5-X04"},{"t":"한복, 올립니다, 다릅니다","mis":"K3-2-u5-X15"}],"explanation":["‘무엇’ 자리에 들어가는 낱말을 찾아요.","올립니다·숙입니다·짚고는 움직임이에요.","다릅니다·특별한은 성질이나 상태예요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#18','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C12',3,'mc','auto','「큰절하는 방법」의 밑줄 그은 낱말 「입고」의 뜻을 국어사전에서 찾으려고 해요. 찾을 낱말과 그 까닭을 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":18,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"「큰절하는 방법」의 밑줄 그은 낱말 「입고」의 뜻을 국어사전에서 찾으려고 해요. 찾을 낱말과 그 까닭을 바르게 쓴 것은 무엇인가요?","options":[{"t":"입다 — 「입」과 「고」로 나눈 뒤 바뀌지 않는 부분 「입」에 ‘-다’를 붙여서","correct":true},{"t":"입고다 — 「입고」에 ‘-다’를 붙여서","mis":"K3-2-u5-X11"},{"t":"입 — 바뀌지 않는 부분만 찾으면 되어서","mis":"K3-2-u5-X11"}],"explanation":["「입고」는 「입」과 「고」로 나눠요.","바뀌지 않는 부분 「입」에 ‘-다’를 붙이면 「입다」예요.","「입」만 찾으면 얼굴의 입처럼 다른 낱말이 나와요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#19','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C14',3,'mc','auto','『국어활동』 스스로 읽기 「사계절 우리말 사전」의 낱말은 어떤 기준으로 묶여 있나요?',ARRAY['K3-2-u5-X15','K3-2-u5-X14']::text[],false,'{"seq":19,"concept":"K3-2-u5-C14","difficulty":3,"kind":"mc","stem":"『국어활동』 스스로 읽기 「사계절 우리말 사전」의 낱말은 어떤 기준으로 묶여 있나요?","options":[{"t":"어느 계절과 관련한 낱말인가","correct":true},{"t":"낱말의 글자 수","mis":"K3-2-u5-X15"},{"t":"낱말의 종류","mis":"K3-2-u5-X14"}],"explanation":["봄, 여름, 가을, 겨울로 나누어 낱말을 소개해요.","‘꽃샘잎샘’은 봄, ‘한추위’는 겨울에 묶여 있어요.","같은 특징(계절)을 가진 것끼리 묶었어요."],"asset":{"type":"passage","lines":["[낱말] 봄 — 봄뜻 · 꽃샘잎샘 · 솜병아리 · 새털구름","[낱말] 여름 — 소나기밥 · 서늘맞이 · 여름심기 · 잠방잠방","[낱말] 가을 — 가을하다 · 달마중 · 땅거미 · 어우렁더우렁","[낱말] 겨울 — 눈구름 · 한추위 · 겨우살이 · 한올지다"],"title":"「사계절 우리말 사전」(신소영 글)에 나오는 낱말 — 『국어활동』 76~83쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#20','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C21',3,'mc','auto','「가방, 강조, 갈래, 가을」을 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X37','K3-2-u5-X21']::text[],false,'{"seq":20,"concept":"K3-2-u5-C21","difficulty":3,"kind":"mc","stem":"「가방, 강조, 갈래, 가을」을 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"가방 → 가을 → 갈래 → 강조","correct":true},{"t":"가을 → 가방 → 강조 → 갈래","mis":"K3-2-u5-X37"},{"t":"강조 → 갈래 → 가방 → 가을","mis":"K3-2-u5-X21"},{"t":"가방 → 가을 → 강조 → 갈래","mis":"K3-2-u5-X37"}],"explanation":["받침 없는 「가」로 시작하는 「가방」, 「가을」이 먼저예요. 두 번째 글자 ㅂ이 ㅇ보다 앞이에요.","그다음 받침 ㄹ인 「갈래」, 받침 ㅇ인 「강조」예요.","받침끼리도 자음자 차례로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#21','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C26',3,'mc','auto','「낱말을 먹는 아이」에서 낱말을 모두 먹은 ‘나’가 배가 부르고 행복했다고 했어요. 이 ‘배’를 국어사전에서 찾았더니 ‘배’라는 낱말이 여럿 실려 있어요. 이 문장에 알맞은 ‘배’는 무엇인가요?',ARRAY['K3-2-u5-X38']::text[],false,'{"seq":21,"concept":"K3-2-u5-C26","difficulty":3,"kind":"mc","stem":"「낱말을 먹는 아이」에서 낱말을 모두 먹은 ‘나’가 배가 부르고 행복했다고 했어요. 이 ‘배’를 국어사전에서 찾았더니 ‘배’라는 낱말이 여럿 실려 있어요. 이 문장에 알맞은 ‘배’는 무엇인가요?","options":[{"t":"밥을 먹으면 불러지는, 사람 몸의 배","correct":true},{"t":"물 위를 다니는 탈것인 배 — 사전에 맨 먼저 나와서","mis":"K3-2-u5-X38"},{"t":"과일인 배 — 어느 것을 골라도 상관없어서","mis":"K3-2-u5-X38"}],"explanation":["뜻이 여럿이면 하나씩 문장에 넣어 읽어 봐요.","「배가 부르고」에 어울리는 것은 사람 몸의 배예요.","글의 앞뒤에 맞는 뜻을 골라야 내용을 바르게 이해해요."],"asset":{"type":"passage","lines":["(간추림) 나는 입을 꼭 다물고 더 이상 아무 낱말도 먹지 않기로 결심했다.","(간추림) 웃지도 슬퍼하지도 못하고, 마음이 텅 빈 것 같았다.","그래서 나는 낱말을 모두 먹어 버리기로 했어.","(간추림) 배가 부르고 행복했다. 초콜릿을 양껏 먹은 것처럼.","(간추림) 어떤 날은 행복하면서도 두렵거나 슬프거나 화가 난다.","모든 낱말이 나를 도와주는 걸.","내 기분이 어떤지 내가 누구인지 잘 알 수 있도록."],"title":"「낱말을 먹는 아이」 뒷부분 — 『국어』 234~235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#22','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C30',3,'mc','auto','『국어』 252쪽이에요. ‘ㄴ’ 소리가 더해지는 경우가 많은 때는 언제인가요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":22,"concept":"K3-2-u5-C30","difficulty":3,"kind":"mc","stem":"『국어』 252쪽이에요. ‘ㄴ’ 소리가 더해지는 경우가 많은 때는 언제인가요?","options":[{"t":"받침 뒤에 ‘이, 야, 여, 요, 유’가 올 때","correct":true},{"t":"받침이 없는 글자 뒤에 ‘이’가 올 때","mis":"K3-2-u5-X32"},{"t":"글자에 ㅇ이 들어 있으면 언제나","mis":"K3-2-u5-X32"}],"explanation":["「솜이불[솜니불]」, 「맨입[맨닙]」을 떠올려요.","받침 뒤에 ‘이, 야, 여, 요, 유’가 오면 ‘ㄴ’ 소리가 더해지는 경우가 많아요.","「나이」, 「오이」처럼 받침이 없으면 더해지지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#23','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C12',4,'essay','teacher','「큰절하는 방법」의 밑줄 그은 낱말 「입고, 짚고, 포개어」 가운데에서 두 개를 골라 기본형과 국어사전에서 찾은 뜻을 쓰고, 그 낱말을 넣어 문장을 하나씩 만드세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u5-C12","difficulty":4,"kind":"essay","stem":"「큰절하는 방법」의 밑줄 그은 낱말 「입고, 짚고, 포개어」 가운데에서 두 개를 골라 기본형과 국어사전에서 찾은 뜻을 쓰고, 그 낱말을 넣어 문장을 하나씩 만드세요.","answer_guide":{"answer":"예: 짚고 — 기본형 짚다. 뜻 — 국어사전에서 찾은 뜻을 옮겨 쓴다(이 글에서는 손을 방바닥에 대고 몸을 받치는 모습). 문장: 할머니께서 지팡이를 짚고 산책을 하셨다. 포개어 — 기본형 포개다. 뜻 — 국어사전에서 찾은 뜻을 옮겨 쓴다(이 글에서는 오른손을 왼손 위에 겹쳐 놓는 모습). 문장: 다 읽은 책을 책상 위에 포개어 두었다.","scoring_points":["고른 낱말의 기본형을 바르게 썼는가","국어사전에서 찾은 뜻을 글의 흐름에 맞게 썼는가(사전마다 뜻풀이 말은 조금 다를 수 있음)","그 낱말을 알맞게 넣어 문장을 만들었는가"]},"explanation":["형태가 바뀌지 않는 부분에 ‘-다’를 붙여 기본형을 만들어요.","기본형으로 국어사전에서 뜻을 찾아요.","찾은 뜻에 맞게 문장을 만들면 낱말을 내 것으로 쓸 수 있어요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#24','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C26',4,'essay','teacher','더 알고 싶은 주제를 골라 책을 읽으려고 해요. 주제를 쓰고, 책을 읽다가 뜻을 모르는 낱말이 나오면 국어사전을 어떻게 활용할지 차례대로 쓰세요. 형태가 바뀐 낱말이 나올 때 할 일도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C26","difficulty":4,"kind":"essay","stem":"더 알고 싶은 주제를 골라 책을 읽으려고 해요. 주제를 쓰고, 책을 읽다가 뜻을 모르는 낱말이 나오면 국어사전을 어떻게 활용할지 차례대로 쓰세요. 형태가 바뀐 낱말이 나올 때 할 일도 쓰세요.","answer_guide":{"answer":"예: 주제 — 내가 키우고 싶은 동물. 활용 — 뜻을 모르는 낱말에 표시하고 앞뒤 내용으로 뜻을 짐작하며 끝까지 읽는다. 다 읽은 뒤 국어사전에서 찾아 짐작한 뜻과 비교하고, 찾은 뜻을 공책에 쓴다. 형태가 바뀐 낱말 — 「돌보면」처럼 바뀐 낱말은 기본형 「돌보다」로 바꾸어 찾는다.","scoring_points":["더 알고 싶은 주제를 골랐는가","표시하기 → 짐작하기 → 사전에서 찾기 → 비교하기 차례를 썼는가","형태가 바뀐 낱말은 기본형으로 찾는다고 썼는가"]},"explanation":["책을 읽을 때 국어사전을 알맞게 활용해요.","먼저 짐작하며 읽고 뒤에 사전으로 확인해요.","형태가 바뀐 낱말은 기본형으로 바꾸어 찾아요."],"asset":{"type":"passage","lines":["내가 키우고 싶은 동물 / 내가 키우고 싶은 식물 / 우리나라의 역사","내가 되고 싶은 직업 / 우주 / (그 밖에 원하는 주제)"],"title":"국어사전을 활용해 책 읽기 — 더 알고 싶은 주제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_a#25','kor',3,2,'u5','','tb_g3_2_kor_u5_review_a','unit_review','K3-2-u5-C22',4,'mc','auto','「내가 키우고 싶은 동물」 책을 읽다가 「강아지를 키우고 싶다면」의 「키우고」 뜻이 궁금해졌어요. 국어사전에서 어떤 낱말을 찾아야 하나요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":25,"concept":"K3-2-u5-C22","difficulty":4,"kind":"mc","stem":"「내가 키우고 싶은 동물」 책을 읽다가 「강아지를 키우고 싶다면」의 「키우고」 뜻이 궁금해졌어요. 국어사전에서 어떤 낱말을 찾아야 하나요?","options":[{"t":"키우다","correct":true},{"t":"키우고","mis":"K3-2-u5-X23"},{"t":"키","mis":"K3-2-u5-X11"},{"t":"키우으다","mis":"K3-2-u5-X11"}],"explanation":["「키우고」는 형태가 바뀐 낱말이에요.","바뀌지 않는 부분 「키우」에 ‘-다’를 붙여요.","「키」만 찾으면 다른 낱말이 나와요."],"asset":{"type":"passage","lines":["내가 키우고 싶은 동물 / 내가 키우고 싶은 식물 / 우리나라의 역사","내가 되고 싶은 직업 / 우주 / (그 밖에 원하는 주제)"],"title":"국어사전을 활용해 책 읽기 — 더 알고 싶은 주제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#1','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C23',1,'mc','auto','『국어』 217쪽 안내문의 ‘우천’은 무슨 뜻인가요?',ARRAY['K3-2-u5-X17','K3-2-u5-X25']::text[],false,'{"seq":1,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 안내문의 ‘우천’은 무슨 뜻인가요?","options":[{"t":"비가 오는 날씨","correct":true},{"t":"일이 있는 바로 그날","mis":"K3-2-u5-X17"},{"t":"맑은 날씨","mis":"K3-2-u5-X25"},{"t":"눈이 오는 날씨","mis":"K3-2-u5-X25"}],"explanation":["‘우천’은 「비가 오는 날씨」예요.","「우천 시에는 체육관에서」는 비가 오면 체육관에서 한다는 말이에요.","뜻을 알면 안내문의 내용을 바르게 알 수 있어요."],"asset":{"type":"passage","lines":["[그림] 국어사전이 꽂힌 책꽂이 앞에서 안내문을 읽는 아이","체육 대회 안내","가을 체육 대회가 열립니다.","당일 우천 시에는 체육관에서 진행합니다.","○○초등학교","[말풍선] 당일? 우천? 무슨 뜻이지?"],"title":"생각 열기 — 『국어』 217쪽","hi":["당일","우천"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#2','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C3',1,'mc','auto','『국어』 219쪽 3번이에요. 낱말 알아맞히기 놀이에서 「전구」를 뽑았다면 어떻게 설명하면 좋을까요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":2,"concept":"K3-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 219쪽 3번이에요. 낱말 알아맞히기 놀이에서 「전구」를 뽑았다면 어떻게 설명하면 좋을까요?","options":[{"t":"“불을 밝히는 데 쓰는, 유리로 된 둥근 물건이야.”","correct":true},{"t":"“단추를 눌러 불이 들어오게 하는 거야.”","mis":"K3-2-u5-X04"},{"t":"“빛이 환해서 잘 보이는 거야.”","mis":"K3-2-u5-X04"}],"explanation":["「전구」는 물건의 이름을 나타내는 낱말이에요.","둘째 설명은 「켜다」, 셋째 설명은 「밝다」에 어울려요.","이름은 그것이 무엇인지 생김새나 쓰임으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#3','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C5',1,'mc','auto','「아름답다, 높다, 검다」는 어떤 종류의 낱말인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":3,"concept":"K3-2-u5-C5","difficulty":1,"kind":"mc","stem":"「아름답다, 높다, 검다」는 어떤 종류의 낱말인가요?","options":[{"t":"성질이나 상태를 나타내는 낱말","correct":true},{"t":"움직임을 나타내는 낱말","mis":"K3-2-u5-X05"},{"t":"이름을 나타내는 낱말","mis":"K3-2-u5-X04"}],"explanation":["「꽃이 아름답다」처럼 ‘어떠하다’ 자리에 넣어 봐요.","셋 다 대상이 어떠한지를 나타내요.","성질이나 상태를 나타내는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#4','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C9',1,'mc','auto','『국어』 229쪽 표예요. 「낮고, 낮아서, 낮으니, 낮으면」에서 형태가 바뀌지 않는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":4,"concept":"K3-2-u5-C9","difficulty":1,"kind":"mc","stem":"『국어』 229쪽 표예요. 「낮고, 낮아서, 낮으니, 낮으면」에서 형태가 바뀌지 않는 부분은 무엇인가요?","options":[{"t":"낮","correct":true},{"t":"낮으","mis":"K3-2-u5-X08"},{"t":"낮아","mis":"K3-2-u5-X08"},{"t":"고","mis":"K3-2-u5-X08"}],"explanation":["네 낱말에 모두 든 부분을 찾아요.","「고·아서·으니·으면」이 바뀌는 부분이에요.","형태가 바뀌지 않는 부분은 「낮」이에요."],"asset":{"type":"passage","lines":["낮고 · 낮아서 · 낮으니 · 낮으면 → 낮 → 낮다","잡고 · 잡아서 · 잡으니 · 잡으면 → (   ) → (   )","매고 · 매서 · 매니 · 매면 → (   ) → (   )","짧고 · 짧아서 · 짧으니 · 짧으면 → (   ) → (   )"],"title":"낱말의 기본형 만들기 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#5','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C12',1,'mc','auto','『국어활동』 73쪽 글의 「앉으면」의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":5,"concept":"K3-2-u5-C12","difficulty":1,"kind":"mc","stem":"『국어활동』 73쪽 글의 「앉으면」의 기본형은 무엇인가요?","options":[{"t":"앉다","correct":true},{"t":"앉으다","mis":"K3-2-u5-X11"},{"t":"앉으면다","mis":"K3-2-u5-X11"},{"t":"앉아다","mis":"K3-2-u5-X11"}],"explanation":["「앉으면」을 「앉」과 「으면」으로 나눠요.","바뀌지 않는 부분 「앉」에 ‘-다’를 붙여요.","기본형은 「앉다」예요."],"asset":{"type":"passage","lines":["가을 하늘이 높고 맑으니 내 마음도 시원해요.","잠자리가 날아서 꽃에 앉으면 물방울이 떨어져요."],"title":"『국어활동』 73쪽 2번 글","hi":["높고","맑으니","시원해요","날아서","앉으면","떨어져요"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#6','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C18',1,'mc','auto','『국어활동』 75쪽 ㉮예요. 「너비」와 「시루」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C18","difficulty":1,"kind":"mc","stem":"『국어활동』 75쪽 ㉮예요. 「너비」와 「시루」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?","options":[{"t":"너비","correct":true},{"t":"시루","mis":"K3-2-u5-X19"},{"t":"글자 수가 같아서 정할 수 없다","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자를 살펴봐요.","「너비」는 ㄴ, 「시루」는 ㅅ으로 시작해요.","ㄴ이 ㅅ보다 앞이니 「너비」가 먼저예요."],"asset":{"type":"passage","lines":["㉮ 너비 · 시루","㉯ 고요 · 겨레 · 구기","㉰ 한과 · 학문 · 하교 · 한파"],"title":"『국어활동』 75쪽 2번 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#7','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C23',1,'ox','auto','『국어활동』 75쪽 「더 알아보기」를 읽었어요. 국어사전에서 낱말을 찾으면 그 낱말의 뜻 한 가지만 알 수 있어요.',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":7,"concept":"K3-2-u5-C23","difficulty":1,"kind":"ox","stem":"『국어활동』 75쪽 「더 알아보기」를 읽었어요. 국어사전에서 낱말을 찾으면 그 낱말의 뜻 한 가지만 알 수 있어요.","answer":"X","reason_options":[{"t":"뜻과 함께 낱말의 종류, 발음, 낱말을 사용하는 예도 실려 있어요.","correct":true},{"t":"국어사전은 뜻을 알려 주는 책이니 뜻만 적혀 있어요.","mis":"K3-2-u5-X24"}],"mis":"K3-2-u5-X24","explanation":["국어사전에서 낱말을 찾으면 여러 정보가 함께 나와요.","발음이나 쓰이는 예를 보면 낱말을 바르게 쓸 수 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["국어사전에서 얻을 수 있는 정보","낱말의 뜻, 종류, 발음 외에도 낱말을 사용하는 예와 같은 정보를 얻을 수 있어요."],"title":"더 알아보기 — 『국어활동』 75쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#8','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C32',1,'mc','auto','『국어』 253쪽 「괴물」의 ‘ㅚ’는 어떤 두 모음자가 붙은 것인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":8,"concept":"K3-2-u5-C32","difficulty":1,"kind":"mc","stem":"『국어』 253쪽 「괴물」의 ‘ㅚ’는 어떤 두 모음자가 붙은 것인가요?","options":[{"t":"ㅗ와 ㅣ","correct":true},{"t":"ㅗ와 ㅐ","mis":"K3-2-u5-X35"},{"t":"ㅗ와 ㅏ","mis":"K3-2-u5-X35"}],"explanation":["‘ㅘ’는 ㅗ와 ㅏ, ‘ㅙ’는 ㅗ와 ㅐ예요.","‘ㅚ’는 ㅗ와 ㅣ가 붙은 거예요.","두 모음자가 붙는 자리를 살피며 써요."],"asset":{"type":"passage","lines":["과자 · 영화 · 완성 · 돼지","횃불 · 괴물 · 횡단보도"],"title":"글씨를 바르게 써 봅시다 — 『국어』 253쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#9','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C4',2,'mc','auto','『국어활동』 72쪽이에요. 그림 속 문장에서 움직임을 나타내는 낱말(□ 표)끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":9,"concept":"K3-2-u5-C4","difficulty":2,"kind":"mc","stem":"『국어활동』 72쪽이에요. 그림 속 문장에서 움직임을 나타내는 낱말(□ 표)끼리 묶은 것은 무엇인가요?","options":[{"t":"신다, 쓰다, 매다, 끼다","correct":true},{"t":"크다, 길다, 짧다","mis":"K3-2-u5-X05"},{"t":"양말, 모자, 장갑","mis":"K3-2-u5-X04"},{"t":"신다, 길다, 끼다","mis":"K3-2-u5-X05"}],"explanation":["「양말을 신다」처럼 ‘어찌하다’ 자리에 들어가는 낱말을 찾아요.","크다·길다·짧다는 성질이나 상태예요.","양말·모자·장갑은 이름이에요."],"asset":{"type":"passage","lines":["외출 준비 시작!","양말을 신다. · 모자를 쓰다. · 단추가 크다.","목도리를 두르다. · 목도리가 길다. · 안경을 쓰다.","신발을 신다. · 신발 끈을 매다. · 신발 끈이 짧다.","장갑을 끼다. · 장갑이 따뜻하다. · 외출 준비 끝!","○ 이름 · □ 움직임 · △ 성질이나 상태"],"title":"그림 속 문장 — 『국어활동』 72쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#10','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C15',2,'mc','auto','「웃다, 침대, 슬프다」를 「형태가 바뀌는 부분이 있는가」로 나누면 혼자 다른 칸에 들어가는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":10,"concept":"K3-2-u5-C15","difficulty":2,"kind":"mc","stem":"「웃다, 침대, 슬프다」를 「형태가 바뀌는 부분이 있는가」로 나누면 혼자 다른 칸에 들어가는 낱말은 무엇인가요?","options":[{"t":"침대","correct":true},{"t":"웃다","mis":"K3-2-u5-X09"},{"t":"슬프다","mis":"K3-2-u5-X09"}],"explanation":["「웃다」, 「슬프다」는 「웃고, 슬프고」처럼 형태가 바뀌어요.","「침대」는 형태가 바뀌는 부분이 없어요.","그래서 「침대」만 다른 칸에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#11','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C33',2,'mc','auto','「낱말을 먹는 아이」에서 ‘기쁨’이라는 낱말을 먹은 날 ‘나’는 어떠했나요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":11,"concept":"K3-2-u5-C33","difficulty":2,"kind":"mc","stem":"「낱말을 먹는 아이」에서 ‘기쁨’이라는 낱말을 먹은 날 ‘나’는 어떠했나요?","options":[{"t":"무척 즐거워서 쉴 새 없이 웃었다","correct":true},{"t":"너무 슬퍼서 울기만 했다","mis":"K3-2-u5-X17"},{"t":"하루 종일 무서웠다","mis":"K3-2-u5-X17"}],"explanation":["‘기쁨’을 먹은 날을 찾아요.","무척 즐거웠고 온종일 행복해서 쉴 새 없이 웃었어요.","울기만 한 날은 ‘슬픔’을 먹은 날이에요."],"asset":{"type":"passage","lines":["(간추림) 기쁨이라는 낱말을 먹은 날 — 무척 즐거웠고 쉴 새 없이 웃었다.","(간추림) 슬픔이라는 낱말을 먹은 날 — 너무 슬퍼서 울기만 했다.","하루는 사랑이라는 낱말을 먹었어. 그건 참 좋았어.","(간추림) 모든 사람을 안아 주고 싶었고, 말이 모두 하트 모양이 되었다.","(간추림) 분노를 먹은 날은 내내 화가 나고 기분이 안 좋았다.","(간추림) 두려움을 먹은 날은 하루 종일 무서웠다. 침대 밑에서 괴물까지 봤다."],"title":"「낱말을 먹는 아이」(마를레트 수니에르 글) 앞부분 — 『국어』 231~233쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#12','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C20',2,'mc','auto','『국어』 240쪽 그림 속 낱말이에요. 「치하」와 「칙사」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X22']::text[],false,'{"seq":12,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"『국어』 240쪽 그림 속 낱말이에요. 「치하」와 「칙사」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?","options":[{"t":"치하","correct":true},{"t":"칙사","mis":"K3-2-u5-X21"},{"t":"정할 수 없다","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자 ㅊ, 모음자 ㅣ가 같아요.","「치」는 받침이 없고 「칙」은 받침 ㄱ이 있어요.","받침이 없는 글자가 먼저이니 「치하」가 먼저예요."],"asset":{"type":"passage","lines":["[그림] 국어사전을 펼친 쪽에 보이는 낱말","층간 · 층수 · 치통 · 치하 · 칙사 · 친가 · 친교"],"title":"『국어』 240쪽 그림 속 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#13','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C22',2,'sa','auto','「공을 잡아서 던졌다.」의 「잡아서」 뜻을 국어사전에서 찾으려면 어떤 낱말을 찾아야 하나요? 그 낱말을 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"K3-2-u5-C22","difficulty":2,"kind":"sa","stem":"「공을 잡아서 던졌다.」의 「잡아서」 뜻을 국어사전에서 찾으려면 어떤 낱말을 찾아야 하나요? 그 낱말을 쓰세요.","answer":["잡다"],"explanation":["「잡아서」는 형태가 바뀐 낱말이에요.","바뀌지 않는 부분 「잡」에 ‘-다’를 붙여요.","기본형 「잡다」를 찾아요."],"mis":"K3-2-u5-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#14','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C24',2,'mc','auto','「육지 표면이 아니라 땅속에 대해」에서 ‘표면’의 뜻을 짐작할 수 있는 실마리는 무엇인가요?',ARRAY['K3-2-u5-X25','K3-2-u5-X17']::text[],false,'{"seq":14,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"「육지 표면이 아니라 땅속에 대해」에서 ‘표면’의 뜻을 짐작할 수 있는 실마리는 무엇인가요?","options":[{"t":"‘땅속’과 맞서 쓰였으니 땅의 겉 부분이라는 것","correct":true},{"t":"‘표’라는 글자가 들어 있으니 표를 붙인 곳이라는 것","mis":"K3-2-u5-X25"},{"t":"‘육지’라는 말이 앞에 있으니 바다라는 것","mis":"K3-2-u5-X17"}],"explanation":["「○○이 아니라 땅속」이라고 했어요.","땅속과 맞서는 곳은 땅의 겉 부분이에요.","앞뒤 내용에 낱말의 뜻을 짐작할 실마리가 있어요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#15','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C34',2,'mc','auto','「아직도 미지의 세계는 남아 있다」에서 새로운 장소를 찾아 나서는 인간의 역사를 무엇의 역사라고 했나요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":15,"concept":"K3-2-u5-C34","difficulty":2,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」에서 새로운 장소를 찾아 나서는 인간의 역사를 무엇의 역사라고 했나요?","options":[{"t":"미개척지에 대한 탐험과 도전의 역사","correct":true},{"t":"지도를 사고판 역사","mis":"K3-2-u5-X17"},{"t":"집을 짓는 역사","mis":"K3-2-u5-X17"}],"explanation":["달과 다른 행성을 관찰한 이야기 다음 문장이에요.","인간은 끊임없이 새로운 장소를 찾아 나섰어요.","그 역사를 미개척지에 대한 탐험과 도전의 역사라고 했어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#16','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C28',2,'mc','auto','나만의 국어사전에서 낱말의 순서를 정할 때 따르는 것은 무엇인가요?',ARRAY['K3-2-u5-X30']::text[],false,'{"seq":16,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"나만의 국어사전에서 낱말의 순서를 정할 때 따르는 것은 무엇인가요?","options":[{"t":"국어사전에 낱말을 싣는 차례","correct":true},{"t":"낱말을 모은 날짜 차례","mis":"K3-2-u5-X30"},{"t":"내가 좋아하는 낱말 차례","mis":"K3-2-u5-X30"}],"explanation":["나만의 국어사전도 국어사전처럼 만들어요.","첫 자음자 → 모음자 → 받침 차례로 순서를 정해요.","그래야 나중에 찾기 쉬워요."],"asset":{"type":"passage","lines":["① 생활 속에서 뜻이 궁금한 낱말 모으기","② 국어사전을 활용해 낱말의 종류와 뜻 쓰기","③ 낱말을 싣는 차례를 생각하며 낱말의 순서 정하기","④ 낱말 뜻에 어울리는 그림을 그려 사전 완성하기","[그림] 책 모양 · 종 모양 · 고리로 묶은 책 모양 · 병풍 모양"],"title":"나만의 국어사전 만들기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#17','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C4',3,'mc','auto','「큰절하는 방법」에서 움직임을 나타내는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04','K3-2-u5-X15']::text[],false,'{"seq":17,"concept":"K3-2-u5-C4","difficulty":3,"kind":"mc","stem":"「큰절하는 방법」에서 움직임을 나타내는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"올립니다, 숙입니다, 굽히며","correct":true},{"t":"다릅니다, 특별한","mis":"K3-2-u5-X05"},{"t":"한복, 방바닥, 눈높이","mis":"K3-2-u5-X04"},{"t":"올립니다, 다릅니다, 한복","mis":"K3-2-u5-X15"}],"explanation":["‘어찌하다’ 자리에 들어가는 낱말을 찾아요.","손을 올리고, 머리를 숙이고, 몸을 굽히는 움직임이에요.","다릅니다는 성질이나 상태를 나타내요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#18','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C12',3,'mc','auto','「큰절하는 방법」의 밑줄 그은 낱말 「짚고」의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11','K3-2-u5-X25']::text[],false,'{"seq":18,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"「큰절하는 방법」의 밑줄 그은 낱말 「짚고」의 기본형은 무엇인가요?","options":[{"t":"짚다","correct":true},{"t":"짚고다","mis":"K3-2-u5-X11"},{"t":"짚으다","mis":"K3-2-u5-X11"},{"t":"집다","mis":"K3-2-u5-X25"}],"explanation":["「짚고」는 「짚」과 「고」로 나눠요.","바뀌지 않는 부분 「짚」에 ‘-다’를 붙여요.","「집다」는 소리가 비슷한 다른 낱말이에요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#19','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C15',3,'mc','auto','보기의 아홉 낱말을 기준 ①(낱말의 종류)과 기준 ②(형태가 바뀌는 부분이 있는가)로 나누었어요. 나누어진 칸의 수로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X16']::text[],false,'{"seq":19,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"보기의 아홉 낱말을 기준 ①(낱말의 종류)과 기준 ②(형태가 바뀌는 부분이 있는가)로 나누었어요. 나누어진 칸의 수로 알맞은 것은 무엇인가요?","options":[{"t":"기준 ①은 세 칸, 기준 ②는 두 칸","correct":true},{"t":"두 기준 모두 세 칸","mis":"K3-2-u5-X16"},{"t":"기준 ①은 두 칸, 기준 ②는 세 칸","mis":"K3-2-u5-X16"}],"explanation":["기준 ①은 이름 / 움직임 / 성질이나 상태의 세 칸이에요.","기준 ②는 바뀌는 부분이 있는 낱말 / 없는 낱말의 두 칸이에요.","기준이 바뀌면 칸의 수도 달라져요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류 — 이름 / 움직임 / 성질이나 상태","기준 ② 형태가 바뀌는 부분이 있는가 — 있는 낱말 / 없는 낱말","여럿 가운데에서 같은 특징을 가진 것끼리 갈라놓는 것을 분류라고 해요."],"title":"분류 기준 두 가지 — 『국어』 236~237쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#20','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C20',3,'mc','auto','「자라, 장구, 사자, 소리」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X21','K3-2-u5-X20']::text[],false,'{"seq":20,"concept":"K3-2-u5-C20","difficulty":3,"kind":"mc","stem":"「자라, 장구, 사자, 소리」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"사자 → 소리 → 자라 → 장구","correct":true},{"t":"자라 → 장구 → 사자 → 소리","mis":"K3-2-u5-X19"},{"t":"사자 → 소리 → 장구 → 자라","mis":"K3-2-u5-X21"},{"t":"소리 → 사자 → 자라 → 장구","mis":"K3-2-u5-X20"}],"explanation":["첫 자음자 ㅅ이 ㅈ보다 앞이에요.","「사자」와 「소리」는 모음자 ㅏ가 ㅗ보다 앞이에요.","「자라」와 「장구」는 받침 없는 「자」가 먼저예요."],"asset":{"type":"passage","lines":["나라, 가을","사자, 소리","자라, 장구","강조, 갈래","발사, 발레"],"title":"짝 지은 두 낱말 — 국어사전에 먼저 싣는 낱말은?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#21','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C25',3,'mc','auto','‘미지’를 「잘 모르거나 새로움」으로 짐작하고 국어사전에서 「아직 알지 못함」을 찾았어요. 다음에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X26']::text[],false,'{"seq":21,"concept":"K3-2-u5-C25","difficulty":3,"kind":"mc","stem":"‘미지’를 「잘 모르거나 새로움」으로 짐작하고 국어사전에서 「아직 알지 못함」을 찾았어요. 다음에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"사전의 뜻을 넣어 「아직 알지 못하는 세계」로 그 문장을 다시 읽는다","correct":true},{"t":"사전이 틀렸으니 내 짐작대로 읽는다","mis":"K3-2-u5-X26"},{"t":"짐작이 빗나갔으니 그 글은 읽지 않는다","mis":"K3-2-u5-X26"}],"explanation":["짐작과 사전의 뜻을 견주어 봐요.","사전의 뜻으로 알고 문장을 다시 읽어요.","그러면 글의 내용을 더 정확하게 이해할 수 있어요."],"asset":{"type":"passage","lines":["낱말 — 짐작한 뜻 — 국어사전에서 찾은 뜻","미지 — 잘 모르거나 새로움. — 아직 알지 못함.","표면 — 겉 부분. — 사물의 가장 바깥쪽."],"title":"낱말의 뜻 찾아보기 (예시) — 『국어』 246쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#22','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C32',3,'error','auto','글자의 모음자를 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":22,"concept":"K3-2-u5-C32","difficulty":3,"kind":"error","stem":"글자의 모음자를 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희: 「돼지」의 ‘ㅙ’는 ㅗ와 ㅏ가 합쳐진 거야.","correct":true,"mis_target":"K3-2-u5-X35"},{"t":"은호: 「영화」의 ‘ㅘ’는 ㅗ와 ㅏ가 합쳐진 거야.","mis":"K3-2-u5-X35"},{"t":"도윤: 「괴물」의 ‘ㅚ’는 ㅗ와 ㅣ가 합쳐진 거야.","mis":"K3-2-u5-X35"}],"explanation":["‘ㅘ’는 ㅗ와 ㅏ, ‘ㅚ’는 ㅗ와 ㅣ예요.","‘ㅙ’는 ㅗ와 ㅐ가 합쳐진 거예요.","그래서 라희가 잘못 말했어요."],"asset":{"type":"passage","lines":["과자 · 영화 · 완성 · 돼지","횃불 · 괴물 · 횡단보도"],"title":"글씨를 바르게 써 봅시다 — 『국어』 253쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#23','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C6',4,'essay','teacher','「큰절하는 방법」에서 이름, 움직임, 성질이나 상태를 나타내는 낱말을 하나씩 찾아 쓰고, 각각 어떤 문장 틀에 넣어 확인했는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u5-C6","difficulty":4,"kind":"essay","stem":"「큰절하는 방법」에서 이름, 움직임, 성질이나 상태를 나타내는 낱말을 하나씩 찾아 쓰고, 각각 어떤 문장 틀에 넣어 확인했는지 쓰세요.","answer_guide":{"answer":"예: 이름 — 한복. 「이것은 한복이다.」처럼 ‘무엇이 무엇이다’ 틀의 ‘무엇’ 자리에 들어간다. 움직임 — 올립니다(올리다). 「손을 올리다.」처럼 ‘무엇이 어찌하다’ 틀의 ‘어찌하다’ 자리에 들어간다. 성질이나 상태 — 다릅니다(다르다). 「방법이 다르다.」처럼 ‘무엇이 어떠하다’ 틀의 ‘어떠하다’ 자리에 들어간다.","scoring_points":["이름을 나타내는 낱말을 바르게 찾았는가","움직임과 성질이나 상태를 나타내는 낱말을 바르게 찾았는가","각 낱말을 알맞은 문장 틀에 넣어 확인했는가"]},"explanation":["글에서 낱말을 찾아 종류를 가려요.","문장 틀에 넣어 읽어 보면 종류를 확인할 수 있어요.","끝 모양만 보고 정하지 않아요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#24','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C28',4,'essay','teacher','나만의 국어사전을 어떤 모양(책 모양, 종 모양, 고리로 묶은 책 모양, 병풍 모양 가운데 하나)으로 만들지 정하고, 넣을 낱말 두 개와 각 낱말에 쓸 내용(종류·뜻·그림)을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C28","difficulty":4,"kind":"essay","stem":"나만의 국어사전을 어떤 모양(책 모양, 종 모양, 고리로 묶은 책 모양, 병풍 모양 가운데 하나)으로 만들지 정하고, 넣을 낱말 두 개와 각 낱말에 쓸 내용(종류·뜻·그림)을 쓰세요.","answer_guide":{"answer":"예: 모양 — 병풍 모양. 낱말 1 — 갈무리: 이름을 나타내는 낱말, 물건 따위를 잘 정리함, 옷장에 옷을 계절별로 정리하는 그림. 낱말 2 — 마무리: 이름을 나타내는 낱말, 일의 끝맺음, 만들기를 다 끝내고 정리하는 그림. 차례 — 갈무리를 앞에, 마무리를 뒤에 싣는다.","scoring_points":["국어사전의 모양을 정했는가","넣을 낱말 두 개의 종류와 뜻을 썼는가","뜻에 어울리는 그림 계획과 싣는 차례를 썼는가"]},"explanation":["생활 속에서 뜻이 궁금했던 낱말을 모아요.","종류와 뜻은 국어사전에서 찾아 써요.","싣는 차례를 지키고, 뜻에 어울리는 그림을 그려요."],"asset":{"type":"passage","lines":["① 생활 속에서 뜻이 궁금한 낱말 모으기","② 국어사전을 활용해 낱말의 종류와 뜻 쓰기","③ 낱말을 싣는 차례를 생각하며 낱말의 순서 정하기","④ 낱말 뜻에 어울리는 그림을 그려 사전 완성하기","[그림] 책 모양 · 종 모양 · 고리로 묶은 책 모양 · 병풍 모양"],"title":"나만의 국어사전 만들기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_b#25','kor',3,2,'u5','','tb_g3_2_kor_u5_review_b','unit_review','K3-2-u5-C15',4,'mc','auto','「공, 던지다, 빠르다, 운동장」을 어떤 기준으로 나누었더니 「공 / 던지다, 빠르다, 운동장」이 되었어요. 나눈 기준은 무엇일까요?',ARRAY['K3-2-u5-X14','K3-2-u5-X16']::text[],false,'{"seq":25,"concept":"K3-2-u5-C15","difficulty":4,"kind":"mc","stem":"「공, 던지다, 빠르다, 운동장」을 어떤 기준으로 나누었더니 「공 / 던지다, 빠르다, 운동장」이 되었어요. 나눈 기준은 무엇일까요?","options":[{"t":"한 글자 낱말인가","correct":true},{"t":"낱말의 종류","mis":"K3-2-u5-X14"},{"t":"형태가 바뀌는 부분이 있는가","mis":"K3-2-u5-X16"}],"explanation":["낱말의 종류로 나누면 세 칸이 돼요.","형태가 바뀌는가로 나누면 「공, 운동장 / 던지다, 빠르다」가 돼요.","「공」만 한 글자이니 기준은 「한 글자 낱말인가」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#1','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C23',1,'match','auto','『국어』 241쪽 3번이에요. 『국어』 238쪽에 나온 낱말과 국어사전에서 찾은 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C23","difficulty":1,"kind":"match","stem":"『국어』 241쪽 3번이에요. 『국어』 238쪽에 나온 낱말과 국어사전에서 찾은 뜻을 알맞게 이으세요.","pairs":[{"l":"보건","r":"건강을 온전하게 잘 지킴."},{"l":"사흘","r":"세 날."},{"l":"얼","r":"정신의 줏대."},{"l":"깃들다","r":"감정, 생각, 노력 따위가 어리거나 스미다."}],"mis":"K3-2-u5-X25","explanation":["보건실은 건강을 지키도록 돕는 곳이에요.","「사흘」은 넷이 아니라 세 날이에요.","「깃든」은 기본형 「깃들다」로 찾았어요."],"asset":{"type":"passage","lines":["[그림] 보건실 문패 앞 — “‘보건’이 무슨 뜻일까?”","[그림] 가게 안내문 「○○월 ○○일부터 사흘 동안 쉽니다.」","   — “‘사흘’이 무슨 뜻일까?”","[그림] 박물관 「조상의 얼이 깃든 도자기」 — “얼? 깃든?”"],"title":"낱말의 뜻이 궁금했던 경험 — 『국어』 238쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#2','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C3',1,'ox','auto','「사랑」, 「행복」도 이름을 나타내는 낱말이에요.',ARRAY['K3-2-u5-X39']::text[],false,'{"seq":2,"concept":"K3-2-u5-C3","difficulty":1,"kind":"ox","stem":"「사랑」, 「행복」도 이름을 나타내는 낱말이에요.","answer":"O","reason_options":[{"t":"「행복이 가득하다」처럼 ‘무엇’ 자리에 들어가요.","correct":true},{"t":"눈에 보이지 않으니 이름을 나타내는 낱말이 될 수 없어요.","mis":"K3-2-u5-X39"}],"mis":"K3-2-u5-X39","explanation":["이름을 나타내는 낱말에는 눈에 보이지 않는 것도 있어요.","「사랑이 크다」, 「행복이 가득하다」처럼 ‘무엇’ 자리에 들어가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#3','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C5',1,'mc','auto','『국어』 225쪽 「그 밖의 주제」예요. 친구의 좋은 점을 성질이나 상태를 나타내는 낱말로 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":3,"concept":"K3-2-u5-C5","difficulty":1,"kind":"mc","stem":"『국어』 225쪽 「그 밖의 주제」예요. 친구의 좋은 점을 성질이나 상태를 나타내는 낱말로 말한 것은 무엇인가요?","options":[{"t":"친절하다","correct":true},{"t":"달리다","mis":"K3-2-u5-X05"},{"t":"필통","mis":"K3-2-u5-X04"},{"t":"노래하다","mis":"K3-2-u5-X05"}],"explanation":["「내 친구는 친절하다」처럼 ‘어떠하다’ 자리에 들어가요.","달리다·노래하다는 움직임이에요.","필통은 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#4','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C9',1,'sa','auto','형태를 바꾸는 말놀이에서 「설레서, 설레니, 설레면」이 나왔어요. 형태가 바뀌지 않는 부분을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u5-C9","difficulty":1,"kind":"sa","stem":"형태를 바꾸는 말놀이에서 「설레서, 설레니, 설레면」이 나왔어요. 형태가 바뀌지 않는 부분을 쓰세요.","answer":["설레"],"explanation":["세 낱말에 모두 든 부분을 찾아요.","「서·니·면」이 바뀌는 부분이에요.","형태가 바뀌지 않는 부분은 「설레」이고 기본형은 「설레다」예요."],"mis":"K3-2-u5-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#5','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C12',1,'match','auto','『국어』 229쪽 (3)이에요. 형태가 바뀐 낱말과 그 기본형을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u5-C12","difficulty":1,"kind":"match","stem":"『국어』 229쪽 (3)이에요. 형태가 바뀐 낱말과 그 기본형을 알맞게 이으세요.","pairs":[{"l":"잡고, 잡아서, 잡으니","r":"잡다"},{"l":"매고, 매서, 매니","r":"매다"},{"l":"짧고, 짧아서, 짧으니","r":"짧다"}],"mis":"K3-2-u5-X11","explanation":["먼저 형태가 바뀌지 않는 부분을 찾아요 — 잡, 매, 짧.","바뀌지 않는 부분에 ‘-다’를 붙여요.","기본형은 잡다, 매다, 짧다예요."],"asset":{"type":"passage","lines":["낮고 · 낮아서 · 낮으니 · 낮으면 → 낮 → 낮다","잡고 · 잡아서 · 잡으니 · 잡으면 → (   ) → (   )","매고 · 매서 · 매니 · 매면 → (   ) → (   )","짧고 · 짧아서 · 짧으니 · 짧으면 → (   ) → (   )"],"title":"낱말의 기본형 만들기 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#6','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C18',1,'mc','auto','국어사전에서 「친구」를 찾으려고 해요. 가장 먼저 펼칠 곳은 어디인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X18']::text[],false,'{"seq":6,"concept":"K3-2-u5-C18","difficulty":1,"kind":"mc","stem":"국어사전에서 「친구」를 찾으려고 해요. 가장 먼저 펼칠 곳은 어디인가요?","options":[{"t":"ㅊ으로 시작하는 낱말이 모인 곳","correct":true},{"t":"ㄱ으로 시작하는 낱말이 모인 곳","mis":"K3-2-u5-X19"},{"t":"ㄴ으로 시작하는 낱말이 모인 곳","mis":"K3-2-u5-X18"}],"explanation":["첫 번째 글자 「친」의 첫 자음자를 봐요.","「친」은 ㅊ · ㅣ · ㄴ으로 이루어져요.","그래서 ㅊ으로 시작하는 곳을 먼저 펴요."],"asset":{"type":"passage","lines":["① 먼저 첫 번째 글자인 ‘친’을 찾아야 해.","② 첫 자음자인 (   )으로 시작하는 낱말은 여기에 모여 있어.","③ ‘층’으로 시작하는 낱말들이네. 더 뒤로 가야 해. ‘ㅊ’ 다음 모음자는 (   )야.","④ ‘치’로 시작하는 낱말들이네. 이제 받침 (   )을 찾아보자.","   여기는 ‘칙’이니까 다음에 곧 나오겠다.","⑤ 여기 있다! 이제 두 번째 글자인 ‘구’의 첫 자음자 ‘ㄱ’을 찾으면 돼.","⑥ 다음 모음자 (   )가 나올 때까지……. 찾았다!"],"title":"국어사전에서 ‘친구’ 찾기 — 『국어』 240쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#7','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C23',1,'mc','auto','『국어』 241쪽이에요. 국어사전에서 찾은 ‘깃들다’의 뜻은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":7,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"『국어』 241쪽이에요. 국어사전에서 찾은 ‘깃들다’의 뜻은 무엇인가요?","options":[{"t":"감정, 생각, 노력 따위가 어리거나 스미다.","correct":true},{"t":"새가 둥지를 떠나다.","mis":"K3-2-u5-X25"},{"t":"깃털이 빠져 떨어지다.","mis":"K3-2-u5-X25"}],"explanation":["‘깃든’은 형태가 바뀐 낱말이라 ‘깃들다’를 찾았어요.","‘깃들다’는 「감정, 생각, 노력 따위가 어리거나 스미다.」예요.","「조상의 얼이 깃든 도자기」는 조상의 정신이 담긴 도자기예요."],"asset":{"type":"passage","lines":["보건 — 건강을 온전하게 잘 지킴.","사흘 — 세 날.","얼 — 정신의 줏대.","깃들다 — 감정, 생각, 노력 따위가 어리거나 스미다."],"title":"국어사전에서 찾은 뜻 — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#8','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C31',1,'mc','auto','「옷들을 계절별로 갈무리해 옷장에 넣었다.」에서 ‘갈무리’의 뜻은 무엇인가요?',ARRAY['K3-2-u5-X34']::text[],false,'{"seq":8,"concept":"K3-2-u5-C31","difficulty":1,"kind":"mc","stem":"「옷들을 계절별로 갈무리해 옷장에 넣었다.」에서 ‘갈무리’의 뜻은 무엇인가요?","options":[{"t":"물건 따위를 잘 정리함.","correct":true},{"t":"일의 끝맺음.","mis":"K3-2-u5-X34"},{"t":"물건을 잃어버림.","mis":"K3-2-u5-X34"}],"explanation":["옷을 계절별로 정리해 넣는 장면이에요.","‘갈무리’는 「물건 따위를 잘 정리함.」이에요.","‘일의 끝맺음’은 ‘마무리’의 뜻이에요."],"asset":{"type":"passage","lines":["나만의 낱말 사전 만들기를 거의 마무리했다.","옷들을 계절별로 갈무리해 옷장에 넣었다."],"title":"『국어』 252쪽 2번","hi":["마무리","갈무리"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#9','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C3',2,'mc','auto','『국어활동』 72쪽이에요. 그림 속 문장에서 이름을 나타내는 낱말(○ 표)끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X15']::text[],false,'{"seq":9,"concept":"K3-2-u5-C3","difficulty":2,"kind":"mc","stem":"『국어활동』 72쪽이에요. 그림 속 문장에서 이름을 나타내는 낱말(○ 표)끼리 묶은 것은 무엇인가요?","options":[{"t":"양말, 단추, 목도리, 장갑","correct":true},{"t":"두르다, 매다, 끼다","mis":"K3-2-u5-X04"},{"t":"따뜻하다, 짧다, 크다","mis":"K3-2-u5-X04"},{"t":"양말, 매다, 따뜻하다","mis":"K3-2-u5-X15"}],"explanation":["「이것은 양말이다」처럼 ‘무엇’ 자리에 들어가는 낱말을 찾아요.","두르다·매다·끼다는 움직임이에요.","따뜻하다·짧다·크다는 성질이나 상태예요."],"asset":{"type":"passage","lines":["외출 준비 시작!","양말을 신다. · 모자를 쓰다. · 단추가 크다.","목도리를 두르다. · 목도리가 길다. · 안경을 쓰다.","신발을 신다. · 신발 끈을 매다. · 신발 끈이 짧다.","장갑을 끼다. · 장갑이 따뜻하다. · 외출 준비 끝!","○ 이름 · □ 움직임 · △ 성질이나 상태"],"title":"그림 속 문장 — 『국어활동』 72쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#10','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C14',2,'ox','auto','낱말마다 들어갈 칸이 하나로 정해져 있어서, 낱말을 나눌 때 기준을 따로 정하지 않아도 돼요.',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":10,"concept":"K3-2-u5-C14","difficulty":2,"kind":"ox","stem":"낱말마다 들어갈 칸이 하나로 정해져 있어서, 낱말을 나눌 때 기준을 따로 정하지 않아도 돼요.","answer":"X","reason_options":[{"t":"같은 낱말도 기준에 따라 다른 칸에 들어가니 기준을 먼저 정해야 해요.","correct":true},{"t":"낱말마다 정해진 칸이 있으니 그 칸만 찾으면 돼요.","mis":"K3-2-u5-X14"}],"mis":"K3-2-u5-X14","explanation":["「웃다」는 종류로 나누면 움직임 칸이에요.","형태가 바뀌는가로 나누면 「슬프다」와 같은 칸이에요.","그래서 기준을 먼저 정해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#11','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C33',2,'sa','auto','「낱말을 먹는 아이」에서 ‘사랑’을 먹은 날, ‘나’의 입에서 나온 말이 모두 어떤 모양이 되었나요?','{}'::text[],false,'{"seq":11,"concept":"K3-2-u5-C33","difficulty":2,"kind":"sa","stem":"「낱말을 먹는 아이」에서 ‘사랑’을 먹은 날, ‘나’의 입에서 나온 말이 모두 어떤 모양이 되었나요?","answer":["하트","하트 모양"],"explanation":["‘사랑’을 먹은 날을 찾아요.","모든 사람을 안아 주고 싶었어요.","입에서 나온 말이 모두 하트 모양이 되었어요."],"asset":{"type":"passage","lines":["(간추림) 기쁨이라는 낱말을 먹은 날 — 무척 즐거웠고 쉴 새 없이 웃었다.","(간추림) 슬픔이라는 낱말을 먹은 날 — 너무 슬퍼서 울기만 했다.","하루는 사랑이라는 낱말을 먹었어. 그건 참 좋았어.","(간추림) 모든 사람을 안아 주고 싶었고, 말이 모두 하트 모양이 되었다.","(간추림) 분노를 먹은 날은 내내 화가 나고 기분이 안 좋았다.","(간추림) 두려움을 먹은 날은 하루 종일 무서웠다. 침대 밑에서 괴물까지 봤다."],"title":"「낱말을 먹는 아이」(마를레트 수니에르 글) 앞부분 — 『국어』 231~233쪽"},"mis":"K3-2-u5-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#12','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C20',2,'mc','auto','『국어』 240쪽 그림 속 낱말이에요. 「친가」와 「칙사」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X37']::text[],false,'{"seq":12,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"『국어』 240쪽 그림 속 낱말이에요. 「친가」와 「칙사」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?","options":[{"t":"칙사","correct":true},{"t":"친가","mis":"K3-2-u5-X37"},{"t":"정할 수 없다","mis":"K3-2-u5-X37"}],"explanation":["첫 자음자와 모음자가 같고 둘 다 받침이 있어요.","받침을 보면 「칙」은 ㄱ, 「친」은 ㄴ이에요.","ㄱ이 ㄴ보다 앞이니 「칙사」가 먼저예요."],"asset":{"type":"passage","lines":["[그림] 국어사전을 펼친 쪽에 보이는 낱말","층간 · 층수 · 치통 · 치하 · 칙사 · 친가 · 친교"],"title":"『국어』 240쪽 그림 속 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#13','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C22',2,'ox','auto','「먹었다」의 뜻이 궁금하면 국어사전에서 「먹었다」를 그대로 찾아야 해요.',ARRAY['K3-2-u5-X13']::text[],false,'{"seq":13,"concept":"K3-2-u5-C22","difficulty":2,"kind":"ox","stem":"「먹었다」의 뜻이 궁금하면 국어사전에서 「먹었다」를 그대로 찾아야 해요.","answer":"X","reason_options":[{"t":"국어사전에는 기본형만 실려 있으니 「먹다」를 찾아요.","correct":true},{"t":"국어사전에는 바뀐 모양도 모두 실려 있어요.","mis":"K3-2-u5-X13"}],"mis":"K3-2-u5-X13","explanation":["「먹었다」는 형태가 바뀐 낱말이에요.","형태가 바뀌는 낱말을 찾을 때에는 기본형을 찾아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#14','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C2',2,'ox','auto','글을 읽다가 모르는 낱말이 나오면 그 자리에서 바로 멈추고 국어사전부터 찾아야 해요.',ARRAY['K3-2-u5-X02']::text[],false,'{"seq":14,"concept":"K3-2-u5-C2","difficulty":2,"kind":"ox","stem":"글을 읽다가 모르는 낱말이 나오면 그 자리에서 바로 멈추고 국어사전부터 찾아야 해요.","answer":"X","reason_options":[{"t":"우선 뜻을 짐작하며 끝까지 읽고, 뒤에 국어사전으로 확인해요.","correct":true},{"t":"모르는 낱말이 있으면 한 줄도 더 읽을 수 없어요.","mis":"K3-2-u5-X02"}],"mis":"K3-2-u5-X02","explanation":["모르는 낱말에 표시만 하고 계속 읽어요.","앞뒤 내용을 살피며 뜻을 짐작해요.","다 읽은 뒤 국어사전에서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#15','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C34',2,'mc','auto','「아직도 미지의 세계는 남아 있다」 끝에서 글쓴이가 읽는 사람에게 묻는 것은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":15,"concept":"K3-2-u5-C34","difficulty":2,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」 끝에서 글쓴이가 읽는 사람에게 묻는 것은 무엇인가요?","options":[{"t":"여러분은 어떤 지도를 만들어 보고 싶은지","correct":true},{"t":"세계 지도를 몇 번 보았는지","mis":"K3-2-u5-X17"},{"t":"바다에 가 본 적이 있는지","mis":"K3-2-u5-X17"}],"explanation":["글의 마지막 부분을 다시 읽어요.","우주 지도, 사람 마음속 지도를 예로 들었어요.","여러분은 어떤 지도를 만들어 보고 싶은지 물었어요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#16','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C26',2,'mc','auto','『국어』 251쪽 「생활 속으로」예요. 실천할 다짐으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u5-X02']::text[],false,'{"seq":16,"concept":"K3-2-u5-C26","difficulty":2,"kind":"mc","stem":"『국어』 251쪽 「생활 속으로」예요. 실천할 다짐으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"모르는 낱말이 나오면 읽기를 그만두어야지.","correct":true},{"t":"우리 반 교실에는 어떤 낱말이 쓰여 있는지 살펴봐야지.","mis":"K3-2-u5-X02"},{"t":"뉴스를 듣다가 모르는 낱말이 나오면 국어사전에서 찾아봐야지.","mis":"K3-2-u5-X02"}],"explanation":["모르는 낱말이 나오면 짐작하고 국어사전으로 확인해요.","읽기를 그만두면 내용을 알 수 없어요.","생활 속에서 낱말을 살피고 국어사전을 활용해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리 반 교실에는 어떤 낱말이 쓰여 있는지 살펴봐야지."},{"who":"친구 2","text":"뉴스를 듣다가 모르는 낱말이 나오면 국어사전에서 찾아봐야지."},{"who":"친구 3","text":"책을 읽다가 모르는 낱말이 나오면 앞뒤 내용을 살펴 뜻을 짐작해 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#17','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C5',3,'sa','auto','「큰절하는 방법」의 「큰절하는 방법은 남자와 여자가 다릅니다.」에서 성질이나 상태를 나타내는 낱말을 찾아 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"K3-2-u5-C5","difficulty":3,"kind":"sa","stem":"「큰절하는 방법」의 「큰절하는 방법은 남자와 여자가 다릅니다.」에서 성질이나 상태를 나타내는 낱말을 찾아 쓰세요.","answer":["다릅니다","다르다"],"explanation":["‘무엇이 어떠하다’ 틀에 넣어 봐요.","「방법이 다르다」처럼 ‘어떠하다’ 자리에 들어가요.","「다릅니다」는 성질이나 상태를 나타내요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]},"mis":"K3-2-u5-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#18','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C12',3,'mc','auto','「큰절하는 방법」의 밑줄 그은 낱말 「포개어」의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11','K3-2-u5-X08']::text[],false,'{"seq":18,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"「큰절하는 방법」의 밑줄 그은 낱말 「포개어」의 기본형은 무엇인가요?","options":[{"t":"포개다","correct":true},{"t":"포개어다","mis":"K3-2-u5-X11"},{"t":"포다","mis":"K3-2-u5-X08"},{"t":"포개이다","mis":"K3-2-u5-X11"}],"explanation":["「포개어」는 「포개」와 「어」로 나눠요.","바뀌지 않는 부분 「포개」에 ‘-다’를 붙여요.","기본형은 「포개다」예요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#19','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C15',3,'error','auto','낱말 분류 릴레이를 마치고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X15']::text[],false,'{"seq":19,"concept":"K3-2-u5-C15","difficulty":3,"kind":"error","stem":"낱말 분류 릴레이를 마치고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"이안: 앞 친구와 기준이 다르게 나왔으니 앞 친구가 틀린 거야.","correct":true,"mis_target":"K3-2-u5-X16"},{"t":"서윤: 같은 낱말도 기준이 바뀌니까 다른 칸에 들어갔어.","mis":"K3-2-u5-X16"},{"t":"도겸: 새 기준을 외치니 낱말이 새롭게 묶였어.","mis":"K3-2-u5-X15"}],"explanation":["릴레이에서는 새 기준을 외칠 수 있어요.","기준이 다르면 분류 결과도 다를 수 있어요.","기준이 달라졌다고 앞 친구가 틀린 것은 아니에요."],"asset":{"type":"passage","lines":["① 모둠 친구들이 각자 다섯 개의 낱말을 카드에 쓴다.","② 모둠 친구들이 쓴 낱말 카드를 모두 모아 섞는다.","③ 첫 번째 학생이 카드 두 개를 양쪽에 놓으며 분류 기준을 말한다.","④ 다음 학생은 둘 가운데 하나를 고른다.","   선택 1. 낱말 한 개를 골라 앞선 분류 기준에 따라 분류하기","   선택 2. 낱말 한 개를 골라 새 분류 기준을 외치며 분류하기","⑤ 모든 낱말 카드를 분류할 때까지 돌아가며 계속한다."],"title":"낱말 분류 릴레이 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#20','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C21',3,'mc','auto','「너비, 시루, 나라, 겨레」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X20']::text[],false,'{"seq":20,"concept":"K3-2-u5-C21","difficulty":3,"kind":"mc","stem":"「너비, 시루, 나라, 겨레」를 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"겨레 → 나라 → 너비 → 시루","correct":true},{"t":"나라 → 너비 → 겨레 → 시루","mis":"K3-2-u5-X19"},{"t":"겨레 → 너비 → 나라 → 시루","mis":"K3-2-u5-X20"},{"t":"시루 → 너비 → 나라 → 겨레","mis":"K3-2-u5-X19"}],"explanation":["첫 자음자 차례 ㄱ → ㄴ → ㅅ으로 놓아요.","「나라」와 「너비」는 모음자 ㅏ가 ㅓ보다 앞이에요.","그래서 「겨레 → 나라 → 너비 → 시루」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#21','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C25',3,'ox','auto','국어사전마다 ‘미지’의 뜻풀이 말이 조금씩 다르면 그 가운데 하나는 틀린 거예요.',ARRAY['K3-2-u5-X27']::text[],false,'{"seq":21,"concept":"K3-2-u5-C25","difficulty":3,"kind":"ox","stem":"국어사전마다 ‘미지’의 뜻풀이 말이 조금씩 다르면 그 가운데 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"사전마다 말이 조금 달라도 뜻이 같으면 돼요.","correct":true},{"t":"뜻풀이 말이 다르면 하나는 틀린 사전이에요.","mis":"K3-2-u5-X27"}],"mis":"K3-2-u5-X27","explanation":["사전마다 뜻풀이를 하는 말은 조금씩 다를 수 있어요.","중요한 것은 뜻이 같은지예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#22','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C31',3,'mc','auto','「나와 또바기 함께 있어 주렴.」에서 ‘또바기’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X34']::text[],false,'{"seq":22,"concept":"K3-2-u5-C31","difficulty":3,"kind":"mc","stem":"「나와 또바기 함께 있어 주렴.」에서 ‘또바기’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"언제나 한결같이 꼭 그렇게","correct":true},{"t":"담은 것이 그릇에 넘치도록 많이","mis":"K3-2-u5-X34"},{"t":"어떤 일 끝에 더 나아가","mis":"K3-2-u5-X34"}],"explanation":["늘 함께 있어 달라는 마음이 담긴 문장이에요.","‘또바기’는 언제나 한결같이 꼭 그렇게라는 뜻이에요.","넘치도록 많이는 ‘안다미로’의 뜻이에요."],"asset":{"type":"passage","lines":["또바기 — 나와 또바기 함께 있어 주렴.","안다미로 — 쌀을 그릇에 안다미로 퍼 담았다.","이드거니 — 모처럼 이드거니 밥을 먹었다."],"title":"뜻을 알아 두면 좋은 우리말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#23','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C22',4,'essay','teacher','「큰절하는 방법」의 「포개어」를 국어사전에서 찾는 과정을 차례대로 쓰고, 찾은 뜻을 넣어 그 문장을 다시 풀어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u5-C22","difficulty":4,"kind":"essay","stem":"「큰절하는 방법」의 「포개어」를 국어사전에서 찾는 과정을 차례대로 쓰고, 찾은 뜻을 넣어 그 문장을 다시 풀어 쓰세요.","answer_guide":{"answer":"예: 과정 — 「포개어」는 형태가 바뀐 낱말이니 바뀌지 않는 부분 「포개」에 ‘-다’를 붙여 「포개다」로 바꾼다. 첫 번째 글자 「포」의 첫 자음자 ㅍ으로 시작하는 곳을 찾고 모음자 ㅗ를 찾는다. 두 번째 글자 「개」의 ㄱ, ㅐ를 찾으면 「포개다」가 나온다. 뜻 — 국어사전에서 찾은 뜻을 옮겨 쓴다. 풀어 쓰기 — 여자는 오른손을 왼손 위에 겹쳐 놓아 눈높이까지 든다.","scoring_points":["기본형 「포개다」로 바꾸어 찾는다고 썼는가","첫 자음자 → 모음자 → 두 번째 글자 차례로 찾는 과정을 썼는가","찾은 뜻을 넣어 문장을 알맞게 풀어 썼는가"]},"explanation":["형태가 바뀐 낱말은 기본형으로 찾아요.","글자의 짜임대로 차례차례 찾아요.","뜻을 넣어 다시 읽으면 글을 정확하게 이해할 수 있어요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#24','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C15',4,'essay','teacher','낱말 분류 릴레이를 한다고 생각해요. 「공, 던지다, 빠르다, 운동장, 즐겁다」로 첫 번째 기준과 두 번째 기준을 정해 각각 나눈 결과를 쓰고, 결과가 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C15","difficulty":4,"kind":"essay","stem":"낱말 분류 릴레이를 한다고 생각해요. 「공, 던지다, 빠르다, 운동장, 즐겁다」로 첫 번째 기준과 두 번째 기준을 정해 각각 나눈 결과를 쓰고, 결과가 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 첫 번째 기준 — 낱말의 종류: 공, 운동장 / 던지다 / 빠르다, 즐겁다. 두 번째 기준 — 형태가 바뀌는 부분이 있는가: 있는 낱말 — 던지다, 빠르다, 즐겁다 / 없는 낱말 — 공, 운동장. 달라진 점 — 처음에는 세 칸이었는데 두 번째에는 두 칸이 되었고, 던지다는 빠르다, 즐겁다와 같은 칸에 들어갔다.","scoring_points":["서로 다른 두 기준을 분명하게 정했는가","다섯 낱말을 각 기준에 맞게 빠짐없이 나누었는가","기준에 따라 칸의 수나 함께 묶인 낱말이 달라진 점을 썼는가"]},"explanation":["기준을 먼저 말하고 나눠요.","같은 낱말이라도 기준이 바뀌면 다른 칸에 들어가요.","기준이 다르면 분류 결과도 다를 수 있어요."],"asset":{"type":"passage","lines":["① 모둠 친구들이 각자 다섯 개의 낱말을 카드에 쓴다.","② 모둠 친구들이 쓴 낱말 카드를 모두 모아 섞는다.","③ 첫 번째 학생이 카드 두 개를 양쪽에 놓으며 분류 기준을 말한다.","④ 다음 학생은 둘 가운데 하나를 고른다.","   선택 1. 낱말 한 개를 골라 앞선 분류 기준에 따라 분류하기","   선택 2. 낱말 한 개를 골라 새 분류 기준을 외치며 분류하기","⑤ 모든 낱말 카드를 분류할 때까지 돌아가며 계속한다."],"title":"낱말 분류 릴레이 — 우리 반 활동 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_c#25','kor',3,2,'u5','','tb_g3_2_kor_u5_review_c','unit_review','K3-2-u5-C17',4,'mc','auto','「얼음, 어른, 여름」을 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X36','K3-2-u5-X20']::text[],false,'{"seq":25,"concept":"K3-2-u5-C17","difficulty":4,"kind":"mc","stem":"「얼음, 어른, 여름」을 국어사전에 나오는 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"어른 → 얼음 → 여름","correct":true},{"t":"얼음 → 어른 → 여름","mis":"K3-2-u5-X21"},{"t":"어른 → 여름 → 얼음","mis":"K3-2-u5-X36"},{"t":"여름 → 얼음 → 어른","mis":"K3-2-u5-X20"}],"explanation":["세 낱말 모두 첫 자음자는 ㅇ이에요. 「얼음」도 ㄹ이 아니라 ㅇ으로 찾아요.","「어」와 「얼」은 모음자 ㅓ가 같고, 받침 없는 「어」가 먼저예요.","모음자 ㅕ인 「여름」은 맨 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#1','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C23',1,'mc','auto','『국어』 241쪽이에요. 「조상의 얼이 깃든 도자기」에서 ‘얼’의 뜻은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":1,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"『국어』 241쪽이에요. 「조상의 얼이 깃든 도자기」에서 ‘얼’의 뜻은 무엇인가요?","options":[{"t":"정신의 줏대.","correct":true},{"t":"물이 얼어서 굳은 것.","mis":"K3-2-u5-X25"},{"t":"사람의 얼굴.","mis":"K3-2-u5-X25"},{"t":"나이가 많은 사람.","mis":"K3-2-u5-X25"}],"explanation":["‘얼’은 국어사전에 「정신의 줏대.」라고 실려 있어요.","「조상의 얼이 깃든」은 조상의 정신이 담겨 있다는 말이에요.","소리가 비슷한 다른 낱말과 헷갈리지 않아요."],"asset":{"type":"passage","lines":["보건 — 건강을 온전하게 잘 지킴.","사흘 — 세 날.","얼 — 정신의 줏대.","깃들다 — 감정, 생각, 노력 따위가 어리거나 스미다."],"title":"국어사전에서 찾은 뜻 — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#2','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C3',1,'mc','auto','『국어』 225쪽 「그 밖의 주제」예요. 교실에서 이름을 나타내는 낱말을 찾아 말할 때 알맞게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X15']::text[],false,'{"seq":2,"concept":"K3-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 225쪽 「그 밖의 주제」예요. 교실에서 이름을 나타내는 낱말을 찾아 말할 때 알맞게 말한 것은 무엇인가요?","options":[{"t":"칠판, 시계, 책상","correct":true},{"t":"앉다, 쓰다, 읽다","mis":"K3-2-u5-X04"},{"t":"밝다, 넓다, 조용하다","mis":"K3-2-u5-X04"},{"t":"칠판, 앉다, 밝다","mis":"K3-2-u5-X15"}],"explanation":["교실에서 볼 수 있는 것의 이름을 찾아요.","앉다·쓰다·읽다는 움직임, 밝다·넓다·조용하다는 성질이나 상태예요.","정한 종류에 맞는 낱말만 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#3','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C4',1,'mc','auto','『국어』 225쪽 말놀이에서 「움직임을 나타내는 낱말 · 운동장」으로 정했어요. 이어서 말하기에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05']::text[],false,'{"seq":3,"concept":"K3-2-u5-C4","difficulty":1,"kind":"mc","stem":"『국어』 225쪽 말놀이에서 「움직임을 나타내는 낱말 · 운동장」으로 정했어요. 이어서 말하기에 알맞은 낱말은 무엇인가요?","options":[{"t":"던지다","correct":true},{"t":"축구공","mis":"K3-2-u5-X04"},{"t":"넓다","mis":"K3-2-u5-X05"},{"t":"운동장","mis":"K3-2-u5-X04"}],"explanation":["정한 종류는 움직임을 나타내는 낱말이에요.","운동장에서 할 수 있는 움직임을 말해요.","「던지다」가 알맞아요."],"asset":{"type":"passage","lines":["① 이름, 움직임, 성질이나 상태를 나타내는 낱말 가운데 하나를 고른다.","② 상황을 정하고 “시작!”을 외치며 왼쪽이나 오른쪽을 가리킨다.","③ 가리킨 방향으로 한 사람씩 차례대로 낱말을 외친다.","[예] 이름을 나타내는 낱말 · 점심시간 → “젓가락.” “반찬.”","[예] 움직임을 나타내는 낱말 · 운동장 → “달리다.” “던지다.”"],"title":"낱말의 종류를 이용한 말놀이 — 『국어』 225쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#4','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C9',1,'sa','auto','『국어』 227쪽 2번이에요. 「먹고, 먹으니, 먹으면, 먹어서」에서 형태가 바뀌지 않는 부분을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u5-C9","difficulty":1,"kind":"sa","stem":"『국어』 227쪽 2번이에요. 「먹고, 먹으니, 먹으면, 먹어서」에서 형태가 바뀌지 않는 부분을 쓰세요.","answer":["먹"],"explanation":["네 낱말에 빠짐없이 든 부분을 찾아요.","「고·으니·으면·어서」가 바뀌는 부분이에요.","형태가 바뀌지 않는 부분은 「먹」이에요."],"asset":{"type":"passage","lines":["동생이 밥을 먹고 이를 닦았다.","동생이 밥을 먹으니 이제 나도 먹을 수 있겠다.","동생이 밥을 먹으면 좋겠다.","동생이 밥을 먹어서 기분이 좋다."],"title":"『국어』 227쪽 2번 ①","hi":["먹고","먹으니","먹으면","먹어서"]},"mis":"K3-2-u5-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#5','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C12',1,'mc','auto','『국어』 229쪽 「높아서, 높고, 높으니, 높으면」의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":5,"concept":"K3-2-u5-C12","difficulty":1,"kind":"mc","stem":"『국어』 229쪽 「높아서, 높고, 높으니, 높으면」의 기본형은 무엇인가요?","options":[{"t":"높다","correct":true},{"t":"높아다","mis":"K3-2-u5-X11"},{"t":"높으다","mis":"K3-2-u5-X11"},{"t":"높아서다","mis":"K3-2-u5-X11"}],"explanation":["바뀌지 않는 부분은 「높」이에요.","「높」에 ‘-다’를 붙여요.","기본형은 「높다」예요."],"asset":{"type":"passage","lines":["① 낱말의 형태가 바뀌지 않는 부분과 바뀌는 부분을 나눠요.","   높아서 · 높고 · 높으니 · 높으면 → 높 / 아서 · 고 · 으니 · 으면","② 낱말의 형태가 바뀌지 않는 부분에 ‘-다’를 붙여요. → 높다","낱말의 기본형 완성!"],"title":"낱말의 기본형을 만드는 방법 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#6','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C17',1,'sa','auto','『국어』 239쪽이에요. 글자 「교」를 짜임대로 나눌 때 모음자를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u5-C17","difficulty":1,"kind":"sa","stem":"『국어』 239쪽이에요. 글자 「교」를 짜임대로 나눌 때 모음자를 쓰세요.","answer":["ㅛ"],"explanation":["「교」는 첫 자음자와 모음자로 이루어져요.","첫 자음자는 ㄱ, 모음자는 ㅛ예요.","「교」에는 받침이 없어요."],"mis":"K3-2-u5-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#7','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C2',1,'mc','auto','모르는 낱말의 뜻을 알 수 있는 방법을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X01','K3-2-u5-X03','K3-2-u5-X02']::text[],false,'{"seq":7,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"모르는 낱말의 뜻을 알 수 있는 방법을 바르게 모은 것은 무엇인가요?","options":[{"t":"국어사전 찾기, 어른께 여쭈어보기, 인터넷 검색하기","correct":true},{"t":"모르는 낱말 건너뛰기, 글 덮기","mis":"K3-2-u5-X01"},{"t":"짐작만 하고 확인하지 않기","mis":"K3-2-u5-X03"},{"t":"모르는 낱말이 나오면 읽기 그만두기","mis":"K3-2-u5-X02"}],"explanation":["뜻을 모를 때 알아보는 방법은 여러 가지예요.","국어사전 찾기, 어른께 여쭈어보기, 인터넷 검색이 있어요.","글 속에서 뜻을 짐작해 볼 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#8','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C30',1,'mc','auto','『국어』 252쪽 1번이에요. 「눈요기」는 어떻게 소리 나나요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":8,"concept":"K3-2-u5-C30","difficulty":1,"kind":"mc","stem":"『국어』 252쪽 1번이에요. 「눈요기」는 어떻게 소리 나나요?","options":[{"t":"[눈뇨기]","correct":true},{"t":"[누뇨기]","mis":"K3-2-u5-X32"},{"t":"[눈요기]","mis":"K3-2-u5-X32"}],"explanation":["받침 ㄴ 뒤에 「요」가 왔어요.","‘ㄴ’ 소리가 더해져 [눈뇨기]로 소리 나요.","앞 글자 받침 ㄴ도 그대로 소리 나요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#9','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C10',2,'mc','auto','「맛있는 사과를 먹었다.」의 「먹었다」가 형태가 바뀐 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X09','K3-2-u5-X12','K3-2-u5-X13']::text[],false,'{"seq":9,"concept":"K3-2-u5-C10","difficulty":2,"kind":"mc","stem":"「맛있는 사과를 먹었다.」의 「먹었다」가 형태가 바뀐 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"움직임을 나타내는 낱말이라 문장에서 쓰임에 따라 형태가 바뀌어서","correct":true},{"t":"이름을 나타내는 낱말이라서","mis":"K3-2-u5-X09"},{"t":"틀린 말이라서","mis":"K3-2-u5-X12"},{"t":"사전에 「먹었다」로 실려 있어서","mis":"K3-2-u5-X13"}],"explanation":["「먹었다」는 「먹다」가 문장에 맞게 바뀐 모양이에요.","움직임과 성질이나 상태를 나타내는 낱말은 형태가 바뀌어요.","바뀐 모양도 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#10','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C14',2,'mc','auto','「축구공, 운동장, 친구 / 뛰다, 차다, 마시다 / 맛있다, 길다, 빠르다」로 나누었어요. 나눈 기준은 무엇인가요?',ARRAY['K3-2-u5-X15','K3-2-u5-X16']::text[],false,'{"seq":10,"concept":"K3-2-u5-C14","difficulty":2,"kind":"mc","stem":"「축구공, 운동장, 친구 / 뛰다, 차다, 마시다 / 맛있다, 길다, 빠르다」로 나누었어요. 나눈 기준은 무엇인가요?","options":[{"t":"낱말의 종류","correct":true},{"t":"낱말의 글자 수","mis":"K3-2-u5-X15"},{"t":"낱말의 첫 자음자","mis":"K3-2-u5-X15"},{"t":"형태가 바뀌는 부분이 있는가","mis":"K3-2-u5-X16"}],"explanation":["첫 무리는 이름, 둘째 무리는 움직임, 셋째 무리는 성질이나 상태예요.","형태가 바뀌는가로 나누면 두 무리가 돼요.","그래서 기준은 낱말의 종류예요."],"asset":{"type":"passage","lines":["‘……에 가면’ 놀이 — 운동장, 축구공, 자전거, 학교, 친구","‘그리고 뭐 했어?’ 놀이 — 뛰다, 차다, 마시다, 먹다, 던지다","‘……은/는 어때?’ 놀이 — 맛있다, 길다, 빠르다, 뜨겁다, 즐겁다"],"title":"세 놀이에서 쓴 낱말 — 『국어』 222~223쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#11','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C33',2,'mc','auto','「낱말을 먹는 아이」에서 낱말을 모두 먹은 ‘나’가 「배가 부르고 행복했어.」라고 한 것은 무슨 뜻일까요?',ARRAY['K3-2-u5-X40']::text[],false,'{"seq":11,"concept":"K3-2-u5-C33","difficulty":2,"kind":"mc","stem":"「낱말을 먹는 아이」에서 낱말을 모두 먹은 ‘나’가 「배가 부르고 행복했어.」라고 한 것은 무슨 뜻일까요?","options":[{"t":"모든 낱말과 감정을 받아들여 마음이 가득 찬 느낌이 들었다는 뜻","correct":true},{"t":"음식을 정말 많이 먹어서 배가 불렀다는 뜻","mis":"K3-2-u5-X40"},{"t":"초콜릿을 먹어서 행복했다는 뜻","mis":"K3-2-u5-X40"}],"explanation":["‘나’는 낱말을 먹지 않았을 때 마음이 텅 빈 것 같았어요.","모든 낱말을 먹자 마음이 꽉 찬 것처럼 느꼈어요.","‘배가 부르다’, ‘초콜릿을 양껏 먹은 것처럼’은 빗댄 표현이에요."],"asset":{"type":"passage","lines":["(간추림) 나는 입을 꼭 다물고 더 이상 아무 낱말도 먹지 않기로 결심했다.","(간추림) 웃지도 슬퍼하지도 못하고, 마음이 텅 빈 것 같았다.","그래서 나는 낱말을 모두 먹어 버리기로 했어.","(간추림) 배가 부르고 행복했다. 초콜릿을 양껏 먹은 것처럼.","(간추림) 어떤 날은 행복하면서도 두렵거나 슬프거나 화가 난다.","모든 낱말이 나를 도와주는 걸.","내 기분이 어떤지 내가 누구인지 잘 알 수 있도록."],"title":"「낱말을 먹는 아이」 뒷부분 — 『국어』 234~235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#12','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C21',2,'mc','auto','『국어』 240쪽 그림 속 낱말이에요. 「친가」와 「친교」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X22']::text[],false,'{"seq":12,"concept":"K3-2-u5-C21","difficulty":2,"kind":"mc","stem":"『국어』 240쪽 그림 속 낱말이에요. 「친가」와 「친교」 가운데에서 국어사전에 먼저 나오는 낱말은 무엇인가요?","options":[{"t":"친가","correct":true},{"t":"친교","mis":"K3-2-u5-X20"},{"t":"정할 수 없다","mis":"K3-2-u5-X22"}],"explanation":["첫 번째 글자 「친」이 같아요.","두 번째 글자를 보면 첫 자음자 ㄱ은 같고 모음자가 ㅏ와 ㅛ예요.","ㅏ가 ㅛ보다 앞이니 「친가」가 먼저예요."],"asset":{"type":"passage","lines":["[그림] 국어사전을 펼친 쪽에 보이는 낱말","층간 · 층수 · 치통 · 치하 · 칙사 · 친가 · 친교"],"title":"『국어』 240쪽 그림 속 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#13','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C22',2,'mc','auto','「큰절하는 방법」의 「머리를 숙입니다」에서 「숙입니다」의 뜻을 국어사전에서 찾으려면 어떤 낱말을 찾아야 하나요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11','K3-2-u5-X08']::text[],false,'{"seq":13,"concept":"K3-2-u5-C22","difficulty":2,"kind":"mc","stem":"「큰절하는 방법」의 「머리를 숙입니다」에서 「숙입니다」의 뜻을 국어사전에서 찾으려면 어떤 낱말을 찾아야 하나요?","options":[{"t":"숙이다","correct":true},{"t":"숙입니다","mis":"K3-2-u5-X23"},{"t":"숙입다","mis":"K3-2-u5-X11"},{"t":"숙다","mis":"K3-2-u5-X08"}],"explanation":["「숙입니다」는 형태가 바뀐 낱말이에요.","「숙이고, 숙이면, 숙입니다」에 모두 든 부분은 「숙이」예요.","「숙이」에 ‘-다’를 붙인 「숙이다」를 찾아요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#14','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C24',2,'mc','auto','「지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,」에서 ‘길잡이’의 뜻을 짐작한 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":14,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"「지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,」에서 ‘길잡이’의 뜻을 짐작한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"길을 안내해 주는 것","correct":true},{"t":"길을 막아서는 것","mis":"K3-2-u5-X25"},{"t":"길에서 잡은 물고기","mis":"K3-2-u5-X25"}],"explanation":["탐험하는 사람들에게 지도가 어떤 일을 했는지 생각해요.","지도는 가야 할 길을 알려 줘요.","‘길잡이’는 길을 안내해 주는 것이라고 짐작할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 인간은 잘 모르거나 알려지지 않은 세계에 대한 호기심에서 여행을 한다.","(간추림) 보물섬을 찾던 서양 사람들은 아메리카를 발견했고, 남극도 알려졌다.","(간추림) 그 뒤 바닷속 세상을 떠올렸고, 달에 가 보고 다른 행성도 관찰했다.","(간추림) 새로운 장소를 찾아 나서는 인간의 역사는 탐험과 도전의 역사다.","지도는 미지의 세계를 탐험해 온 인간들에게 좋은 길잡이였고,","탐험의 성과가 알알이 박혀 있는 결과물입니다.","이처럼 세상의 잘 모르는 곳을 구석구석 다닌 사람들 덕에","(간추림) 우리는 거의 완벽한 세계 지도를 가지게 되었다."],"title":"「아직도 미지의 세계는 남아 있다」(류재명) 앞부분 — 『국어』 242~243쪽","hi":["미지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#15','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C34',2,'mc','auto','「아직도 미지의 세계는 남아 있다」에서 많은 사람이 탐험을 거듭할수록 지도는 어떻게 되었나요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":15,"concept":"K3-2-u5-C34","difficulty":2,"kind":"mc","stem":"「아직도 미지의 세계는 남아 있다」에서 많은 사람이 탐험을 거듭할수록 지도는 어떻게 되었나요?","options":[{"t":"지도의 윤곽이 점점 더 또렷해졌다","correct":true},{"t":"지도가 점점 흐려졌다","mis":"K3-2-u5-X17"},{"t":"지도가 점점 작아졌다","mis":"K3-2-u5-X17"}],"explanation":["「많은 사람이 탐험을 거듭할수록」으로 시작하는 문장을 찾아요.","지도의 윤곽은 점점 더 또렷해졌어요.","탐험의 성과가 지도에 하나하나 담겼기 때문이에요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#16','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C29',2,'mc','auto','세 가지 단서로 낱말 놀이에서 짝의 낱말을 끝내 못 맞혔어요. 어떻게 하면 좋을까요?',ARRAY['K3-2-u5-X31','K3-2-u5-X29']::text[],false,'{"seq":16,"concept":"K3-2-u5-C29","difficulty":2,"kind":"mc","stem":"세 가지 단서로 낱말 놀이에서 짝의 낱말을 끝내 못 맞혔어요. 어떻게 하면 좋을까요?","options":[{"t":"짝과 함께 그 낱말을 국어사전에서 찾아보며 단서를 다시 살핀다","correct":true},{"t":"졌으니 놀이가 실패라고 생각한다","mis":"K3-2-u5-X31"},{"t":"다음에는 단서에 낱말을 그대로 적어 달라고 한다","mis":"K3-2-u5-X29"}],"explanation":["놀이는 이기려고 하는 것이 아니에요.","단서를 보며 낱말을 헤아려 보는 것이 목표예요.","못 맞힌 낱말은 사전에서 찾아보며 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#17','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C6',3,'error','auto','「큰절하는 방법」의 낱말을 분류하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":17,"concept":"K3-2-u5-C6","difficulty":3,"kind":"error","stem":"「큰절하는 방법」의 낱말을 분류하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하은: 「다릅니다」는 ‘-ㅂ니다’로 끝나니 움직임을 나타내.","correct":true,"mis_target":"K3-2-u5-X05"},{"t":"준호: 「한복」은 ‘무엇’ 자리에 들어가니 이름을 나타내.","mis":"K3-2-u5-X04"},{"t":"세아: 「올립니다」는 ‘어찌하다’ 자리에 들어가니 움직임을 나타내.","mis":"K3-2-u5-X05"}],"explanation":["끝이 같다고 종류가 같은 것은 아니에요.","「방법이 다르다」처럼 「다릅니다」는 ‘어떠하다’ 자리에 들어가요.","「다릅니다」는 성질이나 상태를 나타내요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#18','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C22',3,'mc','auto','「큰절하는 방법」의 「입고, 짚고, 포개어」의 뜻을 국어사전에서 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X23','K3-2-u5-X12']::text[],false,'{"seq":18,"concept":"K3-2-u5-C22","difficulty":3,"kind":"mc","stem":"「큰절하는 방법」의 「입고, 짚고, 포개어」의 뜻을 국어사전에서 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「입다, 짚다, 포개다」처럼 기본형으로 바꾼 뒤 찾는다","correct":true},{"t":"「입고, 짚고, 포개어」를 그대로 찾는다","mis":"K3-2-u5-X23"},{"t":"바뀐 모양은 틀린 말이니 먼저 고쳐 쓴다","mis":"K3-2-u5-X12"}],"explanation":["세 낱말 모두 형태가 바뀐 낱말이에요.","국어사전에는 기본형만 실려 있어요.","기본형으로 바꾼 뒤 찾아요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#19','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C15',3,'mc','auto','「꽃샘잎샘, 소나기밥, 달마중, 한추위」를 계절로 나누면 네 칸이에요. 글자 수로 나누면 몇 칸이 되나요?',ARRAY['K3-2-u5-X16']::text[],false,'{"seq":19,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"「꽃샘잎샘, 소나기밥, 달마중, 한추위」를 계절로 나누면 네 칸이에요. 글자 수로 나누면 몇 칸이 되나요?","options":[{"t":"두 칸(네 글자 / 세 글자)","correct":true},{"t":"네 칸","mis":"K3-2-u5-X16"},{"t":"한 칸","mis":"K3-2-u5-X16"}],"explanation":["꽃샘잎샘·소나기밥은 네 글자, 달마중·한추위는 세 글자예요.","글자 수로 나누면 두 칸이 돼요.","같은 낱말도 기준이 바뀌면 결과가 달라져요."],"asset":{"type":"passage","lines":["[낱말] 봄 — 봄뜻 · 꽃샘잎샘 · 솜병아리 · 새털구름","[낱말] 여름 — 소나기밥 · 서늘맞이 · 여름심기 · 잠방잠방","[낱말] 가을 — 가을하다 · 달마중 · 땅거미 · 어우렁더우렁","[낱말] 겨울 — 눈구름 · 한추위 · 겨우살이 · 한올지다"],"title":"「사계절 우리말 사전」(신소영 글)에 나오는 낱말 — 『국어활동』 76~83쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#20','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C18',3,'mc','auto','『국어활동』 75쪽 ㉰의 「한파」를 국어사전에서 찾는 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X22','K3-2-u5-X18']::text[],false,'{"seq":20,"concept":"K3-2-u5-C18","difficulty":3,"kind":"mc","stem":"『국어활동』 75쪽 ㉰의 「한파」를 국어사전에서 찾는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"ㅎ → ㅏ → 받침 ㄴ → 두 번째 글자 ㅍ → ㅏ","correct":true},{"t":"ㅍ → ㅏ → ㅎ → ㅏ → 받침 ㄴ","mis":"K3-2-u5-X22"},{"t":"ㅎ → 받침 ㄴ → ㅏ → ㅍ → ㅏ","mis":"K3-2-u5-X18"}],"explanation":["첫 번째 글자 「한」부터 찾아요.","첫 자음자 ㅎ → 모음자 ㅏ → 받침 ㄴ 차례예요.","그다음 두 번째 글자 「파」를 같은 방법으로 찾아요."],"asset":{"type":"passage","lines":["㉮ 너비 · 시루","㉯ 고요 · 겨레 · 구기","㉰ 한과 · 학문 · 하교 · 한파"],"title":"『국어활동』 75쪽 2번 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#21','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C26',3,'mc','auto','『국어』 246쪽 (2)예요. 친구들이 말한 국어사전을 활용해 글을 읽으면 좋은 점 두 가지를 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u5-X28','K3-2-u5-X01']::text[],false,'{"seq":21,"concept":"K3-2-u5-C26","difficulty":3,"kind":"mc","stem":"『국어』 246쪽 (2)예요. 친구들이 말한 국어사전을 활용해 글을 읽으면 좋은 점 두 가지를 바르게 묶은 것은 무엇인가요?","options":[{"t":"어려운 낱말의 뜻을 알아 글을 정확하게 이해할 수 있다 · 내가 짐작한 내용이 맞는지 확인할 수 있다","correct":true},{"t":"글을 빨리 읽을 수 있다 · 짐작하지 않아도 된다","mis":"K3-2-u5-X28"},{"t":"모르는 낱말을 건너뛰어도 된다 · 글을 덜 읽어도 된다","mis":"K3-2-u5-X01"}],"explanation":["낱말의 뜻을 알면 글을 정확하게 이해할 수 있어요.","짐작한 뜻을 사전에서 확인할 수 있어요.","빨리 읽으려고 사전을 쓰는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#22','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C30',3,'mc','auto','「눈요기」가 [눈뇨기]로 소리 나는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":22,"concept":"K3-2-u5-C30","difficulty":3,"kind":"mc","stem":"「눈요기」가 [눈뇨기]로 소리 나는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"앞 글자에 받침 ㄴ이 있고 뒤 글자가 ‘요’로 시작해서","correct":true},{"t":"마지막 글자가 ‘기’라서","mis":"K3-2-u5-X32"},{"t":"‘눈’이 한 글자라서","mis":"K3-2-u5-X32"}],"explanation":["받침이 있는지, 뒤 글자가 ‘이, 야, 여, 요, 유’인지 봐요.","「눈」은 받침 ㄴ이 있고 「요」가 뒤에 와요.","그래서 ‘ㄴ’ 소리가 더해져 [눈뇨기]로 소리 나요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤엔 추워서 두꺼운 솜이불을 꺼냈어."},{"who":"친구 2","text":"[솜니불]로 들리네. 담요를 덮는 건 어때?"},{"who":"친구 1","text":"[담뇨]로 들려."},{"who":"친구 3","text":"아침에 속이 안 좋아서 맨입에 물만 마셨어."},{"who":"친구 4","text":"[맨닙]! 반찬이 있어도 눈요기만 했겠구나."},{"who":"친구 3","text":"[눈뇨기]!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#23','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C13',4,'mc','auto','「여자는 오른손을 왼손 위에 포개어 눈높이까지 들고」의 「포개어」에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13']::text[],false,'{"seq":23,"concept":"K3-2-u5-C13","difficulty":4,"kind":"mc","stem":"「여자는 오른손을 왼손 위에 포개어 눈높이까지 들고」의 「포개어」에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"문장에 맞게 형태가 바뀐 바른 말이고, 국어사전에서는 「포개다」로 찾는다","correct":true},{"t":"국어사전에 없으니 틀린 말이다","mis":"K3-2-u5-X12"},{"t":"국어사전에 「포개어」로 실려 있으니 그대로 찾는다","mis":"K3-2-u5-X13"},{"t":"바르게 쓰려면 「포개다」로 고쳐 「오른손을 왼손 위에 포개다 눈높이까지 들고」로 써야 한다","mis":"K3-2-u5-X12"}],"explanation":["「포개어」는 문장에 알맞게 형태가 바뀐 말이에요.","사전에 기본형만 실린다고 바뀐 모양이 틀린 말은 아니에요.","뜻을 찾을 때에는 기본형 「포개다」로 찾아요."],"asset":{"type":"passage","lines":["집안에 특별한 행사가 있거나 차례를 지낼 때 한복을 입고 큰절을 합니다.","큰절하는 방법은 남자와 여자가 다릅니다.","남자는 공수 자세로 손을 눈높이까지 올립니다.","그리고 몸을 굽히며 손을 앞으로 내려 방바닥을 짚고 절을 합니다.","여자는 오른손을 왼손 위에 포개어 눈높이까지 들고 머리를 숙입니다.","(간추림) 몸을 서서히 낮추어 앉았다가 머리를 숙인 뒤 일어섭니다."],"title":"「큰절하는 방법」 (평가 글)","hi":["입고","짚고","포개어"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#24','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C2',4,'essay','teacher','『국어』 251쪽 「생활 속으로」처럼, 이 단원에서 공부한 내용을 생활 속에서 어떻게 실천할지 쓰세요. 국어사전이 필요했던 경험이나 필요할 때를 하나 쓰고, 그때 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C2","difficulty":4,"kind":"essay","stem":"『국어』 251쪽 「생활 속으로」처럼, 이 단원에서 공부한 내용을 생활 속에서 어떻게 실천할지 쓰세요. 국어사전이 필요했던 경험이나 필요할 때를 하나 쓰고, 그때 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 경험 — 박물관 안내서에서 「출토」라는 낱말을 보고 무슨 뜻인지 몰라 내용을 잘 알 수 없었다. 실천 — 앞으로는 모르는 낱말에 표시하고 앞뒤 내용을 살펴 뜻을 짐작한 뒤, 국어사전에서 찾아 확인하고 다시 읽겠다. 교실에 쓰여 있는 낱말도 살펴보겠다.","scoring_points":["국어사전이 필요했던 경험이나 필요한 때를 썼는가","짐작하고 국어사전으로 확인하는 방법을 썼는가","생활 속에서 실천할 다짐을 구체적으로 썼는가"]},"explanation":["생활 속에서 많이 쓰지만 뜻을 잘 몰랐던 낱말을 떠올려요.","모르는 낱말은 짐작하고 국어사전으로 확인해요.","국어사전을 활용하는 습관을 들여요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리 반 교실에는 어떤 낱말이 쓰여 있는지 살펴봐야지."},{"who":"친구 2","text":"뉴스를 듣다가 모르는 낱말이 나오면 국어사전에서 찾아봐야지."},{"who":"친구 3","text":"책을 읽다가 모르는 낱말이 나오면 앞뒤 내용을 살펴 뜻을 짐작해 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u5_review_d#25','kor',3,2,'u5','','tb_g3_2_kor_u5_review_d','unit_review','K3-2-u5-C25',4,'mc','auto','‘표면’을 「종이의 앞면」으로 짐작했다가 국어사전에서 「사물의 가장 바깥쪽」을 찾고 글을 다시 읽었어요. 다시 읽고 알게 된 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X26','K3-2-u5-X02']::text[],false,'{"seq":25,"concept":"K3-2-u5-C25","difficulty":4,"kind":"mc","stem":"‘표면’을 「종이의 앞면」으로 짐작했다가 국어사전에서 「사물의 가장 바깥쪽」을 찾고 글을 다시 읽었어요. 다시 읽고 알게 된 것으로 알맞은 것은 무엇인가요?","options":[{"t":"사람들의 관심이 땅의 겉에서 땅속으로 옮겨 갔다는 내용","correct":true},{"t":"짐작이 빗나갔으니 이 글은 어려워서 읽을 수 없다는 것","mis":"K3-2-u5-X26"},{"t":"앞으로는 모르는 낱말마다 멈추어 사전을 찾아야 한다는 것","mis":"K3-2-u5-X02"}],"explanation":["짐작이 빗나가도 사전으로 바로잡을 수 있어요.","바른 뜻을 넣어 읽으면 땅 위에서 땅속으로 관심이 넓어졌다는 내용이 보여요.","짐작과 사전의 뜻이 다를 때 국어사전의 쓸모를 느낄 수 있어요."],"asset":{"type":"passage","lines":["많은 사람이 탐험을 거듭할수록 지도의 윤곽은 점점 더 또렷해졌습니다.","(간추림) 지구에 대한 지식이 쌓이자 사람들은 더 전문적인 분야로 관심을 돌렸다.","육지 표면이 아니라 땅속에 대해 관심을 갖기 시작한 거죠.","(간추림) 지하자원이 중요해져 답사와 연구 끝에 땅속 암석에 대한 지도를 만들었다.","(간추림) 바다 탐험은 비싼 장비가 많이 필요해 선진국이 중심이 되었다.","(간추림) 해저 지도, 해류의 흐름 지도, 수온의 분포 지도를 만들었다.","(간추림) 앞으로 어떤 지도를 만들까? 우주 지도? 사람 마음속 지도?"],"title":"「아직도 미지의 세계는 남아 있다」 뒷부분 — 『국어』 243~245쪽","hi":["표면"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
